insert into public.book_templates (key, name, description, config) values ('prayer_manual', 'Prayer manual', 'Parts and sections of numbered prayers with scripture, checked off one by one (like the Book of Covenant Prayers).', $json${"reader":"prayer","levels":[{"name":"Part","show_titles":true},{"name":"Section","show_titles":true}],"content":["prayer","foundation"],"check_on":"item","numbering":"nested","actions_on":"level-2","schedule":"fixed","features":{"focus":true,"listen":true,"plans":true,"scripture":true,"verse_popups":true,"notes":true,"pen":true,"search":true,"share":true,"journal":true}}$json$::jsonb) on conflict (key) do nothing;
insert into public.book_templates (key, name, description, config) values ('watch_manual', 'Watch manual', 'Prayer watches with prayers numbered through each watch, plus name lists (like Jesus Chosen Fast and Prayer).', $json${"reader":"prayer","levels":[{"name":"Watch","show_titles":true},{"name":"Topic","show_titles":false}],"content":["prayer","names","embed"],"check_on":"item","numbering":"running","actions_on":"level-1","schedule":"fixed","features":{"focus":true,"listen":true,"plans":true,"scripture":true,"verse_popups":true,"notes":true,"pen":true,"search":true,"share":true,"journal":true}}$json$::jsonb) on conflict (key) do nothing;
insert into public.book_templates (key, name, description, config) values ('devotional', 'Devotional', 'Chapters of reading with highlights and notes (like Rooted).', $json${"reader":"reading","levels":[{"name":"Chapter","show_titles":true}],"content":["reading"],"check_on":"none","numbering":"none","actions_on":"level-1","schedule":"fixed","features":{"focus":false,"listen":true,"plans":false,"scripture":false,"verse_popups":true,"notes":true,"pen":true,"search":true,"share":false,"journal":false}}$json$::jsonb) on conflict (key) do nothing;
insert into public.book_templates (key, name, description, config) values ('weekly_series', 'Weekly series', 'Dated entries published over time, newest first (like the Weekly Kingdom Prayers).', $json${"reader":"prayer","levels":[{"name":"Week","show_titles":true}],"content":["prayer"],"check_on":"item","numbering":"nested","actions_on":"level-1","schedule":"dated","features":{"focus":true,"listen":true,"plans":false,"scripture":false,"verse_popups":false,"notes":false,"pen":false,"search":false,"share":true,"journal":false}}$json$::jsonb) on conflict (key) do nothing;
insert into public.books (slug, template, config, title, subtitle, author, cover, access, status, sort_hint) values ('covenant', 'prayer_manual', $json${"reader":"prayer","levels":[{"name":"Part","show_titles":true},{"name":"Section","show_titles":true}],"content":["prayer","foundation"],"check_on":"item","numbering":"nested","actions_on":"level-2","schedule":"fixed","features":{"focus":true,"listen":true,"plans":true,"scripture":true,"verse_popups":true,"notes":true,"pen":true,"search":true,"share":true,"journal":true}}$json$::jsonb, 'Book of Covenant Prayers', '', '', $json${"colors":["#25685d","#11372f","#d9c27e"]}$json$::jsonb, 'members', 'published', 1) on conflict (slug) do nothing;
insert into public.books (slug, template, config, title, subtitle, author, cover, access, status, sort_hint) values ('jcfp', 'watch_manual', $json${"reader":"prayer","levels":[{"name":"Watch","show_titles":true},{"name":"Topic","show_titles":false}],"content":["prayer","names","embed"],"check_on":"item","numbering":"running","actions_on":"level-1","schedule":"fixed","features":{"focus":true,"listen":true,"plans":true,"scripture":true,"verse_popups":true,"notes":true,"pen":true,"search":true,"share":true,"journal":true}}$json$::jsonb, 'Jesus Chosen Fast and Prayer Prayer Manual', '', '', $json${"colors":["#8e2d3a","#561620","#dcb86c"]}$json$::jsonb, 'free', 'published', 2) on conflict (slug) do nothing;
insert into public.books (slug, template, config, title, subtitle, author, cover, access, status, sort_hint) values ('weekly', 'weekly_series', $json${"reader":"prayer","levels":[{"name":"Week","show_titles":true}],"content":["prayer"],"check_on":"item","numbering":"nested","actions_on":"level-1","schedule":"dated","features":{"focus":true,"listen":true,"plans":false,"scripture":false,"verse_popups":false,"notes":false,"pen":false,"search":false,"share":true,"journal":false}}$json$::jsonb, 'GRA Weekly Kingdom Prayers', '', '', $json${"colors":["#33407a","#171d40","#e6c47a"]}$json$::jsonb, 'free', 'published', 0) on conflict (slug) do nothing;
insert into public.books (slug, template, config, title, subtitle, author, cover, access, status, sort_hint) values ('rooted', 'devotional', $json${"reader":"reading","levels":[{"name":"Chapter","show_titles":true}],"content":["reading"],"check_on":"none","numbering":"none","actions_on":"level-1","schedule":"fixed","features":{"focus":false,"listen":true,"plans":false,"scripture":false,"verse_popups":true,"notes":true,"pen":true,"search":true,"share":false,"journal":false}}$json$::jsonb, 'Rooted', 'Five readings on growing in Christ', 'Sample book', $json${"bg":"linear-gradient(105deg, rgba(255,255,255,.35), transparent 40%), #ece3cf","ink":"#24382c","accent":"#8a6a2f","sub":"#4d5b4f","solid":"#24382c"}$json$::jsonb, 'free', 'published', 10) on conflict (slug) do nothing;
insert into public.book_editions (book_slug, version, data, layout, note) values ('covenant', 0, $json$[{"label":"Part EIGHT","title":"GOD’S REMNANT ASSEMBLY WORLDWIDE","subtitle":"Prayers for the whole household of faith, its growth, unity, and every laborer within it","sections":[{"orig":44,"title":"Pleading the Blood of Jesus Over the Entire GRA Global Family","foundation":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"Acts 20:28","verses":[{"n":"28","text":"“Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood.”"}]},{"ref":"Ephesians 4:3","verses":[{"n":"3","text":"“Endeavouring to keep the unity of the Spirit in the bond of peace.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over the entire GRA Global family. Let the Blood of the everlasting covenant cover every church, every nation, every pastor, every minister, every worker, every missionary, every family, and every member.","scripture":[],"o":"s-8-1-1","o2":"s-8-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over GRA Global than every accusation, opposition, persecution, misunderstanding, discouragement, or attack of the enemy.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-8-1-2","o2":"s-8-1-2"},{"text":"Father, by the Blood of Jesus, preserve the unity, love, peace, holiness, purity, and spiritual strength of the entire GRA Global family.","scripture":[{"ref":"Ephesians 4:3","verses":[{"n":"3","text":"“Endeavouring to keep the unity of the Spirit in the bond of peace.”"}]}],"o":"s-8-1-3","o2":"s-8-1-3"},{"text":"Lord, let the Blood of Jesus protect every GRA church, ministry center, mission field, prayer center, fellowship, and gathering place from every work of darkness.","scripture":[{"ref":"Psalm 91:1","verses":[{"n":"1","text":"“He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.”"}]}],"o":"s-8-1-4","o2":"s-8-1-4"},{"text":"Father, by the Blood of Jesus, preserve our Father in the Lord, all pastors, ministers, elders, deacons, missionaries, teachers, evangelists, worship leaders, workers, and volunteers. Strengthen them to fulfill their calling with faithfulness and joy.","scripture":[{"ref":"Acts 20:28","verses":[{"n":"28","text":"“Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood.”"}]}],"o":"s-8-1-5","o2":"s-8-1-5"},{"text":"Lord Jesus, let the Blood of Jesus destroy every spirit of division, offense, bitterness, jealousy, pride, confusion, false doctrine, and discord within GRA Global.","scripture":[{"ref":"Romans 16:17","verses":[{"n":"17","text":"“Now I beseech you, brethren, mark them which cause divisions and offences contrary to the doctrine which ye have learned; and avoid them.”"}]}],"o":"s-8-1-6","o2":"s-8-1-6"},{"text":"Father, by the Blood of Jesus, preserve every GRA marriage, every child, every youth, every family, and every generation represented throughout the ministry.","scripture":[{"ref":"Isaiah 59:21","verses":[{"n":"21","text":"“As for me, this is my covenant with them, saith the LORD; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seed’s seed, saith the LORD, from henceforth and for ever.”"}]}],"o":"s-8-1-7","o2":"s-8-1-7"},{"text":"Lord, let the Blood of Jesus surround every missionary, evangelist, and minister traveling for the Gospel. Protect them by land, sea, and air wherever You send them.","scripture":[{"ref":"Psalm 121:8","verses":[{"n":"8","text":"“The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.”"}]}],"o":"s-8-1-8","o2":"s-8-1-8"},{"text":"Father, let the Blood of Jesus raise up faithful laborers, soul winners, intercessors, teachers, disciplers, and Kingdom builders throughout the entire GRA Global family.","scripture":[{"ref":"Matthew 9:38","verses":[{"n":"38","text":"“Pray ye therefore the Lord of the harvest, that he will send forth labourers into his harvest.”"}]}],"o":"s-8-1-9","o2":"s-8-1-9"},{"text":"Lord Jesus, by Your Blood, grant GRA Global continual revival, fresh anointing, spiritual renewal, and a greater hunger for Your presence and Your Word.","scripture":[{"ref":"Habakkuk 3:2","verses":[{"n":"2","text":"“O LORD, I have heard thy speech, and was afraid: O LORD, revive thy work in the midst of the years, in the midst of the years make known; in wrath remember mercy.”"}]}],"o":"s-8-1-10","o2":"s-8-1-10"},{"text":"Father, by the Blood of Jesus, establish every GRA assembly in sound doctrine, biblical truth, holiness, humility, and unwavering faithfulness to Christ.","scripture":[{"ref":"2 Timothy 1:13","verses":[{"n":"13","text":"“Hold fast the form of sound words, which thou hast heard of me, in faith and love which is in Christ Jesus.”"}]}],"o":"s-8-1-11","o2":"s-8-1-11"},{"text":"Lord, let the Blood of Jesus preserve every ministry assignment, outreach, conference, crusade, discipleship program, church planting effort, humanitarian work, and mission project undertaken by GRA Global.","scripture":[{"ref":"Matthew 28:19–20","verses":[{"n":"19","text":"“Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:"},{"n":"20","text":"Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.”"}]}],"o":"s-8-1-12","o2":"s-8-1-12"},{"text":"Father, by the Blood of Jesus, provide every financial, material, spiritual, and human resource necessary for the growth and effectiveness of GRA Global.","scripture":[{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]}],"o":"s-8-1-13","o2":"s-8-1-13"},{"text":"Lord Jesus, let the Blood of Jesus give GRA Global favor before governments, communities, churches, institutions, and nations according to Your perfect will, opening doors for the Gospel.","scripture":[{"ref":"Colossians 4:3","verses":[{"n":"3","text":"“Withal praying also for us, that God would open unto us a door of utterance, to speak the mystery of Christ, for which I am also in bonds:”"}]}],"o":"s-8-1-14","o2":"s-8-1-14"},{"text":"Father, by the Blood of Jesus, let every GRA church become a lighthouse of truth, prayer, holiness, worship, discipleship, missions, and compassionate service.","scripture":[{"ref":"Matthew 5:14","verses":[{"n":"14","text":"“Ye are the light of the world. A city that is set on an hill cannot be hid.”"}]}],"o":"s-8-1-15","o2":"s-8-1-15"},{"text":"Lord, by the Blood of Jesus, frustrate every plan of Satan against GRA Global. Let no weapon formed against this ministry prosper.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-8-1-16","o2":"s-8-1-16"},{"text":"Father, let the Blood of Jesus multiply souls, disciples, churches, missionaries, leaders, Kingdom partnerships, and mission opportunities throughout GRA Global.","scripture":[{"ref":"Acts 2:47","verses":[{"n":"47","text":"“Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved.”"}]}],"o":"s-8-1-17","o2":"s-8-1-17"},{"text":"Lord Jesus, by Your Blood, preserve GRA Global until the coming of Christ. Let every member remain faithful, steadfast, fruitful, and prepared for the return of the Lord.","scripture":[{"ref":"1 Corinthians 15:58","verses":[{"n":"58","text":"“Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.”"}]}],"o":"s-8-1-18","o2":"s-8-1-18"},{"text":"Father, let every member of the GRA Global family overcome every trial, temptation, persecution, and spiritual battle through the Blood of the Lamb and remain victorious in Christ.","scripture":[{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"o":"s-8-1-19","o2":"s-8-1-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus the entire GRA Global family is redeemed, sanctified, protected, united, strengthened, supplied, fruitful, and established for Your eternal glory. May every church, every member, every leader, every missionary, and every ministry assignment faithfully fulfill Your divine purpose until the glorious appearing of our Lord Jesus Christ.","scripture":[{"ref":"Ephesians 3:20–21","verses":[{"n":"20","text":"“Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,"},{"n":"21","text":"Unto him be glory in the church by Christ Jesus throughout all ages, world without end. Amen.”"}]}],"o":"s-8-1-20","o2":"s-8-1-20"}]},{"orig":45,"title":"Prayer for Mighty Blessings Upon the Entire GRA Family and for Grace Never to Forsake God","foundation":[{"ref":"Deuteronomy 28:2","verses":[{"n":"2","text":"“And all these blessings shall come on thee, and overtake thee, if thou shalt hearken unto the voice of the LORD thy God.”"}]},{"ref":"Numbers 6:24–26","verses":[{"n":"24","text":"“The LORD bless thee, and keep thee:"},{"n":"25","text":"The LORD make his face shine upon thee, and be gracious unto thee:"},{"n":"26","text":"The LORD lift up his countenance upon thee, and give thee peace.”"}]},{"ref":"Psalm 84:11","verses":[{"n":"11","text":"“For the LORD God is a sun and shield: the LORD will give grace and glory: no good thing will he withhold from them that walk uprightly.”"}]},{"ref":"John 6:67–69","verses":[{"n":"67","text":"“Then said Jesus unto the twelve, Will ye also go away?"},{"n":"68","text":"Then Simon Peter answered him, Lord, to whom shall we go? thou hast the words of eternal life."},{"n":"69","text":"And we believe and are sure that thou art that Christ, the Son of the living God.”"}]}],"prayers":[{"text":"Father, pour out Your richest spiritual, physical, and eternal blessings upon every member of the GRA family throughout the world according to Your perfect will.","scripture":[],"o":"s-8-2-1","o2":"s-8-2-1"},{"text":"Lord Jesus, bless every church, every family, every pastor, every minister, every missionary, every worker, every volunteer, every child, every youth, and every elder in GRA with Your abiding presence.","scripture":[],"o":"s-8-2-2","o2":"s-8-2-2"},{"text":"Father, bless us with a deeper knowledge of Christ, a greater love for Your Word, and an increasing hunger for prayer, holiness, and obedience.","scripture":[],"o":"s-8-2-3","o2":"s-8-2-3"},{"text":"Lord, bless every GRA home with peace, unity, joy, wisdom, forgiveness, and unwavering faith in You.","scripture":[],"o":"s-8-2-4","o2":"s-8-2-4"},{"text":"Father, bless us with sound health, renewed strength, divine protection, and long lives dedicated to Your service.","scripture":[],"o":"s-8-2-5","o2":"s-8-2-5"},{"text":"Lord Jesus, bless the work of our hands. Establish our professions, businesses, ministries, studies, and every righteous labor for Your glory.","scripture":[],"o":"s-8-2-6","o2":"s-8-2-6"},{"text":"Father, bless us with wisdom from above, understanding, discernment, excellence, humility, and faithful stewardship.","scripture":[],"o":"s-8-2-7","o2":"s-8-2-7"},{"text":"Lord, bless every GRA assembly with continual revival, genuine conversions, biblical discipleship, sound doctrine, and lasting spiritual fruit.","scripture":[],"o":"s-8-2-8","o2":"s-8-2-8"},{"text":"Father, bless our evangelism, missions, church planting, humanitarian work, and every Kingdom assignment with abundant success according to Your will.","scripture":[],"o":"s-8-2-9","o2":"s-8-2-9"},{"text":"Lord Jesus, bless us with faithful marriages, godly children, strong families, and generations that will love and serve You.","scripture":[],"o":"s-8-2-10","o2":"s-8-2-10"},{"text":"Father, bless us financially so that we may abound in generosity, support the preaching of the Gospel, care for the needy, and glorify Christ in all we possess.","scripture":[],"o":"s-8-2-11","o2":"s-8-2-11"},{"text":"Lord, bless us with favor before You and before men wherever it advances Your Kingdom and honors Your holy name.","scripture":[],"o":"s-8-2-12","o2":"s-8-2-12"},{"text":"Father, preserve every blessing You entrust to us from pride, selfish ambition, greed, complacency, and every snare of the enemy.","scripture":[],"o":"s-8-2-13","o2":"s-8-2-13"},{"text":"Lord Jesus, let no blessing ever become an idol in our hearts. May we always love the Giver more than the gifts.","scripture":[],"o":"s-8-2-14","o2":"s-8-2-14"},{"text":"Father, keep every member of GRA faithful to the end. Let none of us turn away from the Lord Jesus Christ through temptation, persecution, prosperity, disappointment, or the cares of this world.","scripture":[],"o":"s-8-2-15","o2":"s-8-2-15"},{"text":"Father, grant that every blessing You pour upon us will increase our humility, gratitude, compassion, generosity, and dependence upon You rather than self-confidence.","scripture":[],"o":"s-8-2-16","o2":"s-8-2-16"},{"text":"Lord Jesus, help us to finish our course with joy. Let every member of GRA remain faithful to the Gospel, sound in doctrine, holy in conduct, and fruitful in service throughout our lives.","scripture":[],"o":"s-8-2-17","o2":"s-8-2-17"},{"text":"Father, let the entire GRA family continually declare with Peter, “Lord, to whom shall we go? thou hast the words of eternal life.” Keep us from backsliding, compromise, deception, and every path that leads away from Christ.","scripture":[],"o":"s-8-2-18","o2":"s-8-2-18"},{"text":"Thank You, Heavenly Father, for every blessing You have already given and for every blessing You will yet bestow upon the GRA family. We dedicate ourselves afresh to You. May we never forsake You after You have blessed us, but may we love You more deeply, serve You more faithfully, walk more humbly, and glorify the Lord Jesus Christ in every generation until we stand before Your throne. Amen.","scripture":[],"o":"s-8-2-19","o2":"s-8-2-19"},{"text":"Father, unite every heart in love, humility, peace, and one purpose.","scripture":[{"ref":"Psalm 133:1","verses":[{"n":"1","text":"“Behold, how good and how pleasant it is for brethren to dwell together in unity!”"}]}],"o":"s-8-8-1","o2":"s-8-2-20"}]},{"orig":46,"title":"Prayer for Divine Growth, Multiplication, and Establishment of GRA Worldwide","foundation":[{"ref":"Acts 6:7","verses":[{"n":"7","text":"“And the word of God increased; and the number of the disciples multiplied in Jerusalem greatly; and a great company of the priests were obedient to the faith.”"}]},{"ref":"Acts 9:31","verses":[{"n":"31","text":"“Then had the churches rest throughout all Judaea and Galilee and Samaria, and were edified; and walking in the fear of the Lord, and in the comfort of the Holy Ghost, were multiplied.”"}]},{"ref":"Isaiah 54:2–3","verses":[{"n":"2","text":"“Enlarge the place of thy tent, and let them stretch forth the curtains of thine habitations: spare not, lengthen thy cords, and strengthen thy stakes;"},{"n":"3","text":"For thou shalt break forth on the right hand and on the left; and thy seed shall inherit the Gentiles, and make the desolate cities to be inhabited.”"}]},{"ref":"1 Corinthians 3:6–7","verses":[{"n":"6","text":"“I have planted, Apollos watered; but God gave the increase."},{"n":"7","text":"So then neither is he that planteth any thing, neither he that watereth; but God that giveth the increase.”"}]}],"prayers":[{"text":"Father, let the Word of God increase mightily throughout every GRA church until every nation hears the Gospel of Jesus Christ.","scripture":[],"o":"s-8-3-1","o2":"s-8-3-1"},{"text":"Lord Jesus, multiply faithful disciples in every GRA assembly according to Your perfect will and for the glory of Your name.","scripture":[],"o":"s-8-3-2","o2":"s-8-3-2"},{"text":"Father, enlarge the borders of GRA worldwide so that more people may hear the Gospel, be saved, and become mature disciples of Christ.","scripture":[],"o":"s-8-3-3","o2":"s-8-3-3"},{"text":"Lord, establish every new GRA church upon the unshakable foundation of Your holy Word and sound biblical doctrine.","scripture":[],"o":"s-8-3-4","o2":"s-8-3-4"},{"text":"Father, strengthen every existing GRA assembly in holiness, unity, love, humility, prayer, evangelism, and faithful discipleship.","scripture":[],"o":"s-8-3-5","o2":"s-8-3-5"},{"text":"Lord Jesus, let every GRA church become spiritually healthy, biblically grounded, mission-minded, and fruitful for generations to come.","scripture":[],"o":"s-8-3-6","o2":"s-8-3-6"},{"text":"Father, raise faithful pastors, missionaries, evangelists, teachers, elders, deacons, worship leaders, and workers to shepherd Your people with wisdom and love.","scripture":[],"o":"s-8-3-7","o2":"s-8-3-7"},{"text":"Lord, grant every GRA assembly the comfort, power, guidance, and fullness of the Holy Spirit.","scripture":[],"o":"s-8-3-8","o2":"s-8-3-8"},{"text":"Father, let every church experience continual spiritual revival, renewed devotion to Christ, and increasing hunger for Your Word.","scripture":[],"o":"s-8-3-9","o2":"s-8-3-9"},{"text":"Lord Jesus, remove every barrier that hinders the growth of Your Church, including fear, division, discouragement, compromise, false teaching, and spiritual complacency.","scripture":[],"o":"s-8-3-10","o2":"s-8-3-10"},{"text":"Father, let every convert become firmly rooted in Christ, steadfast in prayer, faithful in fellowship, and fruitful in Christian service.","scripture":[],"o":"s-8-3-11","o2":"s-8-3-11"},{"text":"Lord, make every GRA church a house of prayer, worship, holiness, biblical preaching, compassionate ministry, and faithful evangelism.","scripture":[],"o":"s-8-3-12","o2":"s-8-3-12"},{"text":"Father, bless every outreach effort with genuine conversions, lasting discipleship, and enduring spiritual fruit.","scripture":[],"o":"s-8-3-13","o2":"s-8-3-13"},{"text":"Lord Jesus, let every family that joins GRA become firmly established in the faith and faithfully serve You from generation to generation.","scripture":[],"o":"s-8-3-14","o2":"s-8-3-14"},{"text":"Father, grant GRA favor in every community where You have planted us, so that Christ may be known and honored.","scripture":[],"o":"s-8-3-15","o2":"s-8-3-15"},{"text":"Lord, let every GRA assembly become a training center that equips believers to preach the Gospel, make disciples, and serve faithfully in Your Kingdom.","scripture":[],"o":"s-8-3-16","o2":"s-8-3-16"},{"text":"Father, help me personally to contribute faithfully to the spiritual growth, unity, holiness, and mission of GRA through prayer, evangelism, discipleship, faithful service, generosity, and Christian love.","scripture":[],"o":"s-8-3-17","o2":"s-8-3-17"},{"text":"Lord Jesus, let every church planted through GRA become a church that plants other churches, raises faithful leaders, and sends missionaries to the nations.","scripture":[],"o":"s-8-3-18","o2":"s-8-3-18"},{"text":"Father, may the growth of GRA always be marked first by spiritual maturity, biblical faithfulness, Christlike character, holy living, and faithful obedience rather than numbers alone, so that Jesus Christ will receive all the glory.","scripture":[],"o":"s-8-3-19","o2":"s-8-3-19"},{"text":"Thank You, Heavenly Father, because You alone give the increase. Continue to establish, strengthen, multiply, and preserve GRA worldwide until multitudes from every nation are gathered into Your Kingdom, faithfully discipled in Your truth, and prepared for the glorious return of our Lord Jesus Christ. Amen.","scripture":[],"o":"s-8-3-20","o2":"s-8-3-20"}]},{"orig":47,"title":"Prayer for GRA to Become a Global Lighthouse for Jesus Christ and for the Fulfillment of the Great Commission","foundation":[{"ref":"Matthew 5:14–16","verses":[{"n":"14","text":"“Ye are the light of the world. A city that is set on an hill cannot be hid."},{"n":"15","text":"Neither do men light a candle, and put it under a bushel, but on a candlestick; and it giveth light unto all that are in the house."},{"n":"16","text":"Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]},{"ref":"Isaiah 60:1–3","verses":[{"n":"1","text":"“Arise, shine; for thy light is come, and the glory of the LORD is risen upon thee."},{"n":"2","text":"For, behold, the darkness shall cover the earth, and gross darkness the people: but the LORD shall arise upon thee, and his glory shall be seen upon thee."},{"n":"3","text":"And the Gentiles shall come to thy light, and kings to the brightness of thy rising.”"}]},{"ref":"Matthew 24:14","verses":[{"n":"14","text":"“And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.”"}]},{"ref":"Habakkuk 2:14","verses":[{"n":"14","text":"“For the earth shall be filled with the knowledge of the glory of the LORD, as the waters cover the sea.”"}]}],"prayers":[{"text":"Father, establish GRA worldwide as a bright and faithful lighthouse that continually points people to Jesus Christ and never to the glory of men.","scripture":[],"o":"s-8-4-1","o2":"s-8-4-1"},{"text":"Lord Jesus, let the light of Your Gospel shine through every GRA church, every pastor, every missionary, every worker, and every member throughout the nations.","scripture":[],"o":"s-8-4-2","o2":"s-8-4-2"},{"text":"Father, let Your glory rest upon GRA so that people from every tribe, tongue, and nation may come to know the saving grace of Christ.","scripture":[],"o":"s-8-4-3","o2":"s-8-4-3"},{"text":"Lord, open new nations, new cities, new campuses, new communities, and unreached places for the preaching of the Gospel through GRA according to Your sovereign will.","scripture":[],"o":"s-8-4-4","o2":"s-8-4-4"},{"text":"Father, let GRA faithfully fulfill the Great Commission by preaching Christ, making disciples, planting biblically faithful churches, and equipping believers.","scripture":[],"o":"s-8-4-5","o2":"s-8-4-5"},{"text":"Lord Jesus, let every GRA assembly become a center of prayer, biblical teaching, worship, evangelism, discipleship, holiness, compassion, and missionary outreach.","scripture":[],"o":"s-8-4-6","o2":"s-8-4-6"},{"text":"Father, raise faithful missionaries from GRA who will gladly carry the Gospel to difficult places, unreached peoples, and nations where Christ is not yet known.","scripture":[],"o":"s-8-4-7","o2":"s-8-4-7"},{"text":"Lord, grant GRA wisdom to use every lawful means — including personal evangelism, missions, education, literature, media, technology, and humanitarian service — to proclaim the Gospel.","scripture":[],"o":"s-8-4-8","o2":"s-8-4-8"},{"text":"Father, let kings, government leaders, educators, professionals, students, families, and entire communities hear the Gospel through the faithful witness of GRA.","scripture":[],"o":"s-8-4-9","o2":"s-8-4-9"},{"text":"Lord Jesus, preserve GRA from worldly compromise, false doctrine, pride, division, and every distraction that weakens Gospel ministry.","scripture":[],"o":"s-8-4-10","o2":"s-8-4-10"},{"text":"Father, make every GRA member a faithful ambassador for Christ in the home, workplace, school, neighborhood, and every sphere of influence.","scripture":[],"o":"s-8-4-11","o2":"s-8-4-11"},{"text":"Lord, let the fruit of the Holy Spirit be clearly seen in the lives of all who belong to GRA, so that Christ may be honored.","scripture":[],"o":"s-8-4-12","o2":"s-8-4-12"},{"text":"Father, grant GRA increasing favor to proclaim the Gospel wherever You open doors, always with humility, truth, compassion, and faithfulness.","scripture":[],"o":"s-8-4-13","o2":"s-8-4-13"},{"text":"Lord Jesus, let multitudes not only hear the Gospel but also become mature disciples who obey all that You have commanded.","scripture":[],"o":"s-8-4-14","o2":"s-8-4-14"},{"text":"Father, let GRA become known throughout the world for sound doctrine, faithful exposition of Scripture, fervent prayer, holy living, compassionate service, and unwavering devotion to Christ.","scripture":[],"o":"s-8-4-15","o2":"s-8-4-15"},{"text":"Lord, let every generation within GRA faithfully pass the Gospel to the next generation until the return of our Lord Jesus Christ.","scripture":[],"o":"s-8-4-16","o2":"s-8-4-16"},{"text":"Father, let every church planted through GRA become a church that plants other churches, makes disciples who make disciples, and raises leaders who faithfully teach others also.","scripture":[],"o":"s-8-4-17","o2":"s-8-4-17"},{"text":"Lord Jesus, help me personally to serve faithfully in this worldwide vision. Give me grace to pray, give, witness, disciple, encourage, and labor with joy wherever You assign me.","scripture":[],"o":"s-8-4-18","o2":"s-8-4-18"},{"text":"Father, let the name of Jesus Christ alone be exalted through every ministry, every testimony, every miracle, every outreach, every sermon, every publication, and every mission effort carried out by GRA worldwide.","scripture":[],"o":"s-8-4-19","o2":"s-8-4-19"},{"text":"Thank You, Heavenly Father, because the Church belongs to Christ. May GRA remain faithful to Your Word, empowered by the Holy Spirit, devoted to the Great Commission, fruitful in every nation You send us, and steadfast until the glorious appearing of our great God and Savior Jesus Christ. To Him alone be all glory, dominion, honor, and praise forever. Amen.","scripture":[],"o":"s-8-4-20","o2":"s-8-4-20"},{"text":"Let the surrounding community encounter Christ through this church.","scripture":[{"ref":"Matthew 5:14","verses":[{"n":"14","text":"“Ye are the light of the world. A city that is set on an hill cannot be hid.”"}]}],"o":"s-8-10-1","o2":"s-8-4-21"}]},{"orig":48,"title":"Prayer for Divine Wisdom, Direction, Favor, and Open Doors for GRA Worldwide","foundation":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]},{"ref":"Proverbs 3:5–6","verses":[{"n":"5","text":"“Trust in the LORD with all thine heart; and lean not unto thine own understanding."},{"n":"6","text":"In all thy ways acknowledge him, and he shall direct thy paths.”"}]},{"ref":"Colossians 4:3","verses":[{"n":"3","text":"“Withal praying also for us, that God would open unto us a door of utterance, to speak the mystery of Christ, for which I am also in bonds:”"}]},{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]}],"prayers":[{"text":"Father, grant our Father in the Lord, every pastor, every leader, every missionary, and every worker in GRA divine wisdom to make decisions that honor Jesus Christ and advance Your Kingdom.","scripture":[],"o":"s-8-5-1","o2":"s-8-5-1"},{"text":"Lord Jesus, direct every step of GRA according to Your perfect will. Let us never move ahead of You or fall behind Your leading.","scripture":[],"o":"s-8-5-2","o2":"s-8-5-2"},{"text":"Father, open doors for the preaching of the Gospel in cities, villages, campuses, workplaces, and nations where Christ is not yet known.","scripture":[],"o":"s-8-5-3","o2":"s-8-5-3"},{"text":"Lord, grant GRA favor before government authorities, community leaders, educational institutions, Christian organizations, and churches whenever it serves the advance of the Gospel.","scripture":[],"o":"s-8-5-4","o2":"s-8-5-4"},{"text":"Father, close every door that would lead GRA into compromise, distraction, unsound doctrine, or partnerships that do not honor Christ.","scripture":[],"o":"s-8-5-5","o2":"s-8-5-5"},{"text":"Lord Jesus, raise wise counselors around our Father in the Lord and the leadership of GRA who fear God, love the Scriptures, and seek only Your glory.","scripture":[],"o":"s-8-5-6","o2":"s-8-5-6"},{"text":"Father, grant us discernment to recognize every opportunity You have prepared and courage to walk through every door You open.","scripture":[],"o":"s-8-5-7","o2":"s-8-5-7"},{"text":"Lord, let every conference, crusade, leadership meeting, mission trip, evangelistic outreach, and discipleship program be ordered by Your wisdom and directed by the Holy Spirit.","scripture":[],"o":"s-8-5-8","o2":"s-8-5-8"},{"text":"Father, give GRA wisdom to proclaim the unchanging Gospel faithfully while ministering with compassion and understanding to people from every culture and nation.","scripture":[],"o":"s-8-5-9","o2":"s-8-5-9"},{"text":"Lord Jesus, let every new church plant, mission field, and ministry assignment be established according to Your perfect plan.","scripture":[],"o":"s-8-5-10","o2":"s-8-5-10"},{"text":"Father, grant supernatural wisdom in managing finances, resources, properties, publications, media ministries, humanitarian work, and every stewardship You entrust to GRA.","scripture":[],"o":"s-8-5-11","o2":"s-8-5-11"},{"text":"Lord, preserve every leader from confusion, discouragement, impulsive decisions, human pride, and dependence upon worldly wisdom.","scripture":[],"o":"s-8-5-12","o2":"s-8-5-12"},{"text":"Father, let every member of GRA grow in biblical wisdom, spiritual discernment, sound judgment, and increasing knowledge of Christ.","scripture":[],"o":"s-8-5-13","o2":"s-8-5-13"},{"text":"Lord Jesus, let Your favor rest upon every faithful laborer, every missionary, every evangelist, every teacher, every volunteer, and every servant in GRA.","scripture":[],"o":"s-8-5-14","o2":"s-8-5-14"},{"text":"Father, grant us favor to obtain places of worship, ministry opportunities, legal permissions where required, and every resource needed to faithfully carry out the Great Commission.","scripture":[],"o":"s-8-5-15","o2":"s-8-5-15"},{"text":"Lord, make GRA known for biblical integrity, Christlike humility, servant leadership, excellence, compassion, and unwavering faithfulness to the Gospel.","scripture":[],"o":"s-8-5-16","o2":"s-8-5-16"},{"text":"Father, help me personally to seek Your wisdom before every decision, to trust Your guidance completely, and to walk faithfully in every assignment You give me.","scripture":[],"o":"s-8-5-17","o2":"s-8-5-17"},{"text":"Lord Jesus, let every open door You grant become a means for multitudes to hear the Gospel, believe in Christ, and become faithful disciples.","scripture":[],"o":"s-8-5-18","o2":"s-8-5-18"},{"text":"Father, let every favor You bestow upon GRA result in greater opportunities to glorify Christ, strengthen His Church, serve the needy, proclaim the Scriptures, and make disciples of all nations.","scripture":[],"o":"s-8-5-19","o2":"s-8-5-19"},{"text":"Thank You, Heavenly Father, because You are the source of all wisdom, guidance, favor, and opportunity. Continue to lead GRA worldwide by Your Holy Spirit, open every door You desire us to enter, close every door You do not desire, and establish us firmly in Your perfect will until the coming of our Lord Jesus Christ. Amen.","scripture":[],"o":"s-8-5-20","o2":"s-8-5-20"},{"text":"Let every aspect of all our gatherings and meetings flow in divine order under the leadership of the Holy Spirit.","scripture":[{"ref":"1 Corinthians 14:40","verses":[{"n":"40","text":"“Let all things be done decently and in order.”"}]}],"o":"s-8-9-1","o2":"s-8-5-21"}]},{"orig":49,"title":"Prayer for Divine Helpers, Kingdom Partners, and Strategic Connections for GRA Worldwide","foundation":[{"ref":"Psalm 20:2","verses":[{"n":"2","text":"“Send thee help from the sanctuary, and strengthen thee out of Zion;”"}]},{"ref":"Isaiah 60:10–11","verses":[{"n":"10","text":"“And the sons of strangers shall build up thy walls, and their kings shall minister unto thee: for in my wrath I smote thee, but in my favour have I had mercy on thee."},{"n":"11","text":"Therefore thy gates shall be open continually; they shall not be shut day nor night; that men may bring unto thee the forces of the Gentiles, and that their kings may be brought.”"}]},{"ref":"Ecclesiastes 4:9","verses":[{"n":"9","text":"“Two are better than one; because they have a good reward for their labour.”"}]},{"ref":"1 Corinthians 3:9","verses":[{"n":"9","text":"“For we are labourers together with God: ye are God’s husbandry, ye are God’s building.”"}]}],"prayers":[{"text":"Father, raise faithful Kingdom partners for GRA worldwide who sincerely love Jesus Christ, His Word, and the advancement of His Gospel.","scripture":[],"o":"s-8-6-1","o2":"s-8-6-1"},{"text":"Lord Jesus, send men and women whose hearts You have prepared to labor together with GRA in humility, unity, truth, and love.","scripture":[],"o":"s-8-6-2","o2":"s-8-6-2"},{"text":"Father, connect GRA with Bible-believing churches, faithful ministries, missionaries, seminaries, Christian institutions, and Kingdom organizations that will strengthen the work of the Gospel.","scripture":[],"o":"s-8-6-3","o2":"s-8-6-3"},{"text":"Lord, grant GRA favor before pastors, Christian leaders, mission agencies, and churches around the world according to Your perfect will.","scripture":[],"o":"s-8-6-4","o2":"s-8-6-4"},{"text":"Father, raise intercessors who will faithfully pray for GRA, its leaders, missionaries, churches, and global outreach.","scripture":[],"o":"s-8-6-5","o2":"s-8-6-5"},{"text":"Lord Jesus, raise generous supporters who will joyfully give toward evangelism, discipleship, missions, humanitarian ministry, church planting, and theological training.","scripture":[],"o":"s-8-6-6","o2":"s-8-6-6"},{"text":"Father, send skilled workers, administrators, teachers, evangelists, worship leaders, media specialists, translators, counselors, and disciplers to strengthen every area of GRA’s ministry.","scripture":[],"o":"s-8-6-7","o2":"s-8-6-7"},{"text":"Lord, let every partnership established by GRA be founded upon biblical truth, mutual respect, humility, integrity, and a shared commitment to the Gospel.","scripture":[],"o":"s-8-6-8","o2":"s-8-6-8"},{"text":"Father, protect GRA from unhealthy alliances, false doctrine, worldly influence, selfish ambition, manipulation, and every partnership that would compromise the truth of Scripture.","scripture":[],"o":"s-8-6-9","o2":"s-8-6-9"},{"text":"Lord Jesus, give our Father in the Lord and all leaders discernment to recognize the people You have truly appointed to labor alongside this ministry.","scripture":[],"o":"s-8-6-10","o2":"s-8-6-10"},{"text":"Father, let GRA become known throughout the world as a ministry that faithfully preaches Christ, serves people with compassion, and honors Your holy Word.","scripture":[],"o":"s-8-6-11","o2":"s-8-6-11"},{"text":"Lord, grant wisdom to build lasting relationships that strengthen the Body of Christ rather than promote personal ambition or organizational pride.","scripture":[],"o":"s-8-6-12","o2":"s-8-6-12"},{"text":"Father, open doors for collaborative evangelism, leadership training, missions, humanitarian outreach, biblical education, and discipleship wherever You desire.","scripture":[],"o":"s-8-6-13","o2":"s-8-6-13"},{"text":"Lord Jesus, let every Kingdom relationship produce greater unity, greater faithfulness, greater holiness, and greater effectiveness in advancing the Gospel.","scripture":[],"o":"s-8-6-14","o2":"s-8-6-14"},{"text":"Father, help me personally to become a trustworthy servant who encourages unity, serves faithfully, builds healthy relationships, and strengthens the work of Your Kingdom.","scripture":[],"o":"s-8-6-15","o2":"s-8-6-15"},{"text":"Lord, teach me to honor pastors, missionaries, church leaders, workers, and every faithful servant of Christ with genuine love and humility.","scripture":[],"o":"s-8-6-16","o2":"s-8-6-16"},{"text":"Father, use my words, conduct, hospitality, integrity, diligence, and servant-hearted attitude to strengthen relationships that honor Jesus Christ.","scripture":[],"o":"s-8-6-17","o2":"s-8-6-17"},{"text":"Lord Jesus, make me a faithful bridge-builder who promotes reconciliation, cooperation, mutual encouragement, and biblical unity among believers.","scripture":[],"o":"s-8-6-18","o2":"s-8-6-18"},{"text":"Father, let every strategic connection You bring into my life and into GRA become a means of proclaiming Christ, making disciples, strengthening churches, and expanding Your Kingdom throughout the nations.","scripture":[],"o":"s-8-6-19","o2":"s-8-6-19"},{"text":"Thank You, Heavenly Father, because You are the One who joins Your people together for Your purposes. May every helper, every partner, every laborer, every ministry relationship, and every opportunity You provide bring lasting glory to Jesus Christ, strengthen the Body of Christ, and hasten the fulfillment of the Great Commission until our Lord returns. Amen.","scripture":[],"o":"s-8-6-20","o2":"s-8-6-20"}]},{"orig":50,"title":"Prayer for Multitudes to Gather, Be Saved, and Be Discipled in GRA Churches, and for Grace to Faithfully Do My Part","foundation":[{"ref":"Matthew 9:37–38","verses":[{"n":"37","text":"“Then saith he unto his disciples, The harvest truly is plenteous, but the labourers are few;"},{"n":"38","text":"Pray ye therefore the Lord of the harvest, that he will send forth labourers into his harvest.”"}]},{"ref":"Acts 2:41–42","verses":[{"n":"41","text":"“Then they that gladly received his word were baptized: and the same day there were added unto them about three thousand souls."},{"n":"42","text":"And they continued stedfastly in the apostles’ doctrine and fellowship, and in breaking of bread, and in prayers.”"}]},{"ref":"Acts 2:46–47","verses":[{"n":"46","text":"“And they, continuing daily with one accord in the temple, and breaking bread from house to house, did eat their meat with gladness and singleness of heart,"},{"n":"47","text":"Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved.”"}]},{"ref":"Matthew 28:19–20","verses":[{"n":"19","text":"“Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:"},{"n":"20","text":"Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.”"}]}],"prayers":[{"text":"Father, let multitudes from every tribe, nation, language, culture, and background be drawn to Jesus Christ through the ministry of GRA worldwide.","scripture":[],"o":"s-8-7-1","o2":"s-8-7-1"},{"text":"Lord Jesus, let every GRA church become a spiritual home where sinners are saved, believers are discipled, and saints are equipped for every good work.","scripture":[],"o":"s-8-7-2","o2":"s-8-7-2"},{"text":"Father, fulfill Your promise by adding daily to GRA such as should be saved according to Your sovereign will.","scripture":[],"o":"s-8-7-3","o2":"s-8-7-3"},{"text":"Lord, let every worship service, prayer meeting, Bible study, outreach, conference, and evangelistic campaign produce lasting fruit for eternity.","scripture":[],"o":"s-8-7-4","o2":"s-8-7-4"},{"text":"Father, raise thousands of faithful laborers, evangelists, disciplers, pastors, teachers, missionaries, intercessors, and servant leaders throughout GRA.","scripture":[],"o":"s-8-7-5","o2":"s-8-7-5"},{"text":"Lord Jesus, let every new convert become firmly established in Your Word, in prayer, in fellowship, in holiness, and in faithful service.","scripture":[],"o":"s-8-7-6","o2":"s-8-7-6"},{"text":"Father, remove every obstacle that prevents people from hearing the Gospel, responding in faith, and becoming committed disciples of Christ.","scripture":[],"o":"s-8-7-7","o2":"s-8-7-7"},{"text":"Lord, give every GRA assembly favor within its community so that many people will joyfully come to hear the Word of God.","scripture":[],"o":"s-8-7-8","o2":"s-8-7-8"},{"text":"Father, let every church plant become healthy, biblically grounded, Christ-centered, mission-minded, and fruitful for generations to come.","scripture":[],"o":"s-8-7-9","o2":"s-8-7-9"},{"text":"Lord Jesus, preserve GRA from false doctrine, division, spiritual pride, compromise, and every strategy of the enemy that weakens discipleship.","scripture":[],"o":"s-8-7-10","o2":"s-8-7-10"},{"text":"Father, let every member of GRA discover his or her spiritual gifts and faithfully serve the Body of Christ with humility and love.","scripture":[],"o":"s-8-7-11","o2":"s-8-7-11"},{"text":"Lord, let families be restored, children be taught the Scriptures, youth become passionate followers of Christ, and older believers become faithful mentors.","scripture":[],"o":"s-8-7-12","o2":"s-8-7-12"},{"text":"Father, grant our Father in the Lord, pastors, ministers, elders, and leaders wisdom, holiness, compassion, courage, and endurance as they shepherd Your people.","scripture":[],"o":"s-8-7-13","o2":"s-8-7-13"},{"text":"Lord Jesus, let every sermon preached in GRA produce repentance, faith, obedience, spiritual maturity, and lasting transformation.","scripture":[],"o":"s-8-7-14","o2":"s-8-7-14"},{"text":"Father, make every GRA church a lighthouse of truth, prayer, worship, evangelism, discipleship, compassion, and biblical holiness.","scripture":[],"o":"s-8-7-15","o2":"s-8-7-15"},{"text":"Lord, help me personally to become a faithful soul winner. Give me genuine love for people, boldness to share the Gospel, wisdom to answer questions, and perseverance to disciple those You place in my life.","scripture":[],"o":"s-8-7-16","o2":"s-8-7-16"},{"text":"Father, help me to faithfully fulfill my own assignment within GRA. Let me serve with humility, diligence, excellence, integrity, joy, and unwavering commitment, never seeking recognition but only the glory of Christ.","scripture":[],"o":"s-8-7-17","o2":"s-8-7-17"},{"text":"Lord Jesus, use my prayers, my giving, my words, my conduct, my hospitality, my profession, my relationships, and my daily life to strengthen the ministry of GRA and to bring many people into Your Kingdom.","scripture":[],"o":"s-8-7-18","o2":"s-8-7-18"},{"text":"Father, make me a faithful laborer in Your harvest until the end of my life. Help me to encourage others, disciple believers, support leaders, strengthen the weak, and labor together with the whole GRA family so that countless multitudes may come to know Jesus Christ.","scripture":[],"o":"s-8-7-19","o2":"s-8-7-19"},{"text":"Thank You, Heavenly Father, because the harvest belongs to You. I dedicate myself afresh to Your service. Use me as Your willing instrument to gather souls, make disciples, strengthen Your Church, and advance the Gospel through GRA worldwide until the whole earth is filled with the knowledge of the glory of the Lord through Jesus Christ our Savior. Amen.","scripture":[],"o":"s-8-7-20","o2":"s-8-7-20"}]},{"orig":94,"title":"Prayer for Revival, Holiness, and the Fear of the Lord Throughout GRA Worldwide","foundation":[{"ref":"Habakkuk 3:2","verses":[{"n":"2","text":"“O LORD, I have heard thy speech, and was afraid: O LORD, revive thy work in the midst of the years, in the midst of the years make known; in wrath remember mercy.”"}]},{"ref":"2 Chronicles 7:14","verses":[{"n":"14","text":"“If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land.”"}]},{"ref":"Psalm 85:6","verses":[{"n":"6","text":"“Wilt thou not revive us again: that thy people may rejoice in thee?”"}]},{"ref":"Hebrews 12:14","verses":[{"n":"14","text":"“Follow peace with all men, and holiness, without which no man shall see the Lord:”"}]}],"prayers":[{"text":"Father, send a mighty revival throughout every GRA church, beginning with me. Revive our hearts to love Christ above everything else.","scripture":[],"o":"s-12-1-1","o2":"s-1-1-1"},{"text":"Lord Jesus, let the fire of the Holy Ghost burn away spiritual lukewarmness, complacency, compromise, worldliness, and every affection that competes with our devotion to You.","scripture":[],"o":"s-12-1-2","o2":"s-1-1-2"},{"text":"Father, give every member of GRA a deep hunger for holiness, righteousness, purity, and obedience to Your holy Word.","scripture":[],"o":"s-12-1-3","o2":"s-1-1-3"},{"text":"Lord, let every GRA altar become an altar of fervent prayer, sincere repentance, heartfelt worship, and faithful preaching of the Scriptures.","scripture":[],"o":"s-12-1-4","o2":"s-1-1-4"},{"text":"Father, restore our first love for Jesus Christ. Let our greatest delight be to know You, obey You, worship You, and make You known.","scripture":[],"o":"s-12-1-5","o2":"s-1-1-5"},{"text":"Lord Jesus, baptize every pastor, missionary, minister, worker, and member with fresh fire from heaven for holy living and faithful service.","scripture":[],"o":"s-12-1-6","o2":"s-1-1-6"},{"text":"Father, let the fear of the Lord rest upon every GRA assembly, producing humility, wisdom, purity, reverence, and joyful obedience.","scripture":[],"o":"s-12-1-7","o2":"s-1-1-7"},{"text":"Lord, expose and remove every hidden sin, secret compromise, pride, bitterness, hypocrisy, envy, unforgiveness, and selfish ambition from our hearts.","scripture":[],"o":"s-12-1-8","o2":"s-1-1-8"},{"text":"Father, let the Holy Spirit continually convict us of sin, lead us into truth, and conform us to the image of Christ.","scripture":[],"o":"s-12-1-9","o2":"s-1-1-9"},{"text":"Lord Jesus, raise among us men and women who are mighty in prayer, faithful in the Scriptures, steadfast in holiness, and bold in proclaiming the Gospel.","scripture":[],"o":"s-12-1-10","o2":"s-1-1-10"},{"text":"Father, let revival begin in our homes. Restore family worship, daily prayer, Bible reading, and Christ-centered living throughout GRA families.","scripture":[],"o":"s-12-1-11","o2":"s-1-1-11"},{"text":"Lord, make our children and young people passionate lovers of Jesus Christ, faithful students of the Bible, and fearless witnesses for the Gospel.","scripture":[],"o":"s-12-1-12","o2":"s-1-1-12"},{"text":"Father, let our worship never become routine or merely emotional, but may it always be offered in spirit and in truth.","scripture":[],"o":"s-12-1-13","o2":"s-1-1-13"},{"text":"Lord Jesus, let every revival You send produce lasting repentance, transformed lives, restored marriages, reconciled families, faithful disciples, and enduring fruit.","scripture":[],"o":"s-12-1-14","o2":"s-1-1-14"},{"text":"Father, preserve GRA from false revival, emotionalism without truth, unsound doctrine, spiritual pride, counterfeit manifestations, and every deception of the enemy.","scripture":[],"o":"s-12-1-15","o2":"s-1-1-15"},{"text":"Lord, let Your Word dwell richly in every GRA member, shaping our thinking, our speech, our conduct, and our decisions.","scripture":[],"o":"s-12-1-16","o2":"s-1-1-16"},{"text":"Father, help me personally to walk in daily repentance, sincere humility, consistent prayer, faithful obedience, holy living, and unwavering love for Christ.","scripture":[],"o":"s-12-1-17","o2":"s-1-1-17"},{"text":"Lord Jesus, let revival spread from one GRA church to another, from one city to another, from one nation to another, until many people come to saving faith in You.","scripture":[],"o":"s-12-1-18","o2":"s-1-1-18"},{"text":"Father, let every revival You send ultimately exalt Jesus Christ, strengthen the Church, advance the Gospel, make faithful disciples, and prepare us for the glorious return of our Lord.","scripture":[],"o":"s-12-1-19","o2":"s-1-1-19"},{"text":"Thank You, Heavenly Father, because You delight to revive Your people. May GRA worldwide continually walk in the fear of the Lord, the comfort of the Holy Spirit, the holiness of Christ, the power of the Gospel, and the joy of salvation until we stand together before Your heavenly throne. Amen.","scripture":[],"o":"s-12-1-20","o2":"s-1-1-20"}]},{"title":"Prayer for Holiness, the Fear of the Lord, and Christlike Character","foundation":[],"prayers":[{"text":"Send revival that transforms lives and communities.","scripture":[{"ref":"Habakkuk 3:2","verses":[{"n":"2","text":"“O LORD, I have heard thy speech, and was afraid: O LORD, revive thy work in the midst of the years, in the midst of the years make known; in wrath remember mercy.”"}]}],"o":"s-12-2-1","o2":"s-1-2-1"},{"text":"Father, grant sincere repentance. Break every stubborn heart and let many return wholeheartedly unto You.","scripture":[{"ref":"Acts 3:19","verses":[{"n":"19","text":"“Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of the Lord;”"}]}],"o":"s-12-3-1","o2":"s-1-2-2"},{"text":"Holy Spirit, convict every sinner and every backslider. Let no one leave unchanged.","scripture":[{"ref":"John 16:8","verses":[{"n":"8","text":"“And when he is come, he will reprove the world of sin, and of righteousness, and of judgment:”"}]}],"o":"s-12-4-1","o2":"s-1-2-3"},{"text":"Sanctify the entire congregation for Your glory.","scripture":[{"ref":"1 Peter 1:15–16","verses":[{"n":"15","text":"“But as he which hath called you is holy, so be ye holy in all manner of conversation;"},{"n":"16","text":"Because it is written, Be ye holy; for I am holy.”"}]}],"o":"s-12-5-1","o2":"s-1-2-4"},{"text":"Keep every leader and member walking in humility.","scripture":[{"ref":"James 4:10","verses":[{"n":"10","text":"“Humble yourselves in the sight of the Lord, and he shall lift you up.”"}]}],"o":"s-12-7-1","o2":"s-1-2-5"},{"text":"Increase our desire for Your Word, Your presence, and Your righteousness.","scripture":[{"ref":"Matthew 5:6","verses":[{"n":"6","text":"“Blessed are they which do hunger and thirst after righteousness: for they shall be filled.”"}]}],"o":"s-12-8-1","o2":"s-1-2-6"},{"text":"Increase faith for salvation, healing, and obedience.","scripture":[{"ref":"Romans 10:17","verses":[{"n":"17","text":"“So then faith cometh by hearing, and hearing by the word of God.”"}]}],"o":"s-12-9-1","o2":"s-1-2-7"},{"text":"Let Christ’s love characterize every interaction.","scripture":[{"ref":"John 13:35","verses":[{"n":"35","text":"“By this shall all men know that ye are my disciples, if ye have love one to another.”"}]}],"o":"s-12-10-1","o2":"s-1-2-8"},{"text":"Fill every heart with the peace of Christ.","scripture":[{"ref":"John 14:27","verses":[{"n":"27","text":"“Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.”"}]}],"o":"s-12-11-1","o2":"s-1-2-9"},{"text":"Let holy joy overflow throughout all our gatherings and meetings.","scripture":[{"ref":"Nehemiah 8:10","verses":[{"n":"10","text":"“Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our LORD: neither be ye sorry; for the joy of the LORD is your strength.”"}]}],"o":"s-12-12-1","o2":"s-1-2-10"},{"text":"Father, let holy reverence fill all our gatherings and meetings.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-1","o2":"s-1-3-1"},{"text":"Lord, remove every spirit of carelessness.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-2","o2":"s-1-3-2"},{"text":"Father, establish holiness among Your people.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-3","o2":"s-1-3-3"},{"text":"Lord, let sin be forsaken.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-4","o2":"s-1-3-4"},{"text":"Father, grant broken and contrite hearts.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-5","o2":"s-1-3-5"},{"text":"Lord, raise a generation that fears You.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-6","o2":"s-1-3-6"},{"text":"Father, let Your Word be honored.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-7","o2":"s-1-3-7"},{"text":"Lord, let worship be offered in reverence.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-8","o2":"s-1-3-8"},{"text":"Father, let every leader walk in humility.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-9","o2":"s-1-3-9"},{"text":"Lord, let Your holy name be exalted.","scripture":[{"ref":"Proverbs 9:10","verses":[{"n":"10","text":"“The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.”"}]}],"o":"s-12-6-10","o2":"s-1-3-10"}]}]},{"label":"Part SEVEN","title":"MY SPIRITUAL LEADERS","subtitle":"Prayers for our Father and Mother in the Lord and all who shepherd the flock","sections":[{"orig":39,"title":"Pleading the Blood of Jesus Over My Father and Mother in the Lord and Their Family","foundation":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Acts 20:28","verses":[{"n":"28","text":"“Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood.”"}]},{"ref":"1 Thessalonians 5:12–13","verses":[{"n":"12","text":"“And we beseech you, brethren, to know them which labour among you, and are over you in the Lord, and admonish you;"},{"n":"13","text":"And to esteem them very highly in love for their work’s sake. And be at peace among yourselves.”"}]},{"ref":"Hebrews 13:17","verses":[{"n":"17","text":"“Obey them that have the rule over you, and submit yourselves: for they watch for your souls, as they that must give account, that they may do it with joy, and not with grief: for that is unprofitable for you.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my father and mother in the Lord and their entire family. Let the Blood of the everlasting covenant surround, preserve, strengthen, and establish them in every area of their lives.","scripture":[],"o":"s-7-1-1","o2":"s-7-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over them than every accusation, opposition, discouragement, persecution, evil report, or attack of the enemy.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-7-1-2","o2":"s-7-1-2"},{"text":"Father, by the Blood of Jesus, preserve their lives from sickness, disease, accidents, violence, death, destruction, and every hidden danger. Let seven-thousandfold strength return to every evil sender, thought, stronghold, and imagination.","scripture":[{"ref":"Psalm 91:10–11","verses":[{"n":"10","text":"“There shall no evil befall thee, neither shall any plague come nigh thy dwelling."},{"n":"11","text":"For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-7-1-3","o2":"s-7-1-3"},{"text":"Lord, let the Blood of Jesus continually renew their spiritual strength, joy, peace, wisdom, and intimacy with You. Let them never become weary in well doing.","scripture":[{"ref":"Isaiah 40:31","verses":[{"n":"31","text":"“But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.”"}]}],"o":"s-7-1-4","o2":"s-7-1-4"},{"text":"Father, by the Blood of Jesus, preserve and increase the anointing, calling, gifts, and ministry You have entrusted to them. Let their oil never run dry.","scripture":[{"ref":"Psalm 92:10","verses":[{"n":"10","text":"“But my horn shalt thou exalt like the horn of an unicorn: I shall be anointed with fresh oil.”"}]}],"o":"s-7-1-5","o2":"s-7-1-5"},{"text":"Lord Jesus, let the Blood of Jesus frustrate every counsel, conspiracy, enchantment, accusation, or weapon formed against their lives, family, ministry, and divine assignments.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-7-1-6","o2":"s-7-1-6"},{"text":"Father, by the Blood of Jesus, surround them with faithful ministers, wise and loyal sons and daughters, and Spirit-filled workers who, like Aaron and Hur, will strengthen their hands in Your service.","scripture":[],"o":"s-7-1-7","o2":"s-7-1-7"},{"text":"Lord, let the Blood of Jesus preserve them. Let the joy of the Lord through God’s presence continually abound in their lives.","scripture":[],"o":"s-7-1-8","o2":"s-7-1-8"},{"text":"Father, by the Blood of Jesus, preserve their family and future generations. Let them all walk in the fear of the Lord and fulfill Your divine purpose.","scripture":[{"ref":"Isaiah 59:21","verses":[{"n":"21","text":"“As for me, this is my covenant with them, saith the LORD; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seed’s seed, saith the LORD, from henceforth and for ever.”"}]}],"o":"s-7-1-9","o2":"s-7-1-9"},{"text":"Lord Jesus, let the Blood of Jesus grant them divine health, renewed strength, sound minds, and long life to fulfill every assignment You have ordained for them.","scripture":[{"ref":"Psalm 91:16","verses":[{"n":"16","text":"“With long life will I satisfy him, and shew him my salvation.”"}]}],"o":"s-7-1-10","o2":"s-7-1-10"},{"text":"Father, by the Blood of Jesus, supply every spiritual, financial, material, ministerial, and personal need according to Your riches in glory.","scripture":[{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]}],"o":"s-7-1-11","o2":"s-7-1-11"},{"text":"Lord, let the Blood of Jesus open greater doors for effective ministry, evangelism, missions, church planting, discipleship, leadership development, and worldwide Kingdom influence according to Your will.","scripture":[{"ref":"Colossians 4:3","verses":[{"n":"3","text":"“Withal praying also for us, that God would open unto us a door of utterance, to speak the mystery of Christ, for which I am also in bonds:”"}]}],"o":"s-7-1-12","o2":"s-7-1-12"},{"text":"Father, by the Blood of Jesus, protect them from betrayal, false brethren, deception, spiritual attacks, and every scheme of the enemy.","scripture":[{"ref":"2 Corinthians 2:11","verses":[{"n":"11","text":"“Lest Satan should get an advantage of us: for we are not ignorant of his devices.”"}]}],"o":"s-7-1-13","o2":"s-7-1-13"},{"text":"Lord Jesus, let the Blood of Jesus grant them increasing wisdom, discernment, revelation, understanding, and grace to rightly divide the Word of truth.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"o":"s-7-1-14","o2":"s-7-1-14"},{"text":"Father, by the Blood of Jesus, establish the work of their hands. Let every ministry assignment produce lasting fruit for eternity.","scripture":[{"ref":"John 15:16","verses":[{"n":"16","text":"“Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.”"}]}],"o":"s-7-1-15","o2":"s-7-1-15"},{"text":"Lord, by the Blood of Jesus, let Your favor rest upon them before God and before men. Cause kings, leaders, churches, and nations to receive the ministry You have entrusted to them according to Your perfect will.","scripture":[{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]}],"o":"s-7-1-16","o2":"s-7-1-16"},{"text":"Father, by the Blood of Jesus, preserve them in holiness, humility, faithfulness, compassion, and unwavering obedience until the end.","scripture":[{"ref":"1 Corinthians 15:58","verses":[{"n":"58","text":"“Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.”"}]}],"o":"s-7-1-17","o2":"s-7-1-17"},{"text":"Lord Jesus, let the Blood of Jesus make their lives and ministry a continual source of revival, healing, salvation, restoration, discipleship, and blessing to countless people and nations.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-7-1-18","o2":"s-7-1-18"},{"text":"Father, by the Blood of Jesus, grant that they may finish their course with joy, complete every daily divine assignment, hear Your commendation, and receive continuous and abundant eternal reward from Jesus Christ.","scripture":[{"ref":"2 Timothy 4:7–8","verses":[{"n":"7","text":"“I have fought a good fight, I have finished my course, I have kept the faith:"},{"n":"8","text":"Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing.”"}]}],"o":"s-7-1-19","o2":"s-7-1-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus my father and mother in the Lord, together with their entire family, are redeemed, protected, strengthened, preserved, supplied, fruitful, victorious, and established in Your everlasting covenant. May their ministry continue to flourish, their household remain under Your divine covering, and their lives bring increasing glory to the name of our Lord Jesus Christ until His glorious appearing.","scripture":[],"o":"s-7-1-20","o2":"s-7-1-20"}]},{"orig":40,"title":"Prayer for God to Mightily Bless, Promote, Elevate, Preserve, and Perfect Our Father and Mother in the Lord and Their Family","foundation":[{"ref":"Psalm 75:6–7","verses":[{"n":"6","text":"“For promotion cometh neither from the east, nor from the west, nor from the south."},{"n":"7","text":"But God is the judge: he putteth down one, and setteth up another.”"}]},{"ref":"Psalm 121:7–8","verses":[{"n":"7","text":"“The LORD shall preserve thee from all evil: he shall preserve thy soul."},{"n":"8","text":"The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.”"}]},{"ref":"Philippians 1:6","verses":[{"n":"6","text":"“Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:”"}]},{"ref":"Ephesians 3:20–21","verses":[{"n":"20","text":"“Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,"},{"n":"21","text":"Unto him be glory in the church by Christ Jesus throughout all ages, world without end. Amen.”"}]}],"prayers":[{"text":"Father, abundantly bless our Father and Mother in the Lord and every member of their family with every spiritual blessing in Christ Jesus, that they may continually glorify Your holy name.","scripture":[],"o":"s-7-2-1","o2":"s-7-2-1"},{"text":"Lord Jesus, promote them according to Your perfect will. Increase their usefulness, influence, wisdom, and effectiveness for the advancement of Your Kingdom and never for personal glory.","scripture":[],"o":"s-7-2-2","o2":"s-7-2-2"},{"text":"Father, elevate them in Your appointed time and entrust them with greater opportunities to proclaim the Gospel, strengthen the Church, and make faithful disciples throughout the nations.","scripture":[],"o":"s-7-2-3","o2":"s-7-2-3"},{"text":"Lord, preserve their lives from every evil, every attack of the enemy, every accident, every sickness, every discouragement, every temptation, and every hidden danger.","scripture":[],"o":"s-7-2-4","o2":"s-7-2-4"},{"text":"Father, perfect every good work You have begun in them. Continue to conform them to the image of Jesus Christ until they complete every divine assignment You have entrusted to them.","scripture":[],"o":"s-7-2-5","o2":"s-7-2-5"},{"text":"Lord Jesus, grant them increasing wisdom, revelation, discernment, humility, holiness, compassion, courage, and unwavering dependence upon the Holy Spirit.","scripture":[],"o":"s-7-2-6","o2":"s-7-2-6"},{"text":"Father, let their lives and family continually reflect the love, peace, unity, holiness, joy, and faithfulness of Christ, becoming an example to the Body of Christ.","scripture":[],"o":"s-7-2-7","o2":"s-7-2-7"},{"text":"Lord, establish the work of their hands. Let the Word of God be with fire and power in their mouths, and let every mission, conference, publication, outreach, prayer, and ministry assignment produce abundant and lasting fruit for eternity.","scripture":[],"o":"s-7-2-8","o2":"s-7-2-8"},{"text":"Father, surround them with faithful co-laborers, wise counselors, loyal friends, fervent intercessors, and Spirit-filled leaders who will strengthen their hands in the work of the Gospel.","scripture":[],"o":"s-7-2-9","o2":"s-7-2-9"},{"text":"Lord Jesus, let Your favor rest upon them before You and before men wherever it serves the advancement of the Gospel and the glory of Christ.","scripture":[],"o":"s-7-2-10","o2":"s-7-2-10"},{"text":"Father, continually renew their physical strength, emotional peace, spiritual vitality, and holy joy as they faithfully shepherd Your people.","scripture":[],"o":"s-7-2-11","o2":"s-7-2-11"},{"text":"Lord, preserve them from betrayal and from every subtle device of Satan.","scripture":[],"o":"s-7-2-12","o2":"s-7-2-12"},{"text":"Father, let multitudes be saved, healed, discipled, equipped, and established in Christ through the ministry You have entrusted to them.","scripture":[],"o":"s-7-2-13","o2":"s-7-2-13"},{"text":"Lord Jesus, bless every member of their family with steadfast faith, divine protection, sound health, wisdom, fruitful service, and joyful obedience to Christ.","scripture":[],"o":"s-7-2-14","o2":"s-7-2-14"},{"text":"Father, let every generation arising from their household faithfully love You, serve You, proclaim the Gospel, and remain established in Your everlasting covenant.","scripture":[],"o":"s-7-2-15","o2":"s-7-2-15"},{"text":"Lord, grant them grace to continually walk with You with excellence, faithfulness, humility, and unwavering devotion to Jesus Christ.","scripture":[],"o":"s-7-2-16","o2":"s-7-2-16"},{"text":"Father, let the anointing upon their lives continually increase according to Your sovereign will, and let the GRA ministry through them bring revival, holiness, salvation, biblical discipleship, and Christ-centered transformation throughout the nations.","scripture":[],"o":"s-7-2-17","o2":"s-7-2-17"},{"text":"Lord Jesus, grant that through their faithful ministry many churches may be strengthened, many pastors encouraged, many missionaries equipped, and many believers established in the truth of Your Word.","scripture":[],"o":"s-7-2-18","o2":"s-7-2-18"},{"text":"Father, let them, their family, and their generations stand and live before You forever, keeping the faith and bringing lasting glory to the name of Jesus.","scripture":[],"o":"s-7-2-19","o2":"s-7-2-19"},{"text":"Thank You, Heavenly Father, because You are the One who calls, equips, preserves, perfects, and establishes Your servants. Continue to bless, promote, elevate, strengthen, preserve, and perfect our Father and Mother in the Lord and their entire family until the glorious appearing of our great God and Savior, Jesus Christ. May all honor, praise, dominion, and glory belong to Him alone forever. Amen.","scripture":[],"o":"s-7-2-20","o2":"s-7-2-20"},{"text":"Strengthen, protect, and continually anoint our Father in the Lord for faithful ministry.","scripture":[{"ref":"Acts 20:28","verses":[{"n":"28","text":"“Take heed therefore unto yourselves, and to all the flock, over the which the Holy Ghost hath made you overseers, to feed the church of God, which he hath purchased with his own blood.”"}]}],"o":"s-7-3-1","o2":"s-7-2-21"},{"text":"Empower every minister with grace, wisdom, and boldness.","scripture":[{"ref":"2 Thessalonians 3:1","verses":[{"n":"1","text":"“Finally, brethren, pray for us, that the word of the Lord may have free course, and be glorified, even as it is with you:”"}]}],"o":"s-7-4-1","o2":"s-7-2-22"},{"text":"Anoint Your servant afresh. Grant boldness, wisdom, compassion, revelation, and utterance.","scripture":[{"ref":"2 Timothy 4:2","verses":[{"n":"2","text":"“Preach the word; be instant in season, out of season; reprove, rebuke, exhort with all longsuffering and doctrine.”"}]}],"o":"s-7-5-1","o2":"s-7-2-23"}]}]},{"label":"Part NINE","title":"SOULS, EVANGELISM, AND THE HARVEST","subtitle":"Prayers for the lost, for the laborers, and for the advance of the Gospel","sections":[{"orig":54,"title":"Prayer for Fruitful Evangelism, Soul Winning, Discipleship, and Faithful Members to Be Added to GRA by the Power of the Holy Spirit","foundation":[{"ref":"Matthew 28:19–20","verses":[{"n":"19","text":"“Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:"},{"n":"20","text":"Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.”"}]},{"ref":"Acts 2:47","verses":[{"n":"47","text":"“Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved.”"}]},{"ref":"John 15:16","verses":[{"n":"16","text":"“Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.”"}]},{"ref":"Romans 10:14–15","verses":[{"n":"14","text":"“How then shall they call on him in whom they have not believed? and how shall they believe in him of whom they have not heard? and how shall they hear without a preacher?"},{"n":"15","text":"And how shall they preach, except they be sent? as it is written, How beautiful are the feet of them that preach the gospel of peace, and bring glad tidings of good things!”"}]}],"prayers":[{"text":"Father, by the power of the Holy Spirit, make every member of GRA a faithful witness of the Lord Jesus Christ wherever we go.","scripture":[],"o":"s-9-1-1","o2":"s-9-1-1"},{"text":"Lord Jesus, baptize us afresh with the Holy Ghost and with holy boldness to preach the Gospel with love, wisdom, humility, and conviction.","scripture":[],"o":"s-9-1-2","o2":"s-9-1-2"},{"text":"Father, let thousands upon thousands be genuinely converted through the ministry of GRA worldwide and become faithful disciples of Jesus Christ.","scripture":[],"o":"s-9-1-3","o2":"s-9-1-3"},{"text":"Lord, add daily to every GRA church those who are truly being saved, transformed, and established in the faith.","scripture":[],"o":"s-9-1-4","o2":"s-9-1-4"},{"text":"Father, let every soul won through GRA become deeply rooted in Your Word, steadfast in prayer, faithful in fellowship, and fruitful in Christian service.","scripture":[],"o":"s-9-1-5","o2":"s-9-1-5"},{"text":"Lord Jesus, deliver us from merely counting decisions. Grant us the grace to make mature disciples who obey all that You have commanded.","scripture":[],"o":"s-9-1-6","o2":"s-9-1-6"},{"text":"Father, let every outreach, crusade, house fellowship, Bible study, revival meeting, conference, media ministry, and missionary effort produce abundant and lasting spiritual fruit.","scripture":[],"o":"s-9-1-7","o2":"s-9-1-7"},{"text":"Lord, fill every GRA evangelist, pastor, missionary, worker, and member with genuine compassion for lost souls, just as Christ had compassion upon the multitudes.","scripture":[],"o":"s-9-1-8","o2":"s-9-1-8"},{"text":"Father, send Your Holy Spirit ahead of us to prepare hearts, convict sinners, open blind eyes, and draw people irresistibly to Christ.","scripture":[],"o":"s-9-1-9","o2":"s-9-1-9"},{"text":"Lord Jesus, destroy every spiritual blindness, deception, unbelief, hardness of heart, and stronghold that keeps people from receiving the Gospel.","scripture":[],"o":"s-9-1-10","o2":"s-9-1-10"},{"text":"Father, make every GRA church a welcoming spiritual family where new believers are loved, nurtured, encouraged, and established in biblical truth.","scripture":[],"o":"s-9-1-11","o2":"s-9-1-11"},{"text":"Lord, raise faithful disciplers, Bible teachers, mentors, small-group leaders, and spiritual fathers and mothers to care for every new believer.","scripture":[],"o":"s-9-1-12","o2":"s-9-1-12"},{"text":"Father, let every convert discover his or her spiritual gifts and become an active, joyful, and fruitful servant in the Body of Christ.","scripture":[],"o":"s-9-1-13","o2":"s-9-1-13"},{"text":"Lord Jesus, preserve every new believer from false doctrine, offense, temptation, discouragement, and falling away from the faith.","scripture":[],"o":"s-9-1-14","o2":"s-9-1-14"},{"text":"Father, let children, youths, adults, entire households, communities, and nations come to saving faith through the ministry of GRA.","scripture":[],"o":"s-9-1-15","o2":"s-9-1-15"},{"text":"Lord, grant us divine appointments every day with people whose hearts You have prepared to hear the Gospel.","scripture":[],"o":"s-9-1-16","o2":"s-9-1-16"},{"text":"Father, make me personally a fruitful soul winner. Give me wisdom, boldness, compassion, patience, and perseverance to faithfully preach Christ and disciple those You entrust to me.","scripture":[],"o":"s-9-1-17","o2":"s-9-1-17"},{"text":"Lord Jesus, let every faithful member added to GRA become another faithful soul winner, so that disciples continually make more disciples until the whole earth hears the Gospel.","scripture":[],"o":"s-9-1-18","o2":"s-9-1-18"},{"text":"Father, let GRA become known throughout the nations as a Christ-centered, Bible-believing, Holy Spirit-empowered, disciple-making church that glorifies Jesus in doctrine, worship, holiness, missions, and love.","scripture":[],"o":"s-9-1-19","o2":"s-9-1-19"},{"text":"Thank You, Heavenly Father, because the harvest belongs to You. By the power of the Holy Spirit, make GRA worldwide fruitful in evangelism, faithful in discipleship, steadfast in biblical truth, overflowing with devoted members, and effective in fulfilling the Great Commission until the glorious return of our Lord Jesus Christ. Amen.","scripture":[],"o":"s-9-1-20","o2":"s-9-1-20"},{"text":"Father, in the name of Jesus, let all our gatherings and meetings become a divine harvest of souls. Draw sinners, backsliders, seekers, and the brokenhearted by the irresistible power of the Holy Spirit. Remove every veil from blinded minds, convict every heart of sin, righteousness, and judgment, and grant genuine repentance unto life. Let many openly confess Jesus Christ as Lord and Savior, and let their names be written in the Lamb’s Book of Life. Let every message, every prayer, every testimony, and every song point men and women to the Cross of Christ. Add daily to Your Church such as should be saved, and let every service produce lasting fruit for eternity, all to the praise and glory of Your holy name.","scripture":[{"ref":"Luke 19:10","verses":[{"n":"10","text":"“For the Son of man is come to seek and to save that which was lost.”"}]},{"ref":"Acts 2:47","verses":[{"n":"47","text":"“Praising God, and having favour with all the people. And the Lord added to the church daily such as should be saved.”"}]},{"ref":"John 6:44","verses":[{"n":"44","text":"“No man can come to me, except the Father which hath sent me draw him: and I will raise him up at the last day.”"}]},{"ref":"2 Peter 3:9","verses":[{"n":"9","text":"“The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.”"}]},{"ref":"Romans 10:13","verses":[{"n":"13","text":"“For whosoever shall call upon the name of the Lord shall be saved.”"}]}],"o":"s-9-2-1","o2":"s-9-1-21"},{"text":"Raise many laborers committed to soul-winning.","scripture":[{"ref":"Matthew 9:38","verses":[{"n":"38","text":"“Pray ye therefore the Lord of the harvest, that he will send forth labourers into his harvest.”"}]}],"o":"s-9-3-1","o2":"s-9-1-22"},{"text":"Let every convert become a faithful disciple of Christ.","scripture":[{"ref":"Matthew 28:20","verses":[{"n":"20","text":"“Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.”"}]}],"o":"s-9-4-1","o2":"s-9-1-23"},{"text":"Establish every new believer firmly in Christ.","scripture":[{"ref":"1 Peter 2:2","verses":[{"n":"2","text":"“As newborn babes, desire the sincere milk of the word, that ye may grow thereby:”"}]}],"o":"s-9-5-1","o2":"s-9-1-24"}]},{"orig":60,"title":"Prayer for Divine Harvest","foundation":[{"ref":"John 4:35","verses":[{"n":"35","text":"“Say not ye, There are yet four months, and then cometh harvest? behold, I say unto you, Lift up your eyes, and look on the fields; for they are white already to harvest.”"}]}],"prayers":[{"text":"Father, bring multitudes into Your Kingdom in all our gatherings and meetings.","scripture":[],"o":"s-9-7-1","o2":"s-9-2-1"},{"text":"Lord, save entire families.","scripture":[],"o":"s-9-7-2","o2":"s-9-2-2"},{"text":"Father, let backsliders return.","scripture":[],"o":"s-9-7-3","o2":"s-9-2-3"},{"text":"Lord, draw seekers unto Christ.","scripture":[],"o":"s-9-7-4","o2":"s-9-2-4"},{"text":"Father, multiply genuine conversions.","scripture":[],"o":"s-9-7-5","o2":"s-9-2-5"},{"text":"Lord, establish new believers.","scripture":[],"o":"s-9-7-6","o2":"s-9-2-6"},{"text":"Father, add daily to the Church.","scripture":[],"o":"s-9-7-7","o2":"s-9-2-7"},{"text":"Lord, send laborers into the harvest.","scripture":[],"o":"s-9-7-8","o2":"s-9-2-8"},{"text":"Father, let every soul won remain faithful.","scripture":[],"o":"s-9-7-9","o2":"s-9-2-9"},{"text":"Lord, receive all the glory.","scripture":[],"o":"s-9-7-10","o2":"s-9-2-10"},{"text":"Restore every wandering soul to fellowship with Christ.","scripture":[{"ref":"Hosea 14:4","verses":[{"n":"4","text":"“I will heal their backsliding, I will love them freely: for mine anger is turned away from him.”"}]}],"o":"s-9-6-1","o2":"s-9-2-11"}]},{"orig":63,"title":"Prayer for Kingdom Establishment","foundation":[{"ref":"Matthew 6:10","verses":[{"n":"10","text":"“Thy kingdom come. Thy will be done in earth, as it is in heaven.”"}]}],"prayers":[{"text":"Father, establish Your Kingdom in every heart.","scripture":[],"o":"s-9-10-1","o2":"s-9-3-1"},{"text":"Lord, let Your will prevail.","scripture":[],"o":"s-9-10-2","o2":"s-9-3-2"},{"text":"Father, destroy every kingdom of darkness.","scripture":[],"o":"s-9-10-3","o2":"s-9-3-3"},{"text":"Lord, establish righteousness.","scripture":[],"o":"s-9-10-4","o2":"s-9-3-4"},{"text":"Father, establish peace.","scripture":[],"o":"s-9-10-5","o2":"s-9-3-5"},{"text":"Lord, establish joy in the Holy Ghost.","scripture":[],"o":"s-9-10-6","o2":"s-9-3-6"},{"text":"Father, establish truth.","scripture":[],"o":"s-9-10-7","o2":"s-9-3-7"},{"text":"Lord, establish holiness.","scripture":[],"o":"s-9-10-8","o2":"s-9-3-8"},{"text":"Father, establish faithful disciples.","scripture":[],"o":"s-9-10-9","o2":"s-9-3-9"},{"text":"Lord, establish GRA for generations to come.","scripture":[],"o":"s-9-10-10","o2":"s-9-3-10"},{"text":"Strengthen missionaries and raise more laborers for the nations.","scripture":[{"ref":"Mark 16:15","verses":[{"n":"15","text":"“And he said unto them, Go ye into all the world, and preach the gospel to every creature.”"}]}],"o":"s-9-8-1","o2":"s-9-3-11"},{"text":"Use every one of our services and gatherings to advance Your Kingdom locally and globally.","scripture":[{"ref":"Matthew 24:14","verses":[{"n":"14","text":"“And this gospel of the kingdom shall be preached in all the world for a witness unto all nations; and then shall the end come.”"}]}],"o":"s-9-9-1","o2":"s-9-3-12"}]}]},{"label":"Part TEN","title":"THE PRESENCE AND POWER OF GOD IN OUR GATHERINGS","subtitle":"Prayers for God’s glory, His Spirit, and His mighty works among His people","sections":[{"orig":65,"title":"Prayer for the Manifest Presence of God in Every GRA Meeting That Brings Salvation, Miracles, Signs, Wonders, and Deliverance","foundation":[{"ref":"Exodus 33:14","verses":[{"n":"14","text":"“And he said, My presence shall go with thee, and I will give thee rest.”"}]},{"ref":"2 Chronicles 5:13–14","verses":[{"n":"13","text":"“It came even to pass, as the trumpeters and singers were as one, to make one sound to be heard in praising and thanking the LORD; and when they lifted up their voice with the trumpets and cymbals and instruments of musick, and praised the LORD, saying, For he is good; for his mercy endureth for ever: that then the house was filled with a cloud, even the house of the LORD;"},{"n":"14","text":"So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God.”"}]},{"ref":"Acts 4:31","verses":[{"n":"31","text":"“And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness.”"}]},{"ref":"Mark 16:20","verses":[{"n":"20","text":"“And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.”"}]}],"prayers":[{"text":"Father, let Your manifest presence fill every GRA meeting until every heart knows that the living God is truly in our midst.","scripture":[],"o":"s-10-2-1","o2":"s-10-1-1"},{"text":"Lord Jesus, let every worship service, prayer meeting, Bible study, revival, conference, and fellowship become a holy meeting place between heaven and earth.","scripture":[],"o":"s-10-2-2","o2":"s-10-1-2"},{"text":"Father, let the glory of the Lord overshadow every GRA sanctuary as it filled the Tabernacle in the wilderness and Solomon’s Temple.","scripture":[],"o":"s-10-2-3","o2":"s-10-1-3"},{"text":"Lord, let Your holy presence bring deep conviction of sin, genuine repentance, and lasting salvation to every unbeliever who enters our meetings.","scripture":[],"o":"s-10-2-4","o2":"s-10-1-4"},{"text":"Father, let hardened hearts be broken, blind eyes be opened to the truth of the Gospel, and captives be set free by the power of the Holy Spirit.","scripture":[],"o":"s-10-2-5","o2":"s-10-1-5"},{"text":"Lord Jesus, stretch forth Your hand to heal. Let the sick recover, the oppressed be delivered, and the brokenhearted be restored according to Your perfect will.","scripture":[],"o":"s-10-2-6","o2":"s-10-1-6"},{"text":"Father, let biblical signs and wonders accompany the faithful preaching of Your Word, confirming that Jesus Christ is alive and reigning.","scripture":[],"o":"s-10-2-7","o2":"s-10-1-7"},{"text":"Lord, let every miracle performed in GRA exalt Christ alone, strengthen the faith of believers, and draw unbelievers to repentance.","scripture":[],"o":"s-10-2-8","o2":"s-10-1-8"},{"text":"Father, let every chain of sin, addiction, fear, bondage, oppression, deception, and despair be broken through the mighty power of the Holy Spirit.","scripture":[],"o":"s-10-2-9","o2":"s-10-1-9"},{"text":"Lord Jesus, let every GRA meeting become a place where people encounter the transforming power of Your grace rather than merely attend a religious gathering.","scripture":[],"o":"s-10-2-10","o2":"s-10-1-10"},{"text":"Father, let Your holy presence remove every distraction, every work of darkness, every spirit of confusion, and every hindrance to the moving of the Holy Spirit.","scripture":[],"o":"s-10-2-11","o2":"s-10-1-11"},{"text":"Lord, let worship ascend from pure hearts and let Your glory descend upon Your people with power, holiness, and peace.","scripture":[],"o":"s-10-2-12","o2":"s-10-1-12"},{"text":"Father, fill every preacher, teacher, worship leader, intercessor, musician, usher, and worker with fresh anointing and complete dependence upon the Holy Spirit.","scripture":[],"o":"s-10-2-13","o2":"s-10-1-13"},{"text":"Lord Jesus, let every message preached come with the demonstration of the Spirit and with power, producing faith, repentance, and spiritual maturity.","scripture":[],"o":"s-10-2-14","o2":"s-10-1-14"},{"text":"Father, let children, youths, adults, families, and visitors all experience the reality of Your presence and leave our meetings transformed by Christ.","scripture":[],"o":"s-10-2-15","o2":"s-10-1-15"},{"text":"Lord, let every testimony that arises from GRA proclaim Your mercy, Your faithfulness, and Your saving power to the nations.","scripture":[],"o":"s-10-2-16","o2":"s-10-1-16"},{"text":"Father, let the fear of the Lord rest upon every GRA assembly so that holiness, reverence, humility, and joyful obedience characterize our worship.","scripture":[],"o":"s-10-2-17","o2":"s-10-1-17"},{"text":"Lord Jesus, let Your presence continually abide in GRA, not only during our meetings but also in our homes, our workplaces, our schools, and our daily lives, making us faithful witnesses of Christ.","scripture":[],"o":"s-10-2-18","o2":"s-10-1-18"},{"text":"Father, let every GRA meeting become a foretaste of heaven, where Jesus Christ is exalted, the Holy Spirit moves freely according to Scripture, the Word is faithfully proclaimed, souls are saved, believers are strengthened, the sick are healed according to Your will, the oppressed are delivered, and Your holy name alone is glorified.","scripture":[],"o":"s-10-2-19","o2":"s-10-1-19"},{"text":"Thank You, Heavenly Father, because Your presence is our greatest treasure. May every GRA gathering be marked by the manifest presence of God, overflowing with salvation, holiness, biblical miracles, signs, wonders, deliverance, joy, peace, and enduring transformation, so that Jesus Christ alone will receive all the praise, honor, dominion, and glory forever. Amen.","scripture":[],"o":"s-10-2-20","o2":"s-10-1-20"},{"text":"Father, let Your glorious presence fill all our gatherings and meetings from the very beginning until the end. Let everyone who enters encounter the living Christ.","scripture":[{"ref":"Exodus 33:14","verses":[{"n":"14","text":"“And he said, My presence shall go with thee, and I will give thee rest.”"}]}],"o":"s-10-1-1","o2":"s-10-1-21"},{"text":"Lord Jesus, let Your Holy Spirit overshadow every aspect of the service. Let Your glory fill the sanctuary as You filled the tabernacle and the temple.","scripture":[{"ref":"Exodus 33:14","verses":[{"n":"14","text":"“And he said, My presence shall go with thee, and I will give thee rest.”"}]}],"o":"s-10-1-2","o2":"s-10-1-22"},{"text":"Father, let the Holy Spirit have absolute control over every aspect of all our gatherings and meetings. Let no flesh glory in Your presence, and let everything be directed according to Your perfect will.","scripture":[{"ref":"Zechariah 4:6","verses":[{"n":"6","text":"“Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.”"}]}],"o":"s-10-4-1","o2":"s-10-1-23"},{"text":"Father, let every captive go free and every chain be broken by the power of Jesus Christ.","scripture":[{"ref":"Luke 4:18","verses":[{"n":"18","text":"“The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised,”"}]}],"o":"s-10-14-1","o2":"s-10-1-24"}]},{"orig":66,"title":"Prayer for the Glory of God to Fill the Sanctuary","foundation":[{"ref":"2 Chronicles 5:13–14","verses":[{"n":"13","text":"“It came even to pass, as the trumpeters and singers were as one, to make one sound to be heard in praising and thanking the LORD; and when they lifted up their voice with the trumpets and cymbals and instruments of musick, and praised the LORD, saying, For he is good; for his mercy endureth for ever: that then the house was filled with a cloud, even the house of the LORD;"},{"n":"14","text":"So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God.”"}]}],"prayers":[{"text":"Father, let the glory of the Lord fill all our gatherings and meetings from the opening prayer until the closing benediction.","scripture":[],"o":"s-10-3-1","o2":"s-10-2-1"},{"text":"Lord Jesus, let every worshipper encounter the tangible manifestation of Your holy presence.","scripture":[],"o":"s-10-3-2","o2":"s-10-2-2"},{"text":"Holy Spirit, overshadow every song, every prayer, every testimony, and every sermon with heavenly glory.","scripture":[],"o":"s-10-3-3","o2":"s-10-2-3"},{"text":"Father, let every heart become a sanctuary for Your presence.","scripture":[],"o":"s-10-3-4","o2":"s-10-2-4"},{"text":"Lord, let Your glory silence every work of darkness and every distraction.","scripture":[],"o":"s-10-3-5","o2":"s-10-2-5"},{"text":"Father, let signs and wonders follow the manifestation of Your glory.","scripture":[],"o":"s-10-3-6","o2":"s-10-2-6"},{"text":"Lord, let Your glory produce repentance, holiness, worship, and obedience.","scripture":[],"o":"s-10-3-7","o2":"s-10-2-7"},{"text":"Father, let every visitor know that God is truly among His people.","scripture":[],"o":"s-10-3-8","o2":"s-10-2-8"},{"text":"Lord, let Your glory remain upon GRA long after each of our gatherings and meetings has ended.","scripture":[],"o":"s-10-3-9","o2":"s-10-2-9"},{"text":"Father, let all the glory, honor, praise, and thanksgiving belong to You alone forever.","scripture":[],"o":"s-10-3-10","o2":"s-10-2-10"},{"text":"Let every blessing from all our gatherings and meetings produce lasting spiritual fruit.","scripture":[{"ref":"John 15:16","verses":[{"n":"16","text":"“Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.”"}]}],"o":"s-10-19-1","o2":"s-10-2-11"},{"text":"Father, do exceedingly abundantly above all that we ask or think. Let all our gatherings and meetings overflow with Your presence, salvation, healings, miracles, deliverance, restoration, testimonies, unity, joy, holiness, revival, and lasting transformation, so that Jesus Christ alone will receive all the glory.","scripture":[{"ref":"Ephesians 3:20","verses":[{"n":"20","text":"“Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us,”"}]}],"o":"s-10-20-1","o2":"s-10-2-12"}]},{"orig":69,"title":"Prayer for Open Heavens","foundation":[{"ref":"Malachi 3:10","verses":[{"n":"10","text":"“Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the LORD of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it.”"}]}],"prayers":[{"text":"Father, open the heavens over all our gatherings and meetings.","scripture":[],"o":"s-10-6-1","o2":"s-10-3-1"},{"text":"Lord, let revelation flow freely.","scripture":[],"o":"s-10-6-2","o2":"s-10-3-2"},{"text":"Father, let miracles descend from heaven.","scripture":[],"o":"s-10-6-3","o2":"s-10-3-3"},{"text":"Lord, pour out Your blessings.","scripture":[],"o":"s-10-6-4","o2":"s-10-3-4"},{"text":"Father, release angelic ministry.","scripture":[],"o":"s-10-6-5","o2":"s-10-3-5"},{"text":"Lord, send refreshing from Your presence.","scripture":[],"o":"s-10-6-6","o2":"s-10-3-6"},{"text":"Father, let heaven touch earth.","scripture":[],"o":"s-10-6-7","o2":"s-10-3-7"},{"text":"Lord, let every prayer receive divine attention.","scripture":[],"o":"s-10-6-8","o2":"s-10-3-8"},{"text":"Father, let Your Spirit move without hindrance.","scripture":[],"o":"s-10-6-9","o2":"s-10-3-9"},{"text":"Lord, let heaven rejoice over every soul saved.","scripture":[],"o":"s-10-6-10","o2":"s-10-3-10"},{"text":"Father, pour out Your Holy Spirit upon every worshipper. Let there be fresh fire, fresh anointing, spiritual renewal, and revival throughout the congregation.","scripture":[{"ref":"Joel 2:28","verses":[{"n":"28","text":"“And it shall come to pass afterward, that I will pour out my spirit upon all flesh; and your sons and your daughters shall prophesy, your old men shall dream dreams, your young men shall see visions:”"}]}],"o":"s-10-5-1","o2":"s-10-3-11"}]},{"orig":71,"title":"Prayer for Divine Visitation Upon Every Soul","foundation":[{"ref":"Luke 7:16","verses":[{"n":"16","text":"“And there came a fear on all: and they glorified God, saying, That a great prophet is risen up among us; and, That God hath visited his people.”"}]}],"prayers":[{"text":"Father, visit every worshipper personally.","scripture":[],"o":"s-10-8-1","o2":"s-10-4-1"},{"text":"Lord, visit every family.","scripture":[],"o":"s-10-8-2","o2":"s-10-4-2"},{"text":"Father, visit every ministry.","scripture":[],"o":"s-10-8-3","o2":"s-10-4-3"},{"text":"Lord, visit every sick person.","scripture":[],"o":"s-10-8-4","o2":"s-10-4-4"},{"text":"Father, visit every discouraged heart.","scripture":[],"o":"s-10-8-5","o2":"s-10-4-5"},{"text":"Lord, visit every broken home.","scripture":[],"o":"s-10-8-6","o2":"s-10-4-6"},{"text":"Father, visit every waiting soul.","scripture":[],"o":"s-10-8-7","o2":"s-10-4-7"},{"text":"Lord, visit every child.","scripture":[],"o":"s-10-8-8","o2":"s-10-4-8"},{"text":"Father, visit every elder.","scripture":[],"o":"s-10-8-9","o2":"s-10-4-9"},{"text":"Lord, let all our gatherings and meetings become times of divine visitation.","scripture":[],"o":"s-10-8-10","o2":"s-10-4-10"},{"text":"Visit Your people with extraordinary manifestations of Your mercy and grace.","scripture":[{"ref":"Luke 1:68","verses":[{"n":"68","text":"“Blessed be the Lord God of Israel; for he hath visited and redeemed his people,”"}]}],"o":"s-10-7-1","o2":"s-10-4-11"}]},{"orig":73,"title":"Prayer for Unprecedented Miracles, Signs, Wonders, and Great Testimonies Throughout GRA Worldwide","foundation":[{"ref":"Mark 16:17–20","verses":[{"n":"17","text":"“And these signs shall follow them that believe; In my name shall they cast out devils; they shall speak with new tongues;"},{"n":"18","text":"They shall take up serpents; and if they drink any deadly thing, it shall not hurt them; they shall lay hands on the sick, and they shall recover."},{"n":"19","text":"So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of God."},{"n":"20","text":"And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.”"}]},{"ref":"Acts 4:29–30","verses":[{"n":"29","text":"“And now, Lord, behold their threatenings: and grant unto thy servants, that with all boldness they may speak thy word,"},{"n":"30","text":"By stretching forth thine hand to heal; and that signs and wonders may be done by the name of thy holy child Jesus.”"}]},{"ref":"John 14:12","verses":[{"n":"12","text":"“Verily, verily, I say unto you, He that believeth on me, the works that I do shall he do also; and greater works than these shall he do; because I go unto my Father.”"}]},{"ref":"Hebrews 2:4","verses":[{"n":"4","text":"“God also bearing them witness, both with signs and wonders, and with divers miracles, and gifts of the Holy Ghost, according to his own will?”"}]}],"prayers":[{"text":"Father, stretch forth Your mighty hand throughout GRA worldwide, and let signs, wonders, and miracles accompany the preaching of the Gospel, bringing glory to Jesus Christ alone.","scripture":[],"o":"s-10-10-1","o2":"s-10-5-1"},{"text":"Lord Jesus, confirm Your Word in every GRA assembly with genuine biblical miracles according to Your sovereign will, so that many may believe in You.","scripture":[],"o":"s-10-10-2","o2":"s-10-5-2"},{"text":"Father, let unprecedented numbers of sinners be genuinely converted through the demonstration of Your truth, Your power, and the conviction of the Holy Spirit.","scripture":[],"o":"s-10-10-3","o2":"s-10-5-3"},{"text":"Lord, heal the sick, restore the brokenhearted, deliver the oppressed, and comfort the afflicted in every GRA church according to Your mercy and perfect will.","scripture":[],"o":"s-10-10-4","o2":"s-10-5-4"},{"text":"Father, let blind eyes be opened, deaf ears hear, the lame walk, and those suffering from every kind of illness experience Your healing according to Your gracious purpose.","scripture":[],"o":"s-10-10-5","o2":"s-10-5-5"},{"text":"Lord Jesus, let every miracle performed through GRA direct all praise to You and never to any human being.","scripture":[],"o":"s-10-10-6","o2":"s-10-5-6"},{"text":"Father, let there be mighty testimonies of salvation, restoration, reconciliation, answered prayer, and transformed lives from every nation where GRA ministers.","scripture":[],"o":"s-10-10-7","o2":"s-10-5-7"},{"text":"Lord, fill every pastor, minister, missionary, elder, deacon, worker, and member of GRA with fresh boldness to proclaim Christ faithfully.","scripture":[],"o":"s-10-10-8","o2":"s-10-5-8"},{"text":"Father, let every GRA altar become a place where Your holy presence is known, Your Word is honored, and Christ is exalted.","scripture":[],"o":"s-10-10-9","o2":"s-10-5-9"},{"text":"Lord Jesus, let every testimony strengthen the faith of believers and draw unbelievers to repentance.","scripture":[],"o":"s-10-10-10","o2":"s-10-5-10"},{"text":"Father, let hospitals, homes, prisons, schools, workplaces, villages, towns, and cities hear of the mighty works You are doing through the preaching of the Gospel.","scripture":[],"o":"s-10-10-11","o2":"s-10-5-11"},{"text":"Lord, let every miracle deepen reverence for Scripture, increase holiness, and produce faithful disciples rather than mere amazement.","scripture":[],"o":"s-10-10-12","o2":"s-10-5-12"},{"text":"Father, let every impossible situation brought before You become an opportunity for Your name to be glorified.","scripture":[],"o":"s-10-10-13","o2":"s-10-5-13"},{"text":"Lord Jesus, raise men and women of deep prayer, unwavering faith, sound doctrine, humility, and Christlike character throughout GRA worldwide.","scripture":[],"o":"s-10-10-14","o2":"s-10-5-14"},{"text":"Father, frustrate every counterfeit sign, deception, false miracle, and every work of the enemy that seeks to dishonor the Gospel of Christ.","scripture":[],"o":"s-10-10-15","o2":"s-10-5-15"},{"text":"Lord, let every genuine miracle be firmly established upon the truth of Your Word and produce lasting spiritual fruit.","scripture":[],"o":"s-10-10-16","o2":"s-10-5-16"},{"text":"Father, let the testimonies arising from GRA encourage missionaries, strengthen pastors, revive churches, and inspire believers around the world to trust in You more deeply.","scripture":[],"o":"s-10-10-17","o2":"s-10-5-17"},{"text":"Lord Jesus, let children, youths, adults, and the elderly alike experience Your transforming grace, and let entire families come to saving faith in Christ.","scripture":[],"o":"s-10-10-18","o2":"s-10-5-18"},{"text":"Father, may the nations hear of what You are doing through GRA, not for the exaltation of any ministry or individual, but so that Jesus Christ alone may be magnified among all peoples.","scripture":[],"o":"s-10-10-19","o2":"s-10-5-19"},{"text":"Thank You, Heavenly Father, because You are the God who still saves, heals, restores, delivers, answers prayer, and confirms the preaching of the Gospel. Let GRA worldwide become a faithful instrument through which countless people encounter Jesus Christ, mature in the faith, and bring everlasting glory to Your holy name until the return of our Lord and Savior.","scripture":[],"o":"s-10-10-20","o2":"s-10-5-20"},{"text":"Let spiritual gifts operate biblically for the edification of the Church.","scripture":[{"ref":"1 Corinthians 12:7","verses":[{"n":"7","text":"“But the manifestation of the Spirit is given to every man to profit withal.”"}]}],"o":"s-10-9-1","o2":"s-10-5-21"},{"text":"Father, confirm Your Word with mighty miracles that glorify the name of Jesus Christ.","scripture":[{"ref":"Mark 16:20","verses":[{"n":"20","text":"“And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen.”"}]}],"o":"s-10-11-1","o2":"s-10-5-22"},{"text":"Confirm Your Gospel with signs that glorify Jesus alone.","scripture":[{"ref":"Acts 4:30","verses":[{"n":"30","text":"“By stretching forth thine hand to heal; and that signs and wonders may be done by the name of thy holy child Jesus.”"}]}],"o":"s-10-12-1","o2":"s-10-5-23"},{"text":"Lord Jesus, heal every sickness, disease, pain, infirmity, and affliction according to Your perfect will.","scripture":[{"ref":"Jeremiah 17:14","verses":[{"n":"14","text":"“Heal me, O LORD, and I shall be healed; save me, and I shall be saved: for thou art my praise.”"}]}],"o":"s-10-13-1","o2":"s-10-5-24"},{"text":"Let all our gatherings and meetings produce undeniable testimonies of salvation, healing, restoration, and answered prayer.","scripture":[{"ref":"Psalm 126:3","verses":[{"n":"3","text":"“The LORD hath done great things for us; whereof we are glad.”"}]}],"o":"s-10-18-1","o2":"s-10-5-25"}]},{"orig":79,"title":"Prayer for Supernatural Acceleration","foundation":[{"ref":"Amos 9:13","verses":[{"n":"13","text":"“Behold, the days come, saith the LORD, that the plowman shall overtake the reaper, and the treader of grapes him that soweth seed; and the mountains shall drop sweet wine, and all the hills shall melt.”"}]}],"prayers":[{"text":"Father, accelerate every delayed blessing.","scripture":[],"o":"s-10-16-1","o2":"s-10-6-1"},{"text":"Lord, accelerate church growth.","scripture":[],"o":"s-10-16-2","o2":"s-10-6-2"},{"text":"Father, accelerate soul winning.","scripture":[],"o":"s-10-16-3","o2":"s-10-6-3"},{"text":"Lord, accelerate healing.","scripture":[],"o":"s-10-16-4","o2":"s-10-6-4"},{"text":"Father, accelerate restoration.","scripture":[],"o":"s-10-16-5","o2":"s-10-6-5"},{"text":"Lord, accelerate divine promotion.","scripture":[],"o":"s-10-16-6","o2":"s-10-6-6"},{"text":"Father, accelerate spiritual maturity.","scripture":[],"o":"s-10-16-7","o2":"s-10-6-7"},{"text":"Lord, accelerate Kingdom expansion.","scripture":[],"o":"s-10-16-8","o2":"s-10-6-8"},{"text":"Father, accelerate the fulfillment of every prophetic word.","scripture":[],"o":"s-10-16-9","o2":"s-10-6-9"},{"text":"Lord, let all our gatherings and meetings become times of supernatural speed.","scripture":[],"o":"s-10-16-10","o2":"s-10-6-10"},{"text":"Let impossible situations be transformed according to Your will.","scripture":[{"ref":"Isaiah 43:19","verses":[{"n":"19","text":"“Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.”"}]}],"o":"s-10-15-1","o2":"s-10-6-11"}]},{"orig":80,"title":"Prayer for Divine Remembrance","foundation":[{"ref":"Genesis 8:1","verses":[{"n":"1","text":"“And God remembered Noah, and every living thing, and all the cattle that was with him in the ark: and God made a wind to pass over the earth, and the waters asswaged;”"}]}],"prayers":[{"text":"Father, remember every family represented in all our gatherings and meetings.","scripture":[],"o":"s-10-17-1","o2":"s-10-7-1"},{"text":"Father, remember every prayer that has been waiting for an answer.","scripture":[],"o":"s-10-17-2","o2":"s-10-7-2"},{"text":"Lord, remember every barren womb.","scripture":[],"o":"s-10-17-3","o2":"s-10-7-3"},{"text":"Father, remember every unemployed person.","scripture":[],"o":"s-10-17-4","o2":"s-10-7-4"},{"text":"Lord, remember every sick person.","scripture":[],"o":"s-10-17-5","o2":"s-10-7-5"},{"text":"Father, remember every missionary.","scripture":[],"o":"s-10-17-6","o2":"s-10-7-6"},{"text":"Lord, remember every minister.","scripture":[],"o":"s-10-17-7","o2":"s-10-7-7"},{"text":"Father, remember every financial need.","scripture":[],"o":"s-10-17-8","o2":"s-10-7-8"},{"text":"Lord, remember every promise You have spoken over GRA.","scripture":[],"o":"s-10-17-9","o2":"s-10-7-9"},{"text":"Father, let all our gatherings and meetings become times of divine remembrance.","scripture":[],"o":"s-10-17-10","o2":"s-10-7-10"}]},{"title":"Prayer for the Word, the Worship, and the Work of the House","foundation":[],"prayers":[{"text":"Lord, let Your Word come with power, clarity, conviction, wisdom, and life-changing authority.","scripture":[{"ref":"Isaiah 55:11","verses":[{"n":"11","text":"“So shall my word be that goeth forth out of my mouth: it shall not return unto me void, but it shall accomplish that which I please, and it shall prosper in the thing whereto I sent it.”"}]}],"o":"s-11-1-1","o2":"s-10-8-1"},{"text":"Lord, inhabit every song of worship and praise. Let worship draw hearts into Your presence.","scripture":[{"ref":"Psalm 22:3","verses":[{"n":"3","text":"“But thou art holy, O thou that inhabitest the praises of Israel.”"}]}],"o":"s-11-2-1","o2":"s-10-8-2"},{"text":"Anoint every worship leader and musician to minister under the power of the Holy Spirit.","scripture":[{"ref":"2 Chronicles 5:13–14","verses":[{"n":"13","text":"“It came even to pass, as the trumpeters and singers were as one, to make one sound to be heard in praising and thanking the LORD; and when they lifted up their voice with the trumpets and cymbals and instruments of musick, and praised the LORD, saying, For he is good; for his mercy endureth for ever: that then the house was filled with a cloud, even the house of the LORD;"},{"n":"14","text":"So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God.”"}]}],"o":"s-11-3-1","o2":"s-10-8-3"},{"text":"Strengthen every intercessor to pray with faith, authority, and sensitivity to the Holy Spirit.","scripture":[{"ref":"James 5:16","verses":[{"n":"16","text":"“Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.”"}]}],"o":"s-11-4-1","o2":"s-10-8-4"},{"text":"Bless every worker with joy, excellence, humility, wisdom, and servant-heartedness.","scripture":[{"ref":"Colossians 3:23","verses":[{"n":"23","text":"“And whatsoever ye do, do it heartily, as to the Lord, and not unto men;”"}]}],"o":"s-11-5-1","o2":"s-10-8-5"},{"text":"Provide abundantly for every need of the ministry and every worshipper.","scripture":[{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]}],"o":"s-11-6-1","o2":"s-10-8-6"},{"text":"Protect every person traveling to and from all our gatherings and meetings.","scripture":[{"ref":"Psalm 91:11","verses":[{"n":"11","text":"“For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-11-7-1","o2":"s-10-8-7"},{"text":"Surround the church with divine favor before God and men.","scripture":[{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]}],"o":"s-11-8-1","o2":"s-10-8-8"},{"text":"Lead the church according to Your perfect will.","scripture":[{"ref":"Proverbs 3:5–6","verses":[{"n":"5","text":"“Trust in the LORD with all thine heart; and lean not unto thine own understanding."},{"n":"6","text":"In all thy ways acknowledge him, and he shall direct thy paths.”"}]}],"o":"s-11-9-1","o2":"s-10-8-9"},{"text":"Grant wisdom to every leader making decisions.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"o":"s-11-10-1","o2":"s-10-8-10"}]},{"orig":13,"title":"Prayer for Divine Thanksgiving","foundation":[{"ref":"Psalm 100:4","verses":[{"n":"4","text":"“Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.”"}]}],"prayers":[{"text":"Father, we thank You for all our gatherings and meetings.","scripture":[],"o":"s-1-1-1","o2":"s-10-9-1"},{"text":"Thank You for every soul You will save.","scripture":[],"o":"s-1-1-2","o2":"s-10-9-2"},{"text":"Thank You for every healing You will perform.","scripture":[],"o":"s-1-1-3","o2":"s-10-9-3"},{"text":"Thank You for every miracle You will work.","scripture":[],"o":"s-1-1-4","o2":"s-10-9-4"},{"text":"Thank You for every testimony You will produce.","scripture":[],"o":"s-1-1-5","o2":"s-10-9-5"},{"text":"Thank You for every life You will restore.","scripture":[],"o":"s-1-1-6","o2":"s-10-9-6"},{"text":"Thank You for every burden You will remove.","scripture":[],"o":"s-1-1-7","o2":"s-10-9-7"},{"text":"Thank You for every chain You will break.","scripture":[],"o":"s-1-1-8","o2":"s-10-9-8"},{"text":"Thank You for Your abiding presence.","scripture":[],"o":"s-1-1-9","o2":"s-10-9-9"},{"text":"Thank You because Jesus Christ alone shall receive all the glory.","scripture":[],"o":"s-1-1-10","o2":"s-10-9-10"}]},{"orig":15,"title":"Prayer for Christ to Be Glorified Above All","foundation":[{"ref":"John 3:30","verses":[{"n":"30","text":"“He must increase, but I must decrease.”"}]},{"ref":"Colossians 1:18","verses":[{"n":"18","text":"“And he is the head of the body, the church: who is the beginning, the firstborn from the dead; that in all things he might have the preeminence.”"}]}],"prayers":[{"text":"Father, let Jesus Christ alone be exalted in all our gatherings and meetings.","scripture":[],"o":"s-1-3-1","o2":"s-10-10-1"},{"text":"Let every sermon glorify Christ.","scripture":[],"o":"s-1-3-2","o2":"s-10-10-2"},{"text":"Let every song glorify Christ.","scripture":[],"o":"s-1-3-3","o2":"s-10-10-3"},{"text":"Let every miracle glorify Christ.","scripture":[],"o":"s-1-3-4","o2":"s-10-10-4"},{"text":"Let every healing glorify Christ.","scripture":[],"o":"s-1-3-5","o2":"s-10-10-5"},{"text":"Let every testimony glorify Christ.","scripture":[],"o":"s-1-3-6","o2":"s-10-10-6"},{"text":"Let every soul won glorify Christ.","scripture":[],"o":"s-1-3-7","o2":"s-10-10-7"},{"text":"Let every worker glorify Christ through faithful service.","scripture":[],"o":"s-1-3-8","o2":"s-10-10-8"},{"text":"Let every visitor leave saying, “God is truly in this place.”","scripture":[],"o":"s-1-3-9","o2":"s-10-10-9"},{"text":"Father, let all our gatherings and meetings become a lasting memorial to the greatness, majesty, power, holiness, mercy, and glory of our Lord Jesus Christ. Amen.","scripture":[],"o":"s-1-3-10","o2":"s-10-10-10"},{"text":"Let Jesus Christ alone be exalted in all our gatherings and meetings, and let Him draw many people to Himself.","scripture":[{"ref":"John 12:32","verses":[{"n":"32","text":"“And I, if I be lifted up from the earth, will draw all men unto me.”"}]}],"o":"s-1-2-1","o2":"s-10-10-11"}]}]},{"label":"Part SIX","title":"MY CALLING, MY SERVICE, AND MY FUTURE","subtitle":"Prayers for the assignments God has entrusted to me and the days that lie ahead","sections":[{"orig":34,"title":"Pleading the Blood of Jesus Over My Divine Assignments","foundation":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"Acts 20:24","verses":[{"n":"24","text":"“But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.”"}]},{"ref":"2 Timothy 4:7","verses":[{"n":"7","text":"“I have fought a good fight, I have finished my course, I have kept the faith:”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over every divine assignment You have entrusted to me in GRA Central. Let the Blood of the everlasting covenant sanctify, establish, preserve, and prosper every work You have called me to do.","scripture":[],"o":"s-6-1-1","o2":"s-6-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over my calling, my ministry in God’s Remnant Assembly, my service, my responsibilities, and my divine assignments than every accusation, opposition, delay, discouragement, or failure.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-6-1-2","o2":"s-6-1-2"},{"text":"Father, by the Blood of Jesus, preserve me from every distraction, compromise, offense, temptation, and every device of the enemy designed to hinder the fulfillment of my divine assignment.","scripture":[{"ref":"2 Corinthians 2:11","verses":[{"n":"11","text":"“Lest Satan should get an advantage of us: for we are not ignorant of his devices.”"}]}],"o":"s-6-1-3","o2":"s-6-1-3"},{"text":"Lord, let the Blood of Jesus give me a faithful, obedient, teachable, humble, and willing heart to fulfill every responsibility You have committed into my hands.","scripture":[{"ref":"Luke 16:10","verses":[{"n":"10","text":"“He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much.”"}]}],"o":"s-6-1-4","o2":"s-6-1-4"},{"text":"Father, by the Blood of Jesus, destroy every satanic opposition, resistance, delay, conspiracy, and spiritual warfare standing against the success of my assignment.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-6-1-5","o2":"s-6-1-5"},{"text":"Lord Jesus, let Your Blood open every door that is necessary for the successful fulfillment of my assignment, and close every door that is not according to Your will.","scripture":[{"ref":"Revelation 3:8","verses":[{"n":"8","text":"“I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"o":"s-6-1-6","o2":"s-6-1-6"},{"text":"Father, by the Blood of Jesus, fill me continually with the Holy Ghost, divine wisdom, understanding, knowledge, discernment, and spiritual power for every assignment You have given me.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"o":"s-6-1-7","o2":"s-6-1-7"},{"text":"Lord, let the Blood of Jesus preserve my spiritual life so that I may minister from a heart of holiness, prayer, and intimate fellowship with You.","scripture":[{"ref":"John 15:5","verses":[{"n":"5","text":"“I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing.”"}]}],"o":"s-6-1-8","o2":"s-6-1-8"},{"text":"Father, by the Blood of Jesus, grant me favor with our Father in the Lord, pastors, ministers, leaders, workers, and every person with whom I serve, so that together we may labor in unity for Your glory.","scripture":[{"ref":"Psalm 133:1","verses":[{"n":"1","text":"“Behold, how good and how pleasant it is for brethren to dwell together in unity!”"}]}],"o":"s-6-1-9","o2":"s-6-1-9"},{"text":"Lord Jesus, let the Blood of Jesus preserve my integrity, character, reputation, and testimony. Keep me blameless before You and before men.","scripture":[{"ref":"Proverbs 22:1","verses":[{"n":"1","text":"“A GOOD name is rather to be chosen than great riches, and loving favour rather than silver and gold.”"}]}],"o":"s-6-1-10","o2":"s-6-1-10"},{"text":"Father, by the Blood of Jesus, establish the work of my hands. Let every labor I offer in GRA Central produce lasting fruit for Your Kingdom.","scripture":[{"ref":"Psalm 90:17","verses":[{"n":"17","text":"“And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.”"}]}],"o":"s-6-1-11","o2":"s-6-1-11"},{"text":"Lord, by the Blood of Jesus, deliver me from weariness, discouragement, burnout, fear, and every spirit that seeks to weaken my commitment to Your work.","scripture":[{"ref":"Galatians 6:9","verses":[{"n":"9","text":"“And let us not be weary in well doing: for in due season we shall reap, if we faint not.”"}]}],"o":"s-6-1-12","o2":"s-6-1-12"},{"text":"Father, let the Blood of Jesus raise faithful helpers, co-laborers, and Kingdom partners who will strengthen every assignment You have entrusted to me.","scripture":[{"ref":"Ecclesiastes 4:9","verses":[{"n":"9","text":"“Two are better than one; because they have a good reward for their labour.”"}]}],"o":"s-6-1-13","o2":"s-6-1-13"},{"text":"Lord Jesus, by Your Blood, let every gift, talent, grace, and anointing You have placed within me grow continually for the edification of Your Church.","scripture":[{"ref":"1 Peter 4:10","verses":[{"n":"10","text":"“As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God.”"}]}],"o":"s-6-1-14","o2":"s-6-1-14"},{"text":"Father, let the Blood of Jesus protect every ministry project, outreach, conference, discipleship effort, mission activity, and service entrusted to my care in God’s Remnant Assembly from every attack of the enemy.","scripture":[{"ref":"Psalm 121:7–8","verses":[{"n":"7","text":"“The LORD shall preserve thee from all evil: he shall preserve thy soul."},{"n":"8","text":"The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.”"}]}],"o":"s-6-1-15","o2":"s-6-1-15"},{"text":"Lord, by the Blood of Jesus, help me to serve with excellence, diligence, faithfulness, humility, and wholehearted devotion, always seeking Your approval above the praise of men.","scripture":[{"ref":"Colossians 3:23","verses":[{"n":"23","text":"“And whatsoever ye do, do it heartily, as to the Lord, and not unto men;”"}]}],"o":"s-6-1-16","o2":"s-6-1-16"},{"text":"Father, by the Blood of Jesus, let every soul reached, every life transformed, every disciple established, and every Kingdom assignment accomplished through my service bring glory to Your holy name.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-6-1-17","o2":"s-6-1-17"},{"text":"Lord Jesus, let the Blood of Jesus preserve me until I complete every assignment You have ordained for my life. Let me never abandon, neglect, or fail the work You have committed to me.","scripture":[{"ref":"Acts 20:24","verses":[{"n":"24","text":"“But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.”"}]}],"o":"s-6-1-18","o2":"s-6-1-18"},{"text":"Father, by the Blood of Jesus, grant that when my earthly ministry in God’s Remnant Assembly is finished, I may stand before You having faithfully completed the work You entrusted to me.","scripture":[{"ref":"2 Timothy 4:7","verses":[{"n":"7","text":"“I have fought a good fight, I have finished my course, I have kept the faith:”"}]}],"o":"s-6-1-19","o2":"s-6-1-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus every divine assignment You have entrusted to me in GRA Central is covered, sanctified, protected, empowered, established, fruitful, and brought to completion according to Your perfect will. May all my labor be done for the honor of Jesus Christ and for the advancement of Your Kingdom until He comes.","scripture":[{"ref":"Philippians 1:6","verses":[{"n":"6","text":"“Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:”"}]}],"o":"s-6-1-20","o2":"s-6-1-20"}]},{"orig":35,"title":"Pleading the Blood of Jesus Over Our Glorious Future","foundation":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Jeremiah 29:11","verses":[{"n":"11","text":"“For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.”"}]},{"ref":"Romans 8:28","verses":[{"n":"28","text":"“And we know that all things work together for good to them that love God, to them who are the called according to his purpose.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my future, my destiny, and every day You have ordained for me. Let the Blood of the everlasting covenant preserve me until I fulfill Your perfect purpose.","scripture":[],"o":"s-6-2-1","o2":"s-6-2-1"},{"text":"Lord Jesus, let Your Blood speak better things over my future than every evil prophecy, curse, limitation, failure, disappointment, delay, or satanic prediction.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-6-2-2","o2":"s-6-2-2"},{"text":"Father, by the Blood of Jesus, establish Your perfect will concerning my life. Let every divine purpose You ordained before the foundation of the world be fulfilled in me.","scripture":[{"ref":"Jeremiah 29:11","verses":[{"n":"11","text":"“For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.”"}]}],"o":"s-6-2-3","o2":"s-6-2-3"},{"text":"Lord, by the Blood of Jesus, destroy every satanic agenda, evil covenant, generational limitation, and assignment of darkness against my glorious future.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-6-2-4","o2":"s-6-2-4"},{"text":"Father, let the Blood of Jesus guide every decision I make. Lead me only into the paths You have prepared for my life.","scripture":[{"ref":"Proverbs 3:5–6","verses":[{"n":"5","text":"“Trust in the LORD with all thine heart; and lean not unto thine own understanding."},{"n":"6","text":"In all thy ways acknowledge him, and he shall direct thy paths.”"}]}],"o":"s-6-2-5","o2":"s-6-2-5"},{"text":"Lord Jesus, by Your Blood, open every door of divine opportunity, favor, promotion, influence, ministry in God’s Remnant Assembly, education, business, and service that is according to Your will.","scripture":[{"ref":"Revelation 3:8","verses":[{"n":"8","text":"“I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"o":"s-6-2-6","o2":"s-6-2-6"},{"text":"Father, by the Blood of Jesus, close every wrong door, harmful relationship, deceptive opportunity, and dangerous path that would lead me away from Your purpose.","scripture":[{"ref":"Psalm 32:8","verses":[{"n":"8","text":"“I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.”"}]}],"o":"s-6-2-7","o2":"s-6-2-7"},{"text":"Lord, let the Blood of Jesus preserve my calling in God’s Remnant Assembly, my gifts, my talents, and my divine assignments until they are fully accomplished for Your glory.","scripture":[{"ref":"Romans 11:29","verses":[{"n":"29","text":"“For the gifts and calling of God are without repentance.”"}]}],"o":"s-6-2-8","o2":"s-6-2-8"},{"text":"Father, by the Blood of Jesus, let my future be brighter than my past. Let every season of my life reveal increasing grace, wisdom, fruitfulness, and usefulness in Your Kingdom.","scripture":[{"ref":"Proverbs 4:18","verses":[{"n":"18","text":"“But the path of the just is as the shining light, that shineth more and more unto the perfect day.”"}]}],"o":"s-6-2-9","o2":"s-6-2-9"},{"text":"Lord Jesus, by Your Blood, surround me with godly counselors, faithful friends, wise mentors, Kingdom partners, and spiritual leaders who will strengthen me in Your purpose.","scripture":[{"ref":"Ecclesiastes 4:9","verses":[{"n":"9","text":"“Two are better than one; because they have a good reward for their labour.”"}]}],"o":"s-6-2-10","o2":"s-6-2-10"},{"text":"Father, let the Blood of Jesus preserve me from every temptation, deception, distraction, compromise, and sin that could hinder my destiny.","scripture":[{"ref":"1 Corinthians 10:13","verses":[{"n":"13","text":"“There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.”"}]}],"o":"s-6-2-11","o2":"s-6-2-11"},{"text":"Lord, by the Blood of Jesus, grant me wisdom to redeem every opportunity You place before me and to walk faithfully in every season of life.","scripture":[{"ref":"Ephesians 5:15–16","verses":[{"n":"15","text":"“See then that ye walk circumspectly, not as fools, but as wise,"},{"n":"16","text":"Redeeming the time, because the days are evil.”"}]}],"o":"s-6-2-12","o2":"s-6-2-12"},{"text":"Father, by the Blood of Jesus, let every delay be turned into divine preparation, every trial into spiritual growth, and every difficulty into a testimony of Your faithfulness.","scripture":[{"ref":"Romans 8:28","verses":[{"n":"28","text":"“And we know that all things work together for good to them that love God, to them who are the called according to his purpose.”"}]}],"o":"s-6-2-13","o2":"s-6-2-13"},{"text":"Lord Jesus, by Your Blood, establish my future generations in Your covenant. Let my children and those who come after me serve You faithfully.","scripture":[{"ref":"Isaiah 59:21","verses":[{"n":"21","text":"“As for me, this is my covenant with them, saith the LORD; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seed’s seed, saith the LORD, from henceforth and for ever.”"}]}],"o":"s-6-2-14","o2":"s-6-2-14"},{"text":"Father, by the Blood of Jesus, preserve me in good health, strength, wisdom, holiness, and faithfulness so that I may complete every assignment You have entrusted to me.","scripture":[{"ref":"Acts 20:24","verses":[{"n":"24","text":"“But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.”"}]}],"o":"s-6-2-15","o2":"s-6-2-15"},{"text":"Lord, by the Blood of Jesus, let my latter days be more fruitful than my former days. Let Your glory continually increase in my life.","scripture":[{"ref":"Job 42:12","verses":[{"n":"12","text":"“So the LORD blessed the latter end of Job more than his beginning: for he had fourteen thousand sheep, and six thousand camels, and a thousand yoke of oxen, and a thousand she asses.”"}]}],"o":"s-6-2-16","o2":"s-6-2-16"},{"text":"Father, by the Blood of Jesus, let my life become a testimony of Your grace, mercy, power, and faithfulness to future generations.","scripture":[{"ref":"Psalm 71:18","verses":[{"n":"18","text":"“Now also when I am old and grayheaded, O God, forsake me not; until I have shewed thy strength unto this generation, and thy power to every one that is to come.”"}]}],"o":"s-6-2-17","o2":"s-6-2-17"},{"text":"Lord Jesus, let the Blood of Jesus keep me steadfast in the faith until the end. Let me never turn back, never fall away, and never lose the inheritance You have prepared for me.","scripture":[{"ref":"2 Timothy 4:7–8","verses":[{"n":"7","text":"“I have fought a good fight, I have finished my course, I have kept the faith:"},{"n":"8","text":"Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing.”"}]}],"o":"s-6-2-18","o2":"s-6-2-18"},{"text":"Father, by the Blood of Jesus, prepare me not only for a fruitful earthly future but also for the glorious inheritance reserved for all who belong to Christ. Let my name remain written in the Book of Life, and grant me grace to finish faithfully until I behold Your face.","scripture":[{"ref":"1 Peter 1:3–4","verses":[{"n":"3","text":"“Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,"},{"n":"4","text":"To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you,”"}]},{"ref":"Revelation 21:7","verses":[{"n":"7","text":"“He that overcometh shall inherit all things; and I will be his God, and he shall be my son.”"}]}],"o":"s-6-2-19","o2":"s-6-2-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus my future is secure in Your hands. I declare that my latter end shall be blessed, my course shall be finished with joy, my testimony shall glorify Christ, and I shall inherit every promise You have ordained for me both in this life and in the life to come.","scripture":[{"ref":"Philippians 1:6","verses":[{"n":"6","text":"“Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:”"}]}],"o":"s-6-2-20","o2":"s-6-2-20"}]},{"orig":36,"title":"Prayer for Fruitfulness in Every Good Work","foundation":[{"ref":"Colossians 1:10","verses":[{"n":"10","text":"“That ye might walk worthy of the Lord unto all pleasing, being fruitful in every good work, and increasing in the knowledge of God;”"}]}],"prayers":[{"text":"Father, make my life fruitful in every good work You have prepared for me.","scripture":[],"o":"s-6-3-1","o2":"s-6-3-1"},{"text":"Lord Jesus, let every effort I make for Your Kingdom produce lasting fruit.","scripture":[],"o":"s-6-3-2","o2":"s-6-3-2"},{"text":"Father, help me to remain faithful even when results are not immediately visible.","scripture":[],"o":"s-6-3-3","o2":"s-6-3-3"},{"text":"Lord, establish the work of my hands according to Your purpose.","scripture":[],"o":"s-6-3-4","o2":"s-6-3-4"},{"text":"Father, let my words, actions, and character point others to Christ.","scripture":[],"o":"s-6-3-5","o2":"s-6-3-5"},{"text":"Lord Jesus, help me to labor with diligence, excellence, and humility.","scripture":[],"o":"s-6-3-6","o2":"s-6-3-6"},{"text":"Father, let every gift You have given me be used for the edification of Your Church.","scripture":[],"o":"s-6-3-7","o2":"s-6-3-7"},{"text":"Lord, grant me perseverance to continue serving faithfully until the end.","scripture":[],"o":"s-6-3-8","o2":"s-6-3-8"},{"text":"Father, let my fruit remain for generations to come.","scripture":[],"o":"s-6-3-9","o2":"s-6-3-9"},{"text":"Thank You, Lord, because apart from You I can do nothing, but through You my labor is never in vain.","scripture":[],"o":"s-6-3-10","o2":"s-6-3-10"}]},{"orig":37,"title":"Prayer for Greater Kingdom Impact","foundation":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"prayers":[{"text":"Father, let my life become a bright light that continually points people to Jesus Christ.","scripture":[],"o":"s-6-4-1","o2":"s-6-4-1"},{"text":"Lord Jesus, use every gift, ability, opportunity, and relationship You have entrusted to me for the advancement of Your Kingdom.","scripture":[],"o":"s-6-4-2","o2":"s-6-4-2"},{"text":"Father, make me an effective witness wherever You send me.","scripture":[],"o":"s-6-4-3","o2":"s-6-4-3"},{"text":"Lord, help me to influence my generation through truth, holiness, compassion, and faithful service.","scripture":[],"o":"s-6-4-4","o2":"s-6-4-4"},{"text":"Father, let every message I preach, every conversation I have, and every act of kindness glorify Christ.","scripture":[],"o":"s-6-4-5","o2":"s-6-4-5"},{"text":"Lord Jesus, enlarge my opportunities to serve Your Church and strengthen Your people.","scripture":[],"o":"s-6-4-6","o2":"s-6-4-6"},{"text":"Father, make me a faithful steward of every opportunity You place before me.","scripture":[],"o":"s-6-4-7","o2":"s-6-4-7"},{"text":"Lord, let my influence always lead people toward repentance, faith, and obedience to Christ.","scripture":[],"o":"s-6-4-8","o2":"s-6-4-8"},{"text":"Father, let my life leave an eternal impact that will continue bearing fruit long after I am gone.","scripture":[],"o":"s-6-4-9","o2":"s-6-4-9"},{"text":"Thank You, Lord, because all glory belongs to You alone, both now and forever.","scripture":[],"o":"s-6-4-10","o2":"s-6-4-10"}]},{"orig":38,"title":"Prayer to Finish My Course with Joy","foundation":[{"ref":"Acts 20:24","verses":[{"n":"24","text":"“But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.”"}]},{"ref":"2 Timothy 4:7","verses":[{"n":"7","text":"“I have fought a good fight, I have finished my course, I have kept the faith:”"}]}],"prayers":[{"text":"Father, grant me grace to finish every assignment You have given me.","scripture":[],"o":"s-6-5-1","o2":"s-6-5-1"},{"text":"Lord Jesus, keep me faithful until the end of my earthly journey.","scripture":[],"o":"s-6-5-2","o2":"s-6-5-2"},{"text":"Father, preserve me from anything that would cause me to abandon Your calling.","scripture":[],"o":"s-6-5-3","o2":"s-6-5-3"},{"text":"Lord, strengthen me through every trial and every season of testing.","scripture":[],"o":"s-6-5-4","o2":"s-6-5-4"},{"text":"Father, help me to run my race with endurance, humility, and joy.","scripture":[],"o":"s-6-5-5","o2":"s-6-5-5"},{"text":"Lord Jesus, let me never lose sight of the eternal reward that awaits those who are faithful.","scripture":[],"o":"s-6-5-6","o2":"s-6-5-6"},{"text":"Father, keep my heart devoted to Christ above every earthly ambition.","scripture":[],"o":"s-6-5-7","o2":"s-6-5-7"},{"text":"Lord, help me leave behind a legacy that honors Your holy name.","scripture":[],"o":"s-6-5-8","o2":"s-6-5-8"},{"text":"Father, let me hear those precious words, “Well done, thou good and faithful servant.”","scripture":[],"o":"s-6-5-9","o2":"s-6-5-9"},{"text":"Thank You, Lord, because You are able to keep me from falling and to present me faultless before Your glorious presence with exceeding joy.","scripture":[],"o":"s-6-5-10","o2":"s-6-5-10"}]}]},{"label":"Part ONE","title":"MY LIFE IN CHRIST","subtitle":"Prayers for my walk with God, His answers, His favor, and His keeping power","sections":[{"orig":1,"title":"Pleading the Blood of Jesus Over My Life","foundation":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"1 John 1:7","verses":[{"n":"7","text":"“But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.”"}]},{"ref":"1 Peter 1:18–19","verses":[{"n":"18","text":"“Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;"},{"n":"19","text":"But with the precious blood of Christ, as of a lamb without blemish and without spot:”"}]},{"ref":"Psalm 91:14–16","verses":[{"n":"14","text":"“Because he hath set his love upon me, therefore will I deliver him: I will set him on high, because he hath known my name."},{"n":"15","text":"He shall call upon me, and I will answer him: I will be with him in trouble; I will deliver him, and honour him."},{"n":"16","text":"With long life will I satisfy him, and shew him my salvation.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my entire life. Let the Blood of the everlasting covenant cover my spirit, soul, body, mind, emotions, future, and every area of my existence.","scripture":[],"o":"s-2-1-1","o2":"s-2-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over my life than every accusation, condemnation, curse, evil word, failure, limitation, delay, or judgment.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-2-1-2","o2":"s-2-1-2"},{"text":"Father, by the Blood of Jesus, cleanse me from every known and unknown sin. Purify my heart, my thoughts, my motives, my words, and my actions so that I may walk in holiness before You.","scripture":[{"ref":"1 John 1:7","verses":[{"n":"7","text":"“But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.”"}]}],"o":"s-2-1-3","o2":"s-2-1-3"},{"text":"Lord, by the Blood of Jesus, cancel every curse, every evil covenant, every generational bondage, every legal claim of darkness, and every work of the enemy against my life.","scripture":[{"ref":"Galatians 3:13","verses":[{"n":"13","text":"“Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:”"}]}],"o":"s-2-1-4","o2":"s-2-1-4"},{"text":"Father, let the Blood of Jesus preserve my life from accidents, violence, sickness, disease, disasters, evil arrows, untimely death, and every hidden danger.","scripture":[{"ref":"Psalm 91:10","verses":[{"n":"10","text":"“There shall no evil befall thee, neither shall any plague come nigh thy dwelling.”"}]}],"o":"s-2-1-5","o2":"s-2-1-5"},{"text":"Lord Jesus, let the Blood of Jesus surround me with Your holy angels. Let them guard, defend, guide, and preserve me wherever I go.","scripture":[{"ref":"Psalm 91:11","verses":[{"n":"11","text":"“For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-2-1-6","o2":"s-2-1-6"},{"text":"Father, by the Blood of Jesus, let my mind be preserved in perfect peace. Remove fear, anxiety, depression, confusion, despair, and every spirit contrary to Your will.","scripture":[{"ref":"Isaiah 26:3","verses":[{"n":"3","text":"“Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.”"}]}],"o":"s-2-1-7","o2":"s-2-1-7"},{"text":"Lord, by the Blood of Jesus, strengthen my faith, deepen my love for You, increase my hunger for Your Word, and fill me continually with the Holy Ghost.","scripture":[{"ref":"Ephesians 5:18","verses":[{"n":"18","text":"“And be not drunk with wine, wherein is excess; but be filled with the Spirit;”"}]}],"o":"s-2-1-8","o2":"s-2-1-8"},{"text":"Father, let the Blood of Jesus preserve my calling and gifts in God’s Remnant Assembly, my purpose, and every divine assignment You have prepared for me.","scripture":[{"ref":"Romans 11:29","verses":[{"n":"29","text":"“For the gifts and calling of God are without repentance.”"}]}],"o":"s-2-1-9","o2":"s-2-1-9"},{"text":"Lord Jesus, by Your Blood, establish the work of my hands. Bless every honest labor, every assignment, every ministry, every relationship, and every responsibility You have entrusted to me at God’s Remnant Assembly.","scripture":[{"ref":"Psalm 90:17","verses":[{"n":"17","text":"“And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.”"}]}],"o":"s-2-1-10","o2":"s-2-1-10"},{"text":"Father, by the Blood of Jesus, let no weapon formed against me prosper. Frustrate every plan, conspiracy, enchantment, and strategy of the enemy concerning my life.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-2-1-11","o2":"s-2-1-11"},{"text":"Lord, by the Blood of Jesus, grant me wisdom, understanding, discernment, humility, patience, self-control, and the fear of the Lord in every decision I make.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"o":"s-2-1-12","o2":"s-2-1-12"},{"text":"Father, let the Blood of Jesus open every door You have ordained for me and close every door that would lead me away from Your perfect will.","scripture":[{"ref":"Revelation 3:8","verses":[{"n":"8","text":"“I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"o":"s-2-1-13","o2":"s-2-1-13"},{"text":"Lord Jesus, by the Blood of Jesus, let my life continually bear the fruit of the Holy Spirit and become a testimony of Your grace, mercy, power, and faithfulness.","scripture":[{"ref":"Galatians 5:22–23","verses":[{"n":"22","text":"“But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,"},{"n":"23","text":"Meekness, temperance: against such there is no law.”"}]}],"o":"s-2-1-14","o2":"s-2-1-14"},{"text":"Father, by the Blood of Jesus, preserve me from pride, deception, compromise, hypocrisy, backsliding, and every temptation that seeks to separate me from You.","scripture":[{"ref":"1 Corinthians 10:12","verses":[{"n":"12","text":"“Wherefore let him that thinketh he standeth take heed lest he fall.”"}]}],"o":"s-2-1-15","o2":"s-2-1-15"},{"text":"Lord, by the Blood of Jesus, make me a faithful witness for Christ. Let my words, my character, and my conduct draw many people into Your Kingdom.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-2-1-16","o2":"s-2-1-16"},{"text":"Father, by the Blood of Jesus, let me overcome every trial, every temptation, every persecution, every battle, and every challenge that comes against my life.","scripture":[{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"o":"s-2-1-17","o2":"s-2-1-17"},{"text":"Lord Jesus, by Your Blood, preserve me until I have completed every divine assignment You have entrusted to me. Let me finish my course with joy and faithfulness.","scripture":[{"ref":"Acts 20:24","verses":[{"n":"24","text":"“But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.”"}]}],"o":"s-2-1-18","o2":"s-2-1-18"},{"text":"Father, by the Blood of Jesus, prepare me daily for eternity. Keep my name written in the Lamb’s Book of Life, preserve my faith to the end, and grant that I may stand before You with confidence on the Day of Christ.","scripture":[{"ref":"Revelation 21:27","verses":[{"n":"27","text":"“And there shall in no wise enter into it any thing that defileth, neither whatsoever worketh abomination, or maketh a lie: but they which are written in the Lamb’s book of life.”"}]},{"ref":"2 Timothy 4:7–8","verses":[{"n":"7","text":"“I have fought a good fight, I have finished my course, I have kept the faith:"},{"n":"8","text":"Henceforth there is laid up for me a crown of righteousness, which the Lord, the righteous judge, shall give me at that day: and not to me only, but unto all them also that love his appearing.”"}]}],"o":"s-2-1-19","o2":"s-2-1-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus I am redeemed, justified, sanctified, forgiven, protected, preserved, strengthened, victorious, and secure in Christ. I declare that my life belongs entirely to You, that I shall fulfill every purpose for which You created me, and that I shall glorify You in life, in service, and throughout eternity.","scripture":[{"ref":"Romans 5:9","verses":[{"n":"9","text":"“Much more then, being now justified by his blood, we shall be saved from wrath through him.”"}]}],"o":"s-2-1-20","o2":"s-2-1-20"}]},{"orig":2,"title":"Prayer for God to Answer Me Speedily","foundation":[{"ref":"Psalm 102:2","verses":[{"n":"2","text":"“Hide not thy face from me in the day when I am in trouble; incline thine ear unto me: in the day when I call answer me speedily.”"}]}],"prayers":[{"text":"Father, according to Your Word, answer me speedily. Let every delayed answer to my prayers be released according to Your perfect will and for Your glory.","scripture":[],"o":"s-2-2-1","o2":"s-2-2-1"},{"text":"Lord Jesus, let every righteous prayer I have prayed concerning my spiritual life, family, ministry, and future receive a timely answer from heaven.","scripture":[],"o":"s-2-2-2","o2":"s-2-2-2"},{"text":"Father, let every barrier, hindrance, and delay opposing Your purposes for my life be removed, and let Your perfect timing prevail in every matter.","scripture":[],"o":"s-2-2-3","o2":"s-2-2-3"},{"text":"Lord, hear my cry and remember me with mercy. Let this season become a season of divine visitation and answered prayers.","scripture":[],"o":"s-2-2-4","o2":"s-2-2-4"},{"text":"Father, let my waiting strengthen my faith and deepen my trust in You, and let every answer You give accomplish Your perfect purpose.","scripture":[],"o":"s-2-2-5","o2":"s-2-2-5"},{"text":"Lord, let every promise You have spoken concerning my life begin to unfold according to Your appointed time.","scripture":[],"o":"s-2-2-6","o2":"s-2-2-6"},{"text":"Father, let Your favor surround me, and let doors that You desire to open be opened quickly for Your glory.","scripture":[],"o":"s-2-2-7","o2":"s-2-2-7"},{"text":"Lord Jesus, silence every voice of discouragement and fill my heart with confidence that You hear the prayers of Your children.","scripture":[],"o":"s-2-2-8","o2":"s-2-2-8"},{"text":"Father, let my testimony encourage many to trust in Your faithfulness and to wait upon You with hope.","scripture":[],"o":"s-2-2-9","o2":"s-2-2-9"},{"text":"Thank You, Father, because You are a God who hears prayer. I receive grace to wait faithfully, obey You completely, and rejoice in every answer You send.","scripture":[],"o":"s-2-2-10","o2":"s-2-2-10"}]},{"orig":3,"title":"Prayer for Spiritual Growth and a Deeper Walk with God","foundation":[{"ref":"James 4:8","verses":[{"n":"8","text":"“Draw nigh to God, and he will draw nigh to you. Cleanse your hands, ye sinners; and purify your hearts, ye double minded.”"}]}],"prayers":[{"text":"Father, draw me closer to You every day until Jesus Christ becomes the greatest desire of my heart.","scripture":[],"o":"s-2-3-1","o2":"s-2-3-1"},{"text":"Lord Jesus, increase my hunger for Your Word, for prayer, for worship, and for the fellowship of the Holy Spirit.","scripture":[],"o":"s-2-3-2","o2":"s-2-3-2"},{"text":"Father, let my spiritual life continually grow in holiness, faith, wisdom, love, and obedience.","scripture":[],"o":"s-2-3-3","o2":"s-2-3-3"},{"text":"Lord, deliver me from spiritual complacency, lukewarmness, distraction, and every habit that weakens my fellowship with You.","scripture":[],"o":"s-2-3-4","o2":"s-2-3-4"},{"text":"Father, fill me afresh with the Holy Ghost and empower me to live a life that glorifies Christ.","scripture":[],"o":"s-2-3-5","o2":"s-2-3-5"},{"text":"Lord Jesus, make me fruitful in every good work and increase my knowledge of Your will.","scripture":[],"o":"s-2-3-6","o2":"s-2-3-6"},{"text":"Father, let my life continually reflect the fruit of the Spirit in every relationship and responsibility.","scripture":[],"o":"s-2-3-7","o2":"s-2-3-7"},{"text":"Lord, help me to seek first Your Kingdom and Your righteousness above every earthly ambition.","scripture":[],"o":"s-2-3-8","o2":"s-2-3-8"},{"text":"Father, establish me as a faithful disciple who loves You wholeheartedly and serves You joyfully.","scripture":[],"o":"s-2-3-9","o2":"s-2-3-9"},{"text":"Thank You, Lord, because You, who began a good work in me, will perform it until the day of Jesus Christ.","scripture":[],"o":"s-2-3-10","o2":"s-2-3-10"}]},{"orig":4,"title":"Prayer for the Anointing of the Holy Spirit","foundation":[{"ref":"Isaiah 10:27","verses":[{"n":"27","text":"“And it shall come to pass in that day, that his burden shall be taken away from off thy shoulder, and his yoke from off thy neck, and the yoke shall be destroyed because of the anointing.”"}]},{"ref":"Luke 4:18","verses":[{"n":"18","text":"“The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised,”"}]}],"prayers":[{"text":"Father, fill me afresh with the Holy Spirit every day.","scripture":[],"o":"s-2-4-1","o2":"s-2-4-1"},{"text":"Lord Jesus, let Your anointing empower me to fulfill every assignment You have entrusted to me.","scripture":[],"o":"s-2-4-2","o2":"s-2-4-2"},{"text":"Father, let the Holy Spirit produce Christlike character within me.","scripture":[],"o":"s-2-4-3","o2":"s-2-4-3"},{"text":"Lord, grant me boldness to preach, teach, witness, and serve faithfully.","scripture":[],"o":"s-2-4-4","o2":"s-2-4-4"},{"text":"Father, let Your anointing destroy every yoke that hinders Your work in my life.","scripture":[],"o":"s-2-4-5","o2":"s-2-4-5"},{"text":"Lord Jesus, help me minister in humility and complete dependence upon You.","scripture":[],"o":"s-2-4-6","o2":"s-2-4-6"},{"text":"Father, let the gifts of the Holy Spirit operate according to Your will for the edification of the Church.","scripture":[],"o":"s-2-4-7","o2":"s-2-4-7"},{"text":"Lord, preserve me from grieving or quenching the Holy Spirit.","scripture":[],"o":"s-2-4-8","o2":"s-2-4-8"},{"text":"Father, let my life continually bear the fruit of the Holy Spirit.","scripture":[],"o":"s-2-4-9","o2":"s-2-4-9"},{"text":"Thank You, Lord, because Your Spirit is sufficient for every calling and every season.","scripture":[],"o":"s-2-4-10","o2":"s-2-4-10"}]},{"orig":5,"title":"Prayer for Divine Wisdom","foundation":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"prayers":[{"text":"Father, fill me daily with heavenly wisdom in every decision I make.","scripture":[],"o":"s-2-5-1","o2":"s-2-5-1"},{"text":"Lord Jesus, help me distinguish between truth and error, wisdom and foolishness.","scripture":[],"o":"s-2-5-2","o2":"s-2-5-2"},{"text":"Father, grant me understanding of Your Word and sensitivity to the leading of the Holy Spirit.","scripture":[],"o":"s-2-5-3","o2":"s-2-5-3"},{"text":"Lord, let wisdom guide my ministry, family, profession, finances, and relationships.","scripture":[],"o":"s-2-5-4","o2":"s-2-5-4"},{"text":"Father, preserve me from impulsive decisions and teach me to wait upon You.","scripture":[],"o":"s-2-5-5","o2":"s-2-5-5"},{"text":"Lord Jesus, let Your wisdom be evident in my speech, conduct, and leadership.","scripture":[],"o":"s-2-5-6","o2":"s-2-5-6"},{"text":"Father, help me to seek wise counsel from godly people.","scripture":[],"o":"s-2-5-7","o2":"s-2-5-7"},{"text":"Lord, grant me discernment to recognize opportunities that are according to Your will.","scripture":[],"o":"s-2-5-8","o2":"s-2-5-8"},{"text":"Father, make me wise in winning souls and serving Your Church.","scripture":[],"o":"s-2-5-9","o2":"s-2-5-9"},{"text":"Thank You, Lord, because every good and perfect gift, including wisdom, comes from You.","scripture":[],"o":"s-2-5-10","o2":"s-2-5-10"}]},{"orig":6,"title":"Prayer for Divine Favor","foundation":[{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]}],"prayers":[{"text":"Father, surround me with Your favor everywhere I go.","scripture":[],"o":"s-2-6-1","o2":"s-2-6-1"},{"text":"Lord Jesus, let Your favor open doors that no human effort can open.","scripture":[],"o":"s-2-6-2","o2":"s-2-6-2"},{"text":"Father, grant me favor before You and before men according to Your perfect will.","scripture":[],"o":"s-2-6-3","o2":"s-2-6-3"},{"text":"Lord, let favor accompany my applications, interviews, meetings, ministry, and daily responsibilities.","scripture":[],"o":"s-2-6-4","o2":"s-2-6-4"},{"text":"Father, let kings, leaders, employers, clients, and decision-makers look upon me with goodwill where it aligns with Your purpose.","scripture":[],"o":"s-2-6-5","o2":"s-2-6-5"},{"text":"Lord Jesus, let divine favor distinguish me for every good work You have prepared for me.","scripture":[],"o":"s-2-6-6","o2":"s-2-6-6"},{"text":"Father, let favor replace rejection, discouragement, and disappointment with opportunities that honor Christ.","scripture":[],"o":"s-2-6-7","o2":"s-2-6-7"},{"text":"Lord, let Your favor rest upon my household and all the work You have entrusted to me.","scripture":[],"o":"s-2-6-8","o2":"s-2-6-8"},{"text":"Father, let my life become a testimony of Your undeserved grace and lovingkindness.","scripture":[],"o":"s-2-6-9","o2":"s-2-6-9"},{"text":"Thank You, Lord, because Your favor is better than silver and gold and is sufficient for every season of my life.","scripture":[],"o":"s-2-6-10","o2":"s-2-6-10"}]},{"orig":7,"title":"Prayer for Divine Protection","foundation":[{"ref":"Psalm 121:7–8","verses":[{"n":"7","text":"“The LORD shall preserve thee from all evil: he shall preserve thy soul."},{"n":"8","text":"The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.”"}]}],"prayers":[{"text":"Father, preserve me from every evil according to Your sovereign care.","scripture":[],"o":"s-2-7-1","o2":"s-2-7-1"},{"text":"Lord Jesus, surround me with Your holy angels as You see fit.","scripture":[],"o":"s-2-7-2","o2":"s-2-7-2"},{"text":"Father, protect my family, ministry, and every responsibility You have entrusted to me.","scripture":[],"o":"s-2-7-3","o2":"s-2-7-3"},{"text":"Lord, preserve me from accidents, violence, deception, temptation, and unnecessary danger.","scripture":[],"o":"s-2-7-4","o2":"s-2-7-4"},{"text":"Father, guard my heart, mind, and spirit in Christ Jesus.","scripture":[],"o":"s-2-7-5","o2":"s-2-7-5"},{"text":"Lord Jesus, let no fear rule my life, but let me trust continually in You.","scripture":[],"o":"s-2-7-6","o2":"s-2-7-6"},{"text":"Father, keep me faithful in every circumstance.","scripture":[],"o":"s-2-7-7","o2":"s-2-7-7"},{"text":"Lord, preserve my testimony before believers and unbelievers alike.","scripture":[],"o":"s-2-7-8","o2":"s-2-7-8"},{"text":"Father, let Your peace remain with me wherever I go.","scripture":[],"o":"s-2-7-9","o2":"s-2-7-9"},{"text":"Thank You, Lord, because You neither slumber nor sleep in watching over Your children.","scripture":[],"o":"s-2-7-10","o2":"s-2-7-10"}]},{"orig":8,"title":"Prayer for Divine Remembrance","foundation":[{"ref":"Genesis 8:1","verses":[{"n":"1","text":"“And God remembered Noah, and every living thing, and all the cattle that was with him in the ark: and God made a wind to pass over the earth, and the waters asswaged;”"}]},{"ref":"Genesis 30:22","verses":[{"n":"22","text":"“And God remembered Rachel, and God hearkened to her, and opened her womb.”"}]},{"ref":"1 Samuel 1:19","verses":[{"n":"19","text":"“And they rose up in the morning early, and worshipped before the LORD, and returned, and came to their house to Ramah: and Elkanah knew Hannah his wife; and the LORD remembered her.”"}]},{"ref":"Luke 23:42–43","verses":[{"n":"42","text":"“And he said unto Jesus, Lord, remember me when thou comest into thy kingdom."},{"n":"43","text":"And Jesus said unto him, Verily I say unto thee, To day shalt thou be with me in paradise.”"}]}],"prayers":[{"text":"Father, remember me according to Your mercy and lovingkindness. Let this season become my season of divine remembrance.","scripture":[],"o":"s-2-8-1","o2":"s-2-8-1"},{"text":"Father, remember every prophecy You have spoken concerning my life and bring each one to fulfillment according to Your perfect will.","scripture":[],"o":"s-2-8-2","o2":"s-2-8-2"},{"text":"Father, remember my prayers, my tears, my labor, my sacrifices, my obedience, and my faithful service in Your Kingdom.","scripture":[],"o":"s-2-8-3","o2":"s-2-8-3"},{"text":"Lord Jesus, remember me for good as You remembered Noah, and cause every storm around my life to subside.","scripture":[],"o":"s-2-8-4","o2":"s-2-8-4"},{"text":"Father, remember me as You remembered Rachel. Open every door that has remained shut according to Your perfect purpose.","scripture":[],"o":"s-2-8-5","o2":"s-2-8-5"},{"text":"Lord, remember me as You remembered Hannah. Turn every long-standing burden into a testimony that glorifies Christ.","scripture":[],"o":"s-2-8-6","o2":"s-2-8-6"},{"text":"Father, remember every righteous desire You have placed within my heart concerning my spiritual growth, ministry, family, marriage, profession, business, and Kingdom assignments.","scripture":[],"o":"s-2-8-7","o2":"s-2-8-7"},{"text":"Lord Jesus, remember me in my waiting, and let my waiting produce hope, maturity, and unwavering faith.","scripture":[],"o":"s-2-8-8","o2":"s-2-8-8"},{"text":"Father, remember me for favor before You and before men. Let those You desire to help me remember me at the right time.","scripture":[],"o":"s-2-8-9","o2":"s-2-8-9"},{"text":"Lord, let divine remembrance remove every reproach and every season of discouragement from my life.","scripture":[],"o":"s-2-8-10","o2":"s-2-8-10"},{"text":"Father, remember my covenant with You, and establish me in every good work You have ordained for me.","scripture":[],"o":"s-2-8-11","o2":"s-2-8-11"},{"text":"Lord Jesus, remember every promise in Your Word that applies to my life, and perform it according to Your wisdom.","scripture":[],"o":"s-2-8-12","o2":"s-2-8-12"},{"text":"Father, let divine remembrance restore every opportunity that You desire me to receive.","scripture":[],"o":"s-2-8-13","o2":"s-2-8-13"},{"text":"Lord, remember me with divine visitation that leads to deeper holiness, greater usefulness, and increased fruitfulness.","scripture":[],"o":"s-2-8-14","o2":"s-2-8-14"},{"text":"Father, let my life become a testimony that You never forget those who trust in You.","scripture":[],"o":"s-2-8-15","o2":"s-2-8-15"},{"text":"Lord Jesus, remember my family, establish us in Your covenant, and preserve us for generations to come.","scripture":[],"o":"s-2-8-16","o2":"s-2-8-16"},{"text":"Father, remember GRA, remember Your Church, remember every faithful laborer, and let Your Kingdom continue to flourish.","scripture":[],"o":"s-2-8-17","o2":"s-2-8-17"},{"text":"Lord, remember my soul-winning efforts and cause many lives to be transformed for Your glory.","scripture":[],"o":"s-2-8-18","o2":"s-2-8-18"},{"text":"Father, remember every seed I have sown in faith and let it produce fruit that remains according to Your will.","scripture":[],"o":"s-2-8-19","o2":"s-2-8-19"},{"text":"Thank You, Heavenly Father, because You are the God who remembers His covenant forever. I rejoice that my times are in Your hands, and that every good purpose You have ordained for my life will be fulfilled through Jesus Christ.","scripture":[],"o":"s-2-8-20","o2":"s-2-8-20"}]},{"orig":9,"title":"Prayer for Divine Acceleration According to God’s Will","foundation":[{"ref":"Amos 9:13","verses":[{"n":"13","text":"“Behold, the days come, saith the LORD, that the plowman shall overtake the reaper, and the treader of grapes him that soweth seed; and the mountains shall drop sweet wine, and all the hills shall melt.”"}]},{"ref":"Isaiah 60:22","verses":[{"n":"22","text":"“A little one shall become a thousand, and a small one a strong nation: I the LORD will hasten it in his time.”"}]}],"prayers":[{"text":"Father, hasten every good purpose You have ordained for my life according to Your perfect timing.","scripture":[],"o":"s-2-9-1","o2":"s-2-9-1"},{"text":"Lord Jesus, where I have waited according to Your will, let there now be joyful progress for Your glory.","scripture":[],"o":"s-2-9-2","o2":"s-2-9-2"},{"text":"Father, accelerate my spiritual maturity and conformity to the image of Christ.","scripture":[],"o":"s-2-9-3","o2":"s-2-9-3"},{"text":"Lord, accelerate my usefulness in Your Kingdom and increase my effectiveness in serving You.","scripture":[],"o":"s-2-9-4","o2":"s-2-9-4"},{"text":"Father, let every delay that has fulfilled Your purpose now give way to new opportunities according to Your will.","scripture":[],"o":"s-2-9-5","o2":"s-2-9-5"},{"text":"Lord Jesus, accelerate my growth in wisdom, knowledge, understanding, and discernment.","scripture":[],"o":"s-2-9-6","o2":"s-2-9-6"},{"text":"Father, let my ministry become increasingly fruitful in bringing people to Christ.","scripture":[],"o":"s-2-9-7","o2":"s-2-9-7"},{"text":"Lord, accelerate every Kingdom assignment You have entrusted to me.","scripture":[],"o":"s-2-9-8","o2":"s-2-9-8"},{"text":"Father, let my latter years become more fruitful than my former years.","scripture":[],"o":"s-2-9-9","o2":"s-2-9-9"},{"text":"Lord Jesus, let my profession, business, and education progress according to Your purpose.","scripture":[],"o":"s-2-9-10","o2":"s-2-9-10"},{"text":"Father, accelerate every project that will bring honor to the name of Christ.","scripture":[],"o":"s-2-9-11","o2":"s-2-9-11"},{"text":"Lord, let Your grace enable me to redeem the time and use every opportunity wisely.","scripture":[],"o":"s-2-9-12","o2":"s-2-9-12"},{"text":"Lord Jesus, increase my influence only as it serves the advancement of Your Kingdom.","scripture":[],"o":"s-2-9-13","o2":"s-2-9-13"},{"text":"Father, hasten every answer to prayer that is according to Your will and best for my life.","scripture":[],"o":"s-2-9-14","o2":"s-2-9-14"},{"text":"Lord, let my testimony encourage others to trust Your faithfulness.","scripture":[],"o":"s-2-9-15","o2":"s-2-9-15"},{"text":"Father, grant me strength to keep pace with every opportunity You provide.","scripture":[],"o":"s-2-9-16","o2":"s-2-9-16"},{"text":"Lord Jesus, let my life continually move forward in obedience and faith.","scripture":[],"o":"s-2-9-17","o2":"s-2-9-17"},{"text":"Father, let every acceleration You bring produce humility, gratitude, and greater dependence upon You.","scripture":[],"o":"s-2-9-18","o2":"s-2-9-18"},{"text":"Thank You, Lord, because You make everything beautiful in Your time, and You are faithful to complete every good work You begin.","scripture":[],"o":"s-2-9-19","o2":"s-2-9-19"}]},{"orig":10,"title":"Prayer for Divine Restoration","foundation":[{"ref":"Joel 2:25–26","verses":[{"n":"25","text":"“And I will restore to you the years that the locust hath eaten, the cankerworm, and the caterpiller, and the palmerworm, my great army which I sent among you."},{"n":"26","text":"And ye shall eat in plenty, and be satisfied, and praise the name of the LORD your God, that hath dealt wondrously with you: and my people shall never be ashamed.”"}]}],"prayers":[{"text":"Father, restore every year, every opportunity, every blessing, and every privilege that has been lost according to Your perfect will.","scripture":[],"o":"s-2-10-1","o2":"s-2-10-1"},{"text":"Lord Jesus, let every delay become a testimony of Your faithfulness and redeeming grace.","scripture":[],"o":"s-2-10-2","o2":"s-2-10-2"},{"text":"Father, restore my spiritual passion, my joy, my strength, my peace, and my confidence in You.","scripture":[],"o":"s-2-10-3","o2":"s-2-10-3"},{"text":"Lord, restore every relationship, every ministry opportunity, and every righteous desire that is according to Your purpose.","scripture":[],"o":"s-2-10-4","o2":"s-2-10-4"},{"text":"Father, let my latter end be greater than my beginning, bringing glory to Your holy name.","scripture":[],"o":"s-2-10-5","o2":"s-2-10-5"},{"text":"Lord Jesus, restore every gift and every area of service where I have become weak or discouraged.","scripture":[],"o":"s-2-10-6","o2":"s-2-10-6"},{"text":"Father, let Your restoring power be evident in my family, ministry, profession, business, and every work of my hands.","scripture":[],"o":"s-2-10-7","o2":"s-2-10-7"},{"text":"Lord, replace sorrow with joy, mourning with praise, and discouragement with renewed hope.","scripture":[],"o":"s-2-10-8","o2":"s-2-10-8"},{"text":"Father, let every restoration You bring become a testimony that points people to Jesus Christ.","scripture":[],"o":"s-2-10-9","o2":"s-2-10-9"},{"text":"Thank You, Lord, because You are the God who restores, renews, and makes all things beautiful in Your time.","scripture":[],"o":"s-2-10-10","o2":"s-2-10-10"}]},{"orig":11,"title":"Prayer for the Removal of Reproach and Shame","foundation":[{"ref":"Joel 2:26–27","verses":[{"n":"26","text":"“And ye shall eat in plenty, and be satisfied, and praise the name of the LORD your God, that hath dealt wondrously with you: and my people shall never be ashamed."},{"n":"27","text":"And ye shall know that I am in the midst of Israel, and that I am the LORD your God, and none else: and my people shall never be ashamed.”"}]}],"prayers":[{"text":"Father, remove every reproach that hinders the testimony of Christ in my life.","scripture":[],"o":"s-2-11-1","o2":"s-2-11-1"},{"text":"Lord Jesus, replace shame with the dignity that comes from belonging to You.","scripture":[],"o":"s-2-11-2","o2":"s-2-11-2"},{"text":"Father, heal every wound caused by disappointment, rejection, or failure.","scripture":[],"o":"s-2-11-3","o2":"s-2-11-3"},{"text":"Lord, restore every area of my life that has suffered loss according to Your perfect will.","scripture":[],"o":"s-2-11-4","o2":"s-2-11-4"},{"text":"Father, let my testimony glorify Your mercy rather than my own strength.","scripture":[],"o":"s-2-11-5","o2":"s-2-11-5"},{"text":"Lord Jesus, grant me courage to trust You even in seasons of waiting.","scripture":[],"o":"s-2-11-6","o2":"s-2-11-6"},{"text":"Father, let Your favor replace every season of discouragement.","scripture":[],"o":"s-2-11-7","o2":"s-2-11-7"},{"text":"Lord, establish my steps in righteousness and truth.","scripture":[],"o":"s-2-11-8","o2":"s-2-11-8"},{"text":"Father, let my life proclaim the greatness of Your redeeming grace.","scripture":[],"o":"s-2-11-9","o2":"s-2-11-9"},{"text":"Thank You, Lord, because those who trust in You will never ultimately be put to shame.","scripture":[],"o":"s-2-11-10","o2":"s-2-11-10"}]},{"orig":12,"title":"Prayer for Open Doors That No Man Can Shut","foundation":[{"ref":"Revelation 3:7–8","verses":[{"n":"7","text":"“And to the angel of the church in Philadelphia write; These things saith he that is holy, he that is true, he that hath the key of David, he that openeth, and no man shutteth; and shutteth, and no man openeth;"},{"n":"8","text":"I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"prayers":[{"text":"Father, open every door You have ordained for my life here in GRA, my family, my profession, my business, and my divine destiny.","scripture":[],"o":"s-2-12-1","o2":"s-2-12-1"},{"text":"Lord Jesus, let every door of GRA ministry, service, influence, and Kingdom impact that You desire for me be opened in Your perfect timing.","scripture":[],"o":"s-2-12-2","o2":"s-2-12-2"},{"text":"Father, close every door that would lead me away from Your will, no matter how attractive it may appear, especially any door opened through mammon.","scripture":[],"o":"s-2-12-3","o2":"s-2-12-3"},{"text":"Lord, grant me wisdom to recognize the doors You open and courage to walk through them by faith.","scripture":[],"o":"s-2-12-4","o2":"s-2-12-4"},{"text":"Father, let doors of favor, divine appointments, and godly relationships be opened before me.","scripture":[],"o":"s-2-12-5","o2":"s-2-12-5"},{"text":"Lord Jesus, let every barrier that opposes Your purpose for my life be removed according to Your will.","scripture":[],"o":"s-2-12-6","o2":"s-2-12-6"},{"text":"Father, open doors for soul winning through my life here in GRA, and let every soul won be established in the Gospel.","scripture":[],"o":"s-2-12-7","o2":"s-2-12-7"},{"text":"Lord, let no human opposition frustrate the plans You have ordained for me.","scripture":[],"o":"s-2-12-8","o2":"s-2-12-8"},{"text":"Father, let every open door result in greater glory to Jesus Christ and greater blessing to others.","scripture":[],"o":"s-2-12-9","o2":"s-2-12-9"},{"text":"Thank You, Lord, because You alone hold the keys and Your purposes cannot be overthrown.","scripture":[],"o":"s-2-12-10","o2":"s-2-12-10"}]}]},{"label":"Part THREE","title":"MY MARRIAGE, MY HOME, AND MY FAMILY","subtitle":"Prayers for my spouse, my marriage, my children, the youth, and my entire household","sections":[{"orig":16,"title":"Pleading the Blood of Jesus Over My Spouse","foundation":[{"ref":"Ephesians 5:25","verses":[{"n":"25","text":"“Husbands, love your wives, even as Christ also loved the church, and gave himself for it;”"}]},{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"1 Peter 1:18–19","verses":[{"n":"18","text":"“Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;"},{"n":"19","text":"But with the precious blood of Christ, as of a lamb without blemish and without spot:”"}]},{"ref":"Colossians 1:20","verses":[{"n":"20","text":"“And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.”"}]}],"prayers":[{"text":"Father, in the name of Jesus, I plead the precious Blood of Jesus over my spouse. Let the Blood of the everlasting covenant surround, preserve, and defend him/her from every evil, in Jesus’ name.","scripture":[],"o":"s-3-1-1","o2":"s-3-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over my spouse than every accusation, curse, condemnation, failure, or evil report, according to Hebrews 12:24.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-3-1-2","o2":"s-3-1-2"},{"text":"I declare that the Blood of Jesus covers my spouse’s spirit, soul, and body. Let every satanic attack, arrow, plague, and affliction be nullified by the Blood of the Lamb.","scripture":[],"o":"s-3-1-3","o2":"s-3-1-3"},{"text":"Father, let the Blood of Jesus preserve my spouse from accidents, premature death, violence, sickness, and every hidden danger, in Jesus’ name.","scripture":[],"o":"s-3-1-4","o2":"s-3-1-4"},{"text":"By the Blood of Jesus, I cancel every evil covenant, inherited curse, generational bondage, and satanic legal claim operating against my spouse.","scripture":[],"o":"s-3-1-5","o2":"s-3-1-5"},{"text":"Lord, let the Blood of Jesus sanctify my spouse completely. Purify every thought, motive, word, and action for Your glory.","scripture":[],"o":"s-3-1-6","o2":"s-3-1-6"},{"text":"I plead the Blood of Jesus over my spouse’s mind. Let every spirit of fear, anxiety, depression, confusion, discouragement, and oppression be driven away.","scripture":[],"o":"s-3-1-7","o2":"s-3-1-7"},{"text":"Father, let the Blood of Jesus speak healing into every organ, tissue, bone, nerve, cell, and system of my spouse’s body.","scripture":[],"o":"s-3-1-8","o2":"s-3-1-8"},{"text":"By the Blood of Jesus, I declare that no weapon formed against my spouse shall prosper, and every tongue that rises in judgment is condemned.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-3-1-9","o2":"s-3-1-9"},{"text":"Lord, surround my spouse with holy angels because of the Blood of Jesus. Let angelic protection accompany every journey, every decision, and every assignment.","scripture":[{"ref":"Psalm 91:11","verses":[{"n":"11","text":"“For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-3-1-10","o2":"s-3-1-10"},{"text":"Father, let the Blood of Jesus preserve my spouse’s walk with You. Let nothing separate him/her from Your love and truth.","scripture":[],"o":"s-3-1-11","o2":"s-3-1-11"},{"text":"I plead the Blood of Jesus over my spouse’s calling, gifts, purpose, and destiny in God’s Remnant Assembly. Let every assignment of darkness against God’s purpose be destroyed.","scripture":[],"o":"s-3-1-12","o2":"s-3-1-12"},{"text":"Lord, by the Blood of Jesus, establish peace within our marriage. Let every spirit of division, misunderstanding, bitterness, unforgiveness, and strife be removed.","scripture":[{"ref":"Colossians 1:20","verses":[{"n":"20","text":"“And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.”"}]}],"o":"s-3-1-13","o2":"s-3-1-13"},{"text":"Father, let the Blood of Jesus cover every conversation, decision, journey, meeting, business, ministry in God’s Remnant Assembly, and responsibility entrusted to my spouse.","scripture":[],"o":"s-3-1-14","o2":"s-3-1-14"},{"text":"By the Blood of Jesus, I declare divine favor upon my spouse before God and before men. Open doors that no man can shut.","scripture":[{"ref":"Revelation 3:8","verses":[{"n":"8","text":"“I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"o":"s-3-1-15","o2":"s-3-1-15"},{"text":"Lord, let the Blood of Jesus silence every voice of the enemy speaking against my spouse’s progress, health, family, ministry in God’s Remnant Assembly, reputation, and future.","scripture":[],"o":"s-3-1-16","o2":"s-3-1-16"},{"text":"Father, because of the Blood of Jesus, let my spouse overcome every temptation, every trial, every battle, and every spiritual attack.","scripture":[{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"o":"s-3-1-17","o2":"s-3-1-17"},{"text":"Lord Jesus, let Your precious Blood continually cleanse my spouse from every known and unknown sin, and keep him/her walking in righteousness before You.","scripture":[{"ref":"1 John 1:7","verses":[{"n":"7","text":"“But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.”"}]}],"o":"s-3-1-18","o2":"s-3-1-18"},{"text":"Father, I dedicate my spouse afresh to You under the covering of the Blood of Jesus. Let Your perfect will be fulfilled in every area of his/her life.","scripture":[{"ref":"Romans 12:1","verses":[{"n":"1","text":"“I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.”"}]}],"o":"s-3-1-19","o2":"s-3-1-19"},{"text":"Thank You, Father, because by the Blood of Jesus my spouse is redeemed, protected, justified, sanctified, preserved, victorious, and kept until the day of Jesus Christ. To You alone be all the glory forever.","scripture":[{"ref":"Philippians 1:6","verses":[{"n":"6","text":"“Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:”"}]}],"o":"s-3-1-20","o2":"s-3-1-20"}]},{"orig":17,"title":"Pleading the Blood of Jesus Over My Marriage","foundation":[{"ref":"Genesis 2:24","verses":[{"n":"24","text":"“Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh.”"}]},{"ref":"Ecclesiastes 4:12","verses":[{"n":"12","text":"“And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken.”"}]},{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Colossians 1:20","verses":[{"n":"20","text":"“And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my marriage. Let the Blood of the everlasting covenant cover, preserve, sanctify, and establish our union according to Your perfect will.","scripture":[],"o":"s-3-2-1","o2":"s-3-2-1"},{"text":"Lord Jesus, let Your Blood speak better things over our marriage than every voice of accusation, division, misunderstanding, disappointment, bitterness, or failure.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-3-2-2","o2":"s-3-2-2"},{"text":"Father, by the Blood of Jesus, let our marriage be built upon Christ, the Solid Rock. Let no storm, temptation, trial, or attack overthrow what You have joined together.","scripture":[{"ref":"Matthew 19:6","verses":[{"n":"6","text":"“Wherefore they are no more twain, but one flesh. What therefore God hath joined together, let not man put asunder.”"}]}],"o":"s-3-2-3","o2":"s-3-2-3"},{"text":"By the Blood of Jesus, I cancel every generational curse, ancestral pattern, evil covenant, and inherited bondage that seeks to affect our marriage.","scripture":[{"ref":"Galatians 3:13","verses":[{"n":"13","text":"“Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:”"}]}],"o":"s-3-2-4","o2":"s-3-2-4"},{"text":"Father, let the Blood of Jesus destroy every spirit of divorce, separation, adultery, immorality, abuse, violence, and unfaithfulness operating against our marriage.","scripture":[{"ref":"Malachi 2:16","verses":[{"n":"16","text":"“For the LORD, the God of Israel, saith that he hateth putting away: for one covereth violence with his garment, saith the LORD of hosts: therefore take heed to your spirit, that ye deal not treacherously.”"}]}],"o":"s-3-2-5","o2":"s-3-2-5"},{"text":"Lord, let the Blood of Jesus fill our marriage with unconditional love, forgiveness, compassion, patience, humility, and mutual honor.","scripture":[{"ref":"Ephesians 5:25","verses":[{"n":"25","text":"“Husbands, love your wives, even as Christ also loved the church, and gave himself for it;”"}]}],"o":"s-3-2-6","o2":"s-3-2-6"},{"text":"Father, by the Blood of Jesus, remove every root of anger, pride, resentment, unforgiveness, jealousy, suspicion, and strife from our hearts.","scripture":[{"ref":"Ephesians 4:31–32","verses":[{"n":"31","text":"“Let all bitterness, and wrath, and anger, and clamour, and evil speaking, be put away from you, with all malice:"},{"n":"32","text":"And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you.”"}]}],"o":"s-3-2-7","o2":"s-3-2-7"},{"text":"Lord Jesus, let Your Blood sanctify our thoughts, words, attitudes, conversations, and decisions so that our marriage will continually glorify You.","scripture":[{"ref":"Psalm 19:14","verses":[{"n":"14","text":"“Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer.”"}]}],"o":"s-3-2-8","o2":"s-3-2-8"},{"text":"Father, by the Blood of Jesus, surround our marriage with a wall of divine protection. Let no weapon formed against us prosper.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-3-2-9","o2":"s-3-2-9"},{"text":"Lord, let the Blood of Jesus preserve our physical, emotional, mental, and spiritual health. Strengthen us to fulfill Your purpose together.","scripture":[{"ref":"Ecclesiastes 4:9","verses":[{"n":"9","text":"“Two are better than one; because they have a good reward for their labour.”"}]}],"o":"s-3-2-10","o2":"s-3-2-10"},{"text":"Father, let the Blood of Jesus bring divine peace into our home. Let every storm be calmed, every conflict resolved, and every wound healed.","scripture":[{"ref":"Colossians 3:15","verses":[{"n":"15","text":"“And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.”"}]}],"o":"s-3-2-11","o2":"s-3-2-11"},{"text":"Lord, let the Blood of Jesus preserve our finances, careers, businesses, ministries, and every work of our hands. Let there be no lack in our household.","scripture":[{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]}],"o":"s-3-2-12","o2":"s-3-2-12"},{"text":"Father, by the Blood of Jesus, bless us with wisdom to raise godly children who will love You and serve You faithfully.","scripture":[{"ref":"Isaiah 54:13","verses":[{"n":"13","text":"“And all thy children shall be taught of the LORD; and great shall be the peace of thy children.”"}]}],"o":"s-3-2-13","o2":"s-3-2-13"},{"text":"Lord Jesus, let the Blood of Jesus restore everything that has been broken, damaged, delayed, or stolen in our marriage.","scripture":[{"ref":"Joel 2:25","verses":[{"n":"25","text":"“And I will restore to you the years that the locust hath eaten, the cankerworm, and the caterpiller, and the palmerworm, my great army which I sent among you.”"}]}],"o":"s-3-2-14","o2":"s-3-2-14"},{"text":"Father, let the Blood of Jesus make our marriage a testimony of Your grace, mercy, faithfulness, and covenant love before the world.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-3-2-15","o2":"s-3-2-15"},{"text":"Lord, by the Blood of Jesus, keep us faithful to one another until the end of our lives. Let our covenant remain strong, pure, and enduring.","scripture":[{"ref":"Genesis 2:24","verses":[{"n":"24","text":"“Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh.”"}]}],"o":"s-3-2-16","o2":"s-3-2-16"},{"text":"Father, let the Blood of Jesus fill our home with continual prayer, worship, thanksgiving, joy, and the abiding presence of the Holy Spirit.","scripture":[{"ref":"Joshua 24:15","verses":[{"n":"15","text":"“And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.”"}]}],"o":"s-3-2-17","o2":"s-3-2-17"},{"text":"Lord Jesus, by Your precious Blood, let our marriage reflect the relationship between Christ and His Church. Teach us to love, serve, sacrifice, forgive, and honor one another.","scripture":[{"ref":"Ephesians 5:31–32","verses":[{"n":"31","text":"“For this cause shall a man leave his father and mother, and shall be joined unto his wife, and they two shall be one flesh."},{"n":"32","text":"This is a great mystery: but I speak concerning Christ and the church.”"}]}],"o":"s-3-2-18","o2":"s-3-2-18"},{"text":"Father, by the Blood of Jesus, grant us long life together, fruitful service in Your Kingdom, and grace to finish our marriage with joy, faithfulness, and honor.","scripture":[{"ref":"Psalm 91:16","verses":[{"n":"16","text":"“With long life will I satisfy him, and shew him my salvation.”"}]}],"o":"s-3-2-19","o2":"s-3-2-19"},{"text":"Thank You, Heavenly Father, because through the Blood of Jesus our marriage is redeemed, cleansed, sanctified, protected, strengthened, restored, fruitful, victorious, and firmly established upon the everlasting covenant of Christ. May our union continually bring glory to Your holy name until we stand together before You in eternity.","scripture":[{"ref":"Romans 5:9","verses":[{"n":"9","text":"“Much more then, being now justified by his blood, we shall be saved from wrath through him.”"}]}],"o":"s-3-2-20","o2":"s-3-2-20"}]},{"orig":18,"title":"Pleading the Blood of Jesus Over My Children","foundation":[{"ref":"Isaiah 54:13","verses":[{"n":"13","text":"“And all thy children shall be taught of the LORD; and great shall be the peace of thy children.”"}]},{"ref":"Psalm 127:3","verses":[{"n":"3","text":"“Lo, children are an heritage of the LORD: and the fruit of the womb is his reward.”"}]},{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"1 Peter 1:18–19","verses":[{"n":"18","text":"“Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;"},{"n":"19","text":"But with the precious blood of Christ, as of a lamb without blemish and without spot:”"}]}],"prayers":[{"text":"Father, in the name of Jesus, I plead the precious Blood of Jesus over every one of my children. Let the Blood of the everlasting covenant cover, preserve, and protect them all the days of their lives.","scripture":[],"o":"s-3-3-1","o2":"s-3-3-1"},{"text":"Lord Jesus, let Your Blood speak better things over my children than every evil word, curse, accusation, failure, limitation, or judgment, according to Hebrews 12:24.","scripture":[],"o":"s-3-3-2","o2":"s-3-3-2"},{"text":"By the Blood of Jesus, I dedicate every one of my children to You. Let them belong wholly to You, serve You faithfully, and fulfill Your divine purpose.","scripture":[{"ref":"1 Samuel 1:27–28","verses":[{"n":"27","text":"“For this child I prayed; and the LORD hath given me my petition which I asked of him:"},{"n":"28","text":"Therefore also I have lent him to the LORD; as long as he liveth he shall be lent to the LORD. And he worshipped the LORD there.”"}]}],"o":"s-3-3-3","o2":"s-3-3-3"},{"text":"Father, let the Blood of Jesus preserve my children from sickness, disease, accidents, violence, kidnapping, premature death, and every hidden danger.","scripture":[{"ref":"Psalm 91:10","verses":[{"n":"10","text":"“There shall no evil befall thee, neither shall any plague come nigh thy dwelling.”"}]}],"o":"s-3-3-4","o2":"s-3-3-4"},{"text":"I cancel, by the Blood of Jesus, every inherited curse, generational bondage, satanic covenant, evil dedication, and ancestral oppression concerning my children.","scripture":[{"ref":"Galatians 3:13","verses":[{"n":"13","text":"“Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:”"}]}],"o":"s-3-3-5","o2":"s-3-3-5"},{"text":"Lord, let the Blood of Jesus sanctify my children. Separate them from sin, worldliness, corruption, and every evil influence.","scripture":[{"ref":"John 17:17","verses":[{"n":"17","text":"“Sanctify them through thy truth: thy word is truth.”"}]}],"o":"s-3-3-6","o2":"s-3-3-6"},{"text":"Father, by the Blood of Jesus, keep my children from evil friendships, ungodly relationships, false teachers, deception, and destructive influences.","scripture":[{"ref":"Proverbs 13:20","verses":[{"n":"20","text":"“He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.”"}]}],"o":"s-3-3-7","o2":"s-3-3-7"},{"text":"Let the Blood of Jesus guard the minds of my children. Remove fear, anxiety, confusion, addiction, depression, rebellion, and every evil imagination.","scripture":[{"ref":"2 Timothy 1:7","verses":[{"n":"7","text":"“For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.”"}]}],"o":"s-3-3-8","o2":"s-3-3-8"},{"text":"Father, I plead the Blood of Jesus over the education, learning, wisdom, understanding, memory, and intellectual development of my children.","scripture":[{"ref":"Isaiah 54:13","verses":[{"n":"13","text":"“And all thy children shall be taught of the LORD; and great shall be the peace of thy children.”"}]}],"o":"s-3-3-9","o2":"s-3-3-9"},{"text":"Lord, surround my children with Your holy angels. Let them be protected wherever they go, whether at home, school, work, church, or during travel.","scripture":[{"ref":"Psalm 91:11","verses":[{"n":"11","text":"“For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-3-3-10","o2":"s-3-3-10"},{"text":"By the Blood of Jesus, I declare that no weapon formed against my children shall prosper. Every plan of the enemy against their future shall fail.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-3-3-11","o2":"s-3-3-11"},{"text":"Father, let the Blood of Jesus preserve the calling, gifts, talents, and divine destiny You have placed within every one of my children for Your service in God’s Remnant Assembly.","scripture":[{"ref":"Jeremiah 1:5","verses":[{"n":"5","text":"“Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations.”"}]}],"o":"s-3-3-12","o2":"s-3-3-12"},{"text":"Lord, by the Blood of Jesus, give my children hearts that love righteousness, holiness, humility, obedience, and the fear of the Lord.","scripture":[{"ref":"Proverbs 22:6","verses":[{"n":"6","text":"“Train up a child in the way he should go: and when he is old, he will not depart from it.”"}]}],"o":"s-3-3-13","o2":"s-3-3-13"},{"text":"Father, let the Blood of Jesus open doors of divine favor, scholarship, employment, promotion, business success, ministry opportunities in God’s Remnant Assembly, and godly relationships for my children.","scripture":[{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]}],"o":"s-3-3-14","o2":"s-3-3-14"},{"text":"Lord, let the Blood of Jesus preserve my children from every addiction, immorality, substance abuse, violence, occult involvement, and every work of darkness.","scripture":[{"ref":"1 Corinthians 6:19–20","verses":[{"n":"19","text":"“What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?"},{"n":"20","text":"For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God’s.”"}]}],"o":"s-3-3-15","o2":"s-3-3-15"},{"text":"Father, because of the Blood of Jesus, let my children overcome every temptation, every spiritual battle, every trial, and every attack of the enemy.","scripture":[{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"o":"s-3-3-16","o2":"s-3-3-16"},{"text":"Lord Jesus, let Your precious Blood continually cleanse my children from every known and unknown sin. Draw them daily into a deeper relationship with You.","scripture":[{"ref":"1 John 1:7","verses":[{"n":"7","text":"“But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.”"}]}],"o":"s-3-3-17","o2":"s-3-3-17"},{"text":"Father, let the Blood of Jesus establish peace, unity, love, and joy among my children and throughout our entire family.","scripture":[{"ref":"Colossians 1:20","verses":[{"n":"20","text":"“And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.”"}]}],"o":"s-3-3-18","o2":"s-3-3-18"},{"text":"Lord, I declare that every one of my children shall become mighty in the land, fruitful in every good work, faithful disciples of Christ, and shining lights in their generation.","scripture":[{"ref":"Psalm 112:2","verses":[{"n":"2","text":"“His seed shall be mighty upon earth: the generation of the upright shall be blessed.”"}]},{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-3-3-19","o2":"s-3-3-19"},{"text":"Thank You, Heavenly Father, because by the Blood of Jesus my children are redeemed, protected, sanctified, preserved, guided, favored, victorious, and established in Your everlasting covenant until the coming of our Lord Jesus Christ.","scripture":[{"ref":"Isaiah 59:21","verses":[{"n":"21","text":"“As for me, this is my covenant with them, saith the LORD; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seed’s seed, saith the LORD, from henceforth and for ever.”"}]}],"o":"s-3-3-20","o2":"s-3-3-20"},{"text":"Bless every child with salvation, protection, joy, and a lifelong love for Christ.","scripture":[{"ref":"Mark 10:14","verses":[{"n":"14","text":"“But when Jesus saw it, he was much displeased, and said unto them, Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God.”"}]}],"o":"s-3-7-1","o2":"s-3-3-21"},{"text":"Raise up a generation passionately devoted to Jesus Christ.","scripture":[{"ref":"Ecclesiastes 12:1","verses":[{"n":"1","text":"“Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;”"}]}],"o":"s-3-8-1","o2":"s-3-3-22"}]},{"orig":19,"title":"Pleading the Blood of Jesus Over My Family","foundation":[{"ref":"Joshua 24:15","verses":[{"n":"15","text":"“And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.”"}]},{"ref":"Acts 16:31","verses":[{"n":"31","text":"“And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.”"}]},{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"1 Peter 1:18–19","verses":[{"n":"18","text":"“Forasmuch as ye know that ye were not redeemed with corruptible things, as silver and gold, from your vain conversation received by tradition from your fathers;"},{"n":"19","text":"But with the precious blood of Christ, as of a lamb without blemish and without spot:”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my entire family. Let the Blood of the everlasting covenant surround, preserve, protect, and sanctify every member of my household.","scripture":[],"o":"s-3-4-1","o2":"s-3-4-1"},{"text":"Lord Jesus, let Your Blood speak better things over my family than every evil report, accusation, curse, failure, sorrow, affliction, or judgment, according to Hebrews 12:24.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-3-4-2","o2":"s-3-4-2"},{"text":"Father, I dedicate my entire family to You. Let every member of my household belong to Jesus Christ, walk in His truth, and faithfully serve Him all the days of their lives.","scripture":[{"ref":"Joshua 24:15","verses":[{"n":"15","text":"“And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.”"}]}],"o":"s-3-4-3","o2":"s-3-4-3"},{"text":"By the Blood of Jesus, I cancel every generational curse, ancestral covenant, inherited bondage, satanic dedication, and every legal claim of darkness against my family.","scripture":[{"ref":"Galatians 3:13","verses":[{"n":"13","text":"“Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:”"}]}],"o":"s-3-4-4","o2":"s-3-4-4"},{"text":"Father, let the Blood of Jesus preserve every member of my family from sickness, disease, accidents, violence, premature death, natural disasters, and every hidden danger.","scripture":[{"ref":"Psalm 91:10","verses":[{"n":"10","text":"“There shall no evil befall thee, neither shall any plague come nigh thy dwelling.”"}]}],"o":"s-3-4-5","o2":"s-3-4-5"},{"text":"Lord, let the Blood of Jesus cleanse every member of my family from sin, uncleanness, compromise, and every work of darkness. Draw us all into deeper holiness and obedience.","scripture":[{"ref":"1 John 1:7","verses":[{"n":"7","text":"“But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.”"}]}],"o":"s-3-4-6","o2":"s-3-4-6"},{"text":"Father, let the Blood of Jesus establish salvation in every generation of my family. Let none be lost, but let all come to the knowledge of the truth.","scripture":[{"ref":"Acts 16:31","verses":[{"n":"31","text":"“And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house.”"}]}],"o":"s-3-4-7","o2":"s-3-4-7"},{"text":"Lord, by the Blood of Jesus, remove every spirit of division, bitterness, unforgiveness, strife, jealousy, and misunderstanding from my family.","scripture":[{"ref":"Colossians 1:20","verses":[{"n":"20","text":"“And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.”"}]}],"o":"s-3-4-8","o2":"s-3-4-8"},{"text":"Father, let the Blood of Jesus unite our hearts in love, humility, forgiveness, peace, and mutual honor.","scripture":[{"ref":"Psalm 133:1","verses":[{"n":"1","text":"“Behold, how good and how pleasant it is for brethren to dwell together in unity!”"}]}],"o":"s-3-4-9","o2":"s-3-4-9"},{"text":"Lord, surround every member of my family with Your holy angels. Let them be divinely protected wherever they go.","scripture":[{"ref":"Psalm 91:11","verses":[{"n":"11","text":"“For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-3-4-10","o2":"s-3-4-10"},{"text":"By the Blood of Jesus, I declare that no weapon formed against my family shall prosper. Every evil plan, conspiracy, enchantment, and assignment against us shall fail.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-3-4-11","o2":"s-3-4-11"},{"text":"Father, let the Blood of Jesus preserve the health, strength, minds, emotions, finances, businesses, ministries, education, and divine destinies of every member of my family.","scripture":[{"ref":"Jeremiah 29:11","verses":[{"n":"11","text":"“For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.”"}]}],"o":"s-3-4-12","o2":"s-3-4-12"},{"text":"Lord, by the Blood of Jesus, break every cycle of failure, poverty, addiction, immorality, divorce, rebellion, barrenness, and untimely death operating in my family.","scripture":[{"ref":"2 Corinthians 5:17","verses":[{"n":"17","text":"“Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.”"}]}],"o":"s-3-4-13","o2":"s-3-4-13"},{"text":"Father, let the Blood of Jesus establish Your favor upon every member of my family. Open doors of divine opportunity, promotion, provision, and blessing that no man can shut.","scripture":[{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]}],"o":"s-3-4-14","o2":"s-3-4-14"},{"text":"Lord Jesus, let every member of my family become a witness for Christ. Fill us with the Holy Ghost and use us to win souls for Your Kingdom.","scripture":[{"ref":"Acts 1:8","verses":[{"n":"8","text":"“But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth.”"}]}],"o":"s-3-4-15","o2":"s-3-4-15"},{"text":"Father, let the Blood of Jesus preserve our home as a place of prayer, worship, holiness, joy, peace, hospitality, and the continual presence of God.","scripture":[{"ref":"Psalm 27:4","verses":[{"n":"4","text":"“One thing have I desired of the LORD, that will I seek after; that I may dwell in the house of the LORD all the days of my life, to behold the beauty of the LORD, and to enquire in his temple.”"}]}],"o":"s-3-4-16","o2":"s-3-4-16"},{"text":"Lord, by the Blood of Jesus, preserve every marriage, every child, every parent, every grandparent, and every generation connected to our family.","scripture":[{"ref":"Isaiah 59:21","verses":[{"n":"21","text":"“As for me, this is my covenant with them, saith the LORD; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seed’s seed, saith the LORD, from henceforth and for ever.”"}]}],"o":"s-3-4-17","o2":"s-3-4-17"},{"text":"Father, let the Blood of Jesus deliver my family from every snare of the devil, every evil altar, every occult influence, every deception, and every attack against our faith.","scripture":[{"ref":"Colossians 1:13–14","verses":[{"n":"13","text":"“Who hath delivered us from the power of darkness, and hath translated us into the kingdom of his dear Son:"},{"n":"14","text":"In whom we have redemption through his blood, even the forgiveness of sins:”"}]}],"o":"s-3-4-18","o2":"s-3-4-18"},{"text":"Lord, I declare that my family shall prosper spiritually, physically, financially, emotionally, and ministerially. Let every member fulfill the divine purpose for which You created them.","scripture":[{"ref":"3 John 2","verses":[{"n":"2","text":"“Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.”"}]}],"o":"s-3-4-19","o2":"s-3-4-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus my entire family is redeemed, justified, sanctified, reconciled, protected, preserved, favored, victorious, and established in Your everlasting covenant until the glorious appearing of our Lord Jesus Christ.","scripture":[{"ref":"Romans 5:9","verses":[{"n":"9","text":"“Much more then, being now justified by his blood, we shall be saved from wrath through him.”"}]}],"o":"s-3-4-20","o2":"s-3-4-20"}]},{"orig":20,"title":"Prayer for Timely Marriage According to God’s Will","foundation":[{"ref":"Psalm 68:6","verses":[{"n":"6","text":"“God setteth the solitary in families: he bringeth out those which are bound with chains: but the rebellious dwell in a dry land.”"}]}],"prayers":[{"text":"Father, according to Your perfect wisdom and timing, establish me in the marriage You have prepared for me.","scripture":[],"o":"s-3-5-1","o2":"s-3-5-1"},{"text":"Lord Jesus, lead me only to the spouse You have ordained, and keep me from relationships outside Your will.","scripture":[],"o":"s-3-5-2","o2":"s-3-5-2"},{"text":"Father, remove every obstacle that would hinder the fulfillment of Your purpose concerning my marriage.","scripture":[],"o":"s-3-5-3","o2":"s-3-5-3"},{"text":"Lord, prepare my heart to become a godly husband or wife who reflects the love of Christ.","scripture":[],"o":"s-3-5-4","o2":"s-3-5-4"},{"text":"Father, let my future marriage become a testimony of Your covenant faithfulness.","scripture":[],"o":"s-3-5-5","o2":"s-3-5-5"},{"text":"Lord Jesus, grant wisdom, patience, purity, and discernment while I wait upon You.","scripture":[],"o":"s-3-5-6","o2":"s-3-5-6"},{"text":"Father, unite me only with one who fears You and desires to glorify Christ.","scripture":[],"o":"s-3-5-7","o2":"s-3-5-7"},{"text":"Lord, let my future home become a place of prayer, worship, peace, and faithful service.","scripture":[],"o":"s-3-5-8","o2":"s-3-5-8"},{"text":"Father, let our union advance Your Kingdom and bless many generations.","scripture":[],"o":"s-3-5-9","o2":"s-3-5-9"},{"text":"Thank You, Lord, because every good and perfect gift comes from You, and I trust Your timing completely.","scripture":[],"o":"s-3-5-10","o2":"s-3-5-10"}]},{"orig":21,"title":"Prayer for My Family","foundation":[{"ref":"Joshua 24:15","verses":[{"n":"15","text":"“And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.”"}]}],"prayers":[{"text":"Father, let every member of my family know, love, and faithfully follow Jesus Christ.","scripture":[],"o":"s-3-6-1","o2":"s-3-6-1"},{"text":"Lord, preserve my family in unity, peace, holiness, and truth.","scripture":[],"o":"s-3-6-2","o2":"s-3-6-2"},{"text":"Father, protect every member of my household from evil according to Your will.","scripture":[],"o":"s-3-6-3","o2":"s-3-6-3"},{"text":"Lord Jesus, let Your grace restore every broken relationship within my family.","scripture":[],"o":"s-3-6-4","o2":"s-3-6-4"},{"text":"Father, grant wisdom, health, provision, and spiritual maturity to every member of my household.","scripture":[],"o":"s-3-6-5","o2":"s-3-6-5"},{"text":"Lord, let future generations of my family serve You faithfully.","scripture":[],"o":"s-3-6-6","o2":"s-3-6-6"},{"text":"Father, make our home a place where Christ is honored above all.","scripture":[],"o":"s-3-6-7","o2":"s-3-6-7"},{"text":"Lord Jesus, let forgiveness, compassion, and humility characterize our relationships.","scripture":[],"o":"s-3-6-8","o2":"s-3-6-8"},{"text":"Father, use our family as a light to our community and for the advancement of the Gospel.","scripture":[],"o":"s-3-6-9","o2":"s-3-6-9"},{"text":"Thank You, Lord, because Your covenant mercy extends from generation to generation upon those who fear You.","scripture":[],"o":"s-3-6-10","o2":"s-3-6-10"},{"text":"Save, restore, strengthen, and unite every family represented.","scripture":[{"ref":"Joshua 24:15","verses":[{"n":"15","text":"“And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.”"}]}],"o":"s-3-9-1","o2":"s-3-6-11"}]}]},{"label":"Part FOUR","title":"MY HEALTH AND MY STRENGTH","subtitle":"Prayers for healing, divine health, and long life","sections":[{"orig":25,"title":"Pleading the Blood of Jesus Over My Health","foundation":[{"ref":"Isaiah 53:4–5","verses":[{"n":"4","text":"“Surely he hath borne our griefs, and carried our sorrows: yet we did esteem him stricken, smitten of God, and afflicted."},{"n":"5","text":"But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.”"}]},{"ref":"1 Peter 2:24","verses":[{"n":"24","text":"“Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.”"}]},{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my entire body, spirit, soul, and mind. Let the Blood of the everlasting covenant preserve me in divine health and strength.","scripture":[],"o":"s-4-1-1","o2":"s-4-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over my health than every sickness, disease, diagnosis, infirmity, pain, weakness, or medical report.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-4-1-2","o2":"s-4-1-2"},{"text":"Father, by the Blood of Jesus, let every sickness and disease contrary to Your will be removed from my body. Let Your healing power flow through every part of my being.","scripture":[{"ref":"Isaiah 53:5","verses":[{"n":"5","text":"“But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.”"}]}],"o":"s-4-1-3","o2":"s-4-1-3"},{"text":"Lord, by the Blood of Jesus, cleanse every organ, tissue, cell, bone, nerve, muscle, blood vessel, and system in my body. Let everything function according to Your perfect design.","scripture":[{"ref":"Psalm 103:2–3","verses":[{"n":"2","text":"“Bless the LORD, O my soul, and forget not all his benefits:"},{"n":"3","text":"Who forgiveth all thine iniquities; who healeth all thy diseases;”"}]}],"o":"s-4-1-4","o2":"s-4-1-4"},{"text":"Father, by the Blood of Jesus, I cancel every inherited disease, genetic disorder, generational infirmity, and every curse affecting my health.","scripture":[{"ref":"Galatians 3:13","verses":[{"n":"13","text":"“Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:”"}]}],"o":"s-4-1-5","o2":"s-4-1-5"},{"text":"Lord Jesus, let the Blood of Jesus strengthen my immune system and preserve me from every virus, infection, plague, epidemic, and contagious disease.","scripture":[{"ref":"Psalm 91:10","verses":[{"n":"10","text":"“There shall no evil befall thee, neither shall any plague come nigh thy dwelling.”"}]}],"o":"s-4-1-6","o2":"s-4-1-6"},{"text":"Father, let the Blood of Jesus restore every damaged organ, failing system, weakened tissue, and every part of my body that requires healing according to Your will.","scripture":[{"ref":"Jeremiah 30:17","verses":[{"n":"17","text":"“For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after.”"}]}],"o":"s-4-1-7","o2":"s-4-1-7"},{"text":"Lord, by the Blood of Jesus, remove every spirit of fear, anxiety, depression, discouragement, stress, and emotional burden that affects my health.","scripture":[{"ref":"2 Timothy 1:7","verses":[{"n":"7","text":"“For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.”"}]}],"o":"s-4-1-8","o2":"s-4-1-8"},{"text":"Father, let the Blood of Jesus grant me restful sleep, renewed strength, and daily restoration.","scripture":[{"ref":"Psalm 127:2","verses":[{"n":"2","text":"“It is vain for you to rise up early, to sit up late, to eat the bread of sorrows: for so he giveth his beloved sleep.”"}]}],"o":"s-4-1-9","o2":"s-4-1-9"},{"text":"Lord Jesus, by Your precious Blood, preserve me from accidents, injuries, surgeries, complications, disabilities, and untimely death.","scripture":[{"ref":"Psalm 91:11","verses":[{"n":"11","text":"“For he shall give his angels charge over thee, to keep thee in all thy ways.”"}]}],"o":"s-4-1-10","o2":"s-4-1-10"},{"text":"Father, let the Blood of Jesus sanctify my body as the temple of the Holy Ghost. Help me to honor You in every aspect of my physical life.","scripture":[{"ref":"1 Corinthians 6:19–20","verses":[{"n":"19","text":"“What? know ye not that your body is the temple of the Holy Ghost which is in you, which ye have of God, and ye are not your own?"},{"n":"20","text":"For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God’s.”"}]}],"o":"s-4-1-11","o2":"s-4-1-11"},{"text":"Lord, by the Blood of Jesus, grant wisdom to every physician, nurse, therapist, caregiver, and healthcare professional involved in my care.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"o":"s-4-1-12","o2":"s-4-1-12"},{"text":"Father, let the Blood of Jesus preserve my mind. Grant me clarity, wisdom, sound judgment, emotional stability, and the peace of Christ.","scripture":[{"ref":"Isaiah 26:3","verses":[{"n":"3","text":"“Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.”"}]}],"o":"s-4-1-13","o2":"s-4-1-13"},{"text":"Lord Jesus, by Your Blood, let every hidden sickness be exposed in time and let every necessary treatment, care, and provision come according to Your wisdom and mercy.","scripture":[{"ref":"Psalm 32:8","verses":[{"n":"8","text":"“I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.”"}]}],"o":"s-4-1-14","o2":"s-4-1-14"},{"text":"Father, by the Blood of Jesus, let me walk daily in divine strength to fulfill the work You have prepared for me.","scripture":[{"ref":"Isaiah 40:31","verses":[{"n":"31","text":"“But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.”"}]}],"o":"s-4-1-15","o2":"s-4-1-15"},{"text":"Lord, by the Blood of Jesus, preserve me from harmful habits, addictions, gluttony, substance abuse, and every practice that destroys health.","scripture":[{"ref":"1 Corinthians 10:31","verses":[{"n":"31","text":"“Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.”"}]}],"o":"s-4-1-16","o2":"s-4-1-16"},{"text":"Father, let the Blood of Jesus grant me long life according to Your purpose, that I may serve You faithfully and glorify Your name.","scripture":[{"ref":"Psalm 91:16","verses":[{"n":"16","text":"“With long life will I satisfy him, and shew him my salvation.”"}]}],"o":"s-4-1-17","o2":"s-4-1-17"},{"text":"Lord Jesus, let Your Blood continually cleanse me from every sin and help me walk in holiness, knowing that my spiritual life and physical life both belong to You.","scripture":[{"ref":"1 John 1:7","verses":[{"n":"7","text":"“But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.”"}]}],"o":"s-4-1-18","o2":"s-4-1-18"},{"text":"Father, because of the Blood of Jesus, let my testimony encourage others to trust in Your mercy, Your wisdom, and Your healing power. Whether through healing, strength in weakness, or sustaining grace, let my life bring glory to Christ.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-4-1-19","o2":"s-4-1-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus You are my Healer, my Sustainer, and my Life. I receive Your grace to walk in faith, wisdom, obedience, and health according to Your perfect will, and I dedicate my body to Your service until the day I see You face to face.","scripture":[{"ref":"3 John 2","verses":[{"n":"2","text":"“Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.”"}]}],"o":"s-4-1-20","o2":"s-4-1-20"}]},{"orig":26,"title":"Prayer for Divine Health, Strength, and Long Life","foundation":[{"ref":"Jeremiah 30:17","verses":[{"n":"17","text":"“For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after.”"}]},{"ref":"Psalm 91:16","verses":[{"n":"16","text":"“With long life will I satisfy him, and shew him my salvation.”"}]}],"prayers":[{"text":"Father, according to Your mercy, restore and preserve my health so that I may glorify You in my body and faithfully fulfill every assignment You have given me.","scripture":[],"o":"s-4-2-1","o2":"s-4-2-1"},{"text":"Lord Jesus, strengthen every organ, every cell, every bone, every muscle, every nerve, and every system of my body according to Your perfect design.","scripture":[],"o":"s-4-2-2","o2":"s-4-2-2"},{"text":"Father, grant me wisdom to care for the body You have entrusted to me through godly habits, self-control, and faithful stewardship.","scripture":[],"o":"s-4-2-3","o2":"s-4-2-3"},{"text":"Lord, preserve me from every sickness, disease, accident, hidden danger, and untimely death according to Your will.","scripture":[],"o":"s-4-2-4","o2":"s-4-2-4"},{"text":"Father, renew my strength daily so that I may never grow weary in serving You.","scripture":[],"o":"s-4-2-5","o2":"s-4-2-5"},{"text":"Lord Jesus, grant me peaceful sleep, emotional stability, soundness of mind, and continual spiritual refreshment.","scripture":[],"o":"s-4-2-6","o2":"s-4-2-6"},{"text":"Father, let my health become a testimony of Your sustaining grace and faithfulness.","scripture":[],"o":"s-4-2-7","o2":"s-4-2-7"},{"text":"Lord, help me to use every day of life wisely for Your Kingdom and Your glory.","scripture":[],"o":"s-4-2-8","o2":"s-4-2-8"},{"text":"Father, satisfy me with long life according to Your purpose, and let me finish my course with joy.","scripture":[],"o":"s-4-2-9","o2":"s-4-2-9"},{"text":"Thank You, Lord, because You are my Healer, my Sustainer, and the Giver of every breath I take.","scripture":[],"o":"s-4-2-10","o2":"s-4-2-10"}]}]},{"label":"Part FIVE","title":"MY FINANCES, MY WORK, AND MY STUDIES","subtitle":"Prayers for provision, profession, business, and education","sections":[{"orig":27,"title":"Pleading the Blood of Jesus Over My Finances","foundation":[{"ref":"2 Corinthians 8:9","verses":[{"n":"9","text":"“For ye know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that ye through his poverty might be rich.”"}]},{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Colossians 1:20","verses":[{"n":"20","text":"“And, having made peace through the blood of his cross, by him to reconcile all things unto himself; by him, I say, whether they be things in earth, or things in heaven.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my finances. Let the Blood of the everlasting covenant sanctify, preserve, and establish every financial blessing You have entrusted to me.","scripture":[],"o":"s-5-1-1","o2":"s-5-1-1"},{"text":"Lord Jesus, let Your Blood speak better things over my finances than every voice of poverty, debt, financial hardship, limitation, lack, loss, or failure.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-5-1-2","o2":"s-5-1-2"},{"text":"Father, by the Blood of Jesus, I cancel every curse of poverty, financial stagnation, inherited lack, and every evil covenant working against my prosperity.","scripture":[{"ref":"Galatians 3:13","verses":[{"n":"13","text":"“Christ hath redeemed us from the curse of the law, being made a curse for us: for it is written, Cursed is every one that hangeth on a tree:”"}]}],"o":"s-5-1-3","o2":"s-5-1-3"},{"text":"Lord, let the Blood of Jesus rebuke every devourer assigned against my income, savings, investments, business, employment, and financial future.","scripture":[{"ref":"Malachi 3:11","verses":[{"n":"11","text":"“And I will rebuke the devourer for your sakes, and he shall not destroy the fruits of your ground; neither shall your vine cast her fruit before the time in the field, saith the LORD of hosts.”"}]}],"o":"s-5-1-4","o2":"s-5-1-4"},{"text":"Father, by the Blood of Jesus, bless the work of my hands. Let every honest labor, business, investment, profession, and ministry in God’s Remnant Assembly prosper according to Your will.","scripture":[{"ref":"Deuteronomy 28:12","verses":[{"n":"12","text":"“The LORD shall open unto thee his good treasure, the heaven to give the rain unto thy land in his season, and to bless all the work of thine hand: and thou shalt lend unto many nations, and thou shalt not borrow.”"}]}],"o":"s-5-1-5","o2":"s-5-1-5"},{"text":"Lord Jesus, let the Blood of Jesus open doors of divine provision, promotion, contracts, opportunities, favor, and increase that no man can shut.","scripture":[{"ref":"Revelation 3:8","verses":[{"n":"8","text":"“I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"o":"s-5-1-6","o2":"s-5-1-6"},{"text":"Father, by the Blood of Jesus, deliver me from waste, fraud, theft, financial deception, poor decisions, and every trap of the enemy.","scripture":[{"ref":"Proverbs 3:5–6","verses":[{"n":"5","text":"“Trust in the LORD with all thine heart; and lean not unto thine own understanding."},{"n":"6","text":"In all thy ways acknowledge him, and he shall direct thy paths.”"}]}],"o":"s-5-1-7","o2":"s-5-1-7"},{"text":"Lord, let the Blood of Jesus give me wisdom to manage every resource faithfully, honorably, and according to biblical principles.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]}],"o":"s-5-1-8","o2":"s-5-1-8"},{"text":"Father, by the Blood of Jesus, remove every burden of debt that hinders Your purpose for my life. Grant me grace to live wisely, honestly, and generously.","scripture":[{"ref":"Romans 13:8","verses":[{"n":"8","text":"“Owe no man any thing, but to love one another: for he that loveth another hath fulfilled the law.”"}]}],"o":"s-5-1-9","o2":"s-5-1-9"},{"text":"Lord, let the Blood of Jesus preserve my business, career, employment, profession, investments, retirement, and every lawful source of income from loss and destruction.","scripture":[{"ref":"Psalm 90:17","verses":[{"n":"17","text":"“And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.”"}]}],"o":"s-5-1-10","o2":"s-5-1-10"},{"text":"Father, by the Blood of Jesus, let every delayed financial blessing, inheritance, promotion, reimbursement, provision, and answered prayer be released in Your perfect timing.","scripture":[{"ref":"Habakkuk 2:3","verses":[{"n":"3","text":"“For the vision is yet for an appointed time, but at the end it shall speak, and not lie: though it tarry, wait for it; because it will surely come, it will not tarry.”"}]}],"o":"s-5-1-11","o2":"s-5-1-11"},{"text":"Lord Jesus, let the Blood of Jesus break every yoke of financial oppression, anxiety, fear, insufficiency, and discouragement.","scripture":[{"ref":"2 Timothy 1:7","verses":[{"n":"7","text":"“For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.”"}]}],"o":"s-5-1-12","o2":"s-5-1-12"},{"text":"Father, by the Blood of Jesus, make me a faithful steward who honors You with my substance, gives generously, and uses wealth for the advancement of Your Kingdom.","scripture":[{"ref":"Proverbs 3:9–10","verses":[{"n":"9","text":"“Honour the LORD with thy substance, and with the firstfruits of all thine increase:"},{"n":"10","text":"So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.”"}]}],"o":"s-5-1-13","o2":"s-5-1-13"},{"text":"Lord, let the Blood of Jesus preserve me from greed, covetousness, dishonesty, corruption, and every temptation connected with money.","scripture":[{"ref":"Hebrews 13:5","verses":[{"n":"5","text":"“Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.”"}]}],"o":"s-5-1-14","o2":"s-5-1-14"},{"text":"Father, because of the Blood of Jesus, let my finances become a channel of blessing to my family, the poor, missionaries, the Church, and the work of the Gospel.","scripture":[{"ref":"2 Corinthians 9:8","verses":[{"n":"8","text":"“And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:”"}]}],"o":"s-5-1-15","o2":"s-5-1-15"},{"text":"Lord Jesus, by Your precious Blood, let there be supernatural restoration of every financial opportunity, business, investment, or resource that has been lost according to Your will.","scripture":[{"ref":"Joel 2:25","verses":[{"n":"25","text":"“And I will restore to you the years that the locust hath eaten, the cankerworm, and the caterpiller, and the palmerworm, my great army which I sent among you.”"}]}],"o":"s-5-1-16","o2":"s-5-1-16"},{"text":"Father, let the Blood of Jesus establish lasting peace over my financial life. Remove worry and teach me to trust in Your daily provision.","scripture":[{"ref":"Matthew 6:31–33","verses":[{"n":"31","text":"“Therefore take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed?"},{"n":"32","text":"(For after all these things do the Gentiles seek:) for your heavenly Father knoweth that ye have need of all these things."},{"n":"33","text":"But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.”"}]}],"o":"s-5-1-17","o2":"s-5-1-17"},{"text":"Lord, by the Blood of Jesus, cause me to prosper spiritually before I prosper materially. Let my heart always remain devoted to Christ above riches.","scripture":[{"ref":"Matthew 6:24","verses":[{"n":"24","text":"“No man can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon.”"}]}],"o":"s-5-1-18","o2":"s-5-1-18"},{"text":"Father, let the Blood of Jesus make me a faithful witness through my financial integrity. May every blessing You entrust to me bring glory to Your holy name and advance Your Kingdom.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-5-1-19","o2":"s-5-1-19"},{"text":"Thank You, Heavenly Father, because through the Blood of Jesus You are my Provider, my Sustainer, and my Shepherd. I declare that You will supply all my needs according to Your riches in glory by Christ Jesus, and I dedicate every financial blessing You entrust to me to Your honor and the advancement of the Gospel.","scripture":[{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]}],"o":"s-5-1-20","o2":"s-5-1-20"}]},{"orig":28,"title":"Pleading the Blood of Jesus Over My Profession, Business, and School","foundation":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]},{"ref":"Revelation 12:11","verses":[{"n":"11","text":"“And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.”"}]},{"ref":"Deuteronomy 28:12","verses":[{"n":"12","text":"“The LORD shall open unto thee his good treasure, the heaven to give the rain unto thy land in his season, and to bless all the work of thine hand: and thou shalt lend unto many nations, and thou shalt not borrow.”"}]},{"ref":"Colossians 3:23–24","verses":[{"n":"23","text":"“And whatsoever ye do, do it heartily, as to the Lord, and not unto men;"},{"n":"24","text":"Knowing that of the Lord ye shall receive the reward of the inheritance: for ye serve the Lord Christ.”"}]},{"ref":"Daniel 1:17","verses":[{"n":"17","text":"“As for these four children, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams.”"}]}],"prayers":[{"text":"Father, in the name of Jesus Christ, I plead the precious Blood of Jesus over my profession, my business, my education, my school, and every work of my hands. Let the Blood of the everlasting covenant sanctify, establish, and prosper all that You have entrusted to me.","scripture":[],"o":"s-5-2-1","o2":"s-5-2-1"},{"text":"Lord Jesus, let Your Blood speak better things over my profession, business, education, examinations, career, and future than every voice of failure, rejection, limitation, unemployment, loss, or disappointment.","scripture":[{"ref":"Hebrews 12:24","verses":[{"n":"24","text":"“And to Jesus the mediator of the new covenant, and to the blood of sprinkling, that speaketh better things than that of Abel.”"}]}],"o":"s-5-2-2","o2":"s-5-2-2"},{"text":"Father, by the Blood of Jesus, bless every honest labor of my hands. Let my profession, career, business, and studies prosper according to Your perfect will.","scripture":[{"ref":"Deuteronomy 28:12","verses":[{"n":"12","text":"“The LORD shall open unto thee his good treasure, the heaven to give the rain unto thy land in his season, and to bless all the work of thine hand: and thou shalt lend unto many nations, and thou shalt not borrow.”"}]}],"o":"s-5-2-3","o2":"s-5-2-3"},{"text":"Lord, by the Blood of Jesus, open doors of divine opportunities, promotions, scholarships, research breakthroughs, contracts, partnerships, employment, admissions, and advancement that no man can shut.","scripture":[{"ref":"Revelation 3:8","verses":[{"n":"8","text":"“I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.”"}]}],"o":"s-5-2-4","o2":"s-5-2-4"},{"text":"Father, let the Blood of Jesus destroy every spirit of failure, delay, stagnation, confusion, discouragement, and defeat assigned against my career, business, and education.","scripture":[{"ref":"Isaiah 54:17","verses":[{"n":"17","text":"“No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.”"}]}],"o":"s-5-2-5","o2":"s-5-2-5"},{"text":"Lord Jesus, grant me divine wisdom, knowledge, understanding, creativity, innovation, excellence, and skill through the power of Your Blood, as You gave to Daniel and his companions.","scripture":[{"ref":"James 1:5","verses":[{"n":"5","text":"“If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.”"}]},{"ref":"Daniel 1:17","verses":[{"n":"17","text":"“As for these four children, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams.”"}]}],"o":"s-5-2-6","o2":"s-5-2-6"},{"text":"Father, by the Blood of Jesus, preserve me from every mistake, poor judgment, unethical practice, dishonesty, corruption, fraud, and every temptation that would dishonor Your name.","scripture":[{"ref":"Proverbs 10:9","verses":[{"n":"9","text":"“He that walketh uprightly walketh surely: but he that perverteth his ways shall be known.”"}]}],"o":"s-5-2-7","o2":"s-5-2-7"},{"text":"Lord, let the Blood of Jesus give me favor before employers, supervisors, professors, teachers, examiners, clients, business partners, customers, and colleagues, as Joseph found favor before Potiphar and Pharaoh.","scripture":[{"ref":"Psalm 5:12","verses":[{"n":"12","text":"“For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.”"}]},{"ref":"Genesis 39:4","verses":[{"n":"4","text":"“And Joseph found grace in his sight, and he served him: and he made him overseer over his house, and all that he had he put into his hand.”"}]}],"o":"s-5-2-8","o2":"s-5-2-8"},{"text":"Father, by the Blood of Jesus, preserve my business, career, profession, research, investments, projects, assignments, and academic work from every attack of the enemy.","scripture":[{"ref":"Psalm 121:7–8","verses":[{"n":"7","text":"“The LORD shall preserve thee from all evil: he shall preserve thy soul."},{"n":"8","text":"The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.”"}]}],"o":"s-5-2-9","o2":"s-5-2-9"},{"text":"Lord Jesus, let the Blood of Jesus strengthen my mind, memory, concentration, discipline, diligence, and ability to learn and retain knowledge.","scripture":[{"ref":"Isaiah 11:2","verses":[{"n":"2","text":"“And the spirit of the LORD shall rest upon him, the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of the LORD;”"}]}],"o":"s-5-2-10","o2":"s-5-2-10"},{"text":"Father, by the Blood of Jesus, help me to be an excellent representative of Christ in my workplace, business, classroom, laboratory, hospital, office, and everywhere I serve.","scripture":[{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"o":"s-5-2-11","o2":"s-5-2-11"},{"text":"Lord, by the Blood of Jesus, protect me from unhealthy competition, envy, workplace conflicts, academic dishonesty, false accusations, discrimination, and injustice.","scripture":[{"ref":"Psalm 37:5–6","verses":[{"n":"5","text":"“Commit thy way unto the LORD; trust also in him; and he shall bring it to pass."},{"n":"6","text":"And he shall bring forth thy righteousness as the light, and thy judgment as the noonday.”"}]}],"o":"s-5-2-12","o2":"s-5-2-12"},{"text":"Father, let the Blood of Jesus raise faithful mentors, godly teachers, wise counselors, trustworthy colleagues, and Kingdom partners who will help me grow according to Your purpose, as Moses mentored Joshua.","scripture":[{"ref":"Proverbs 27:17","verses":[{"n":"17","text":"“Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.”"}]},{"ref":"Exodus 24:13","verses":[{"n":"13","text":"“And Moses rose up, and his minister Joshua: and Moses went up into the mount of God.”"}]}],"o":"s-5-2-13","o2":"s-5-2-13"},{"text":"Lord Jesus, by Your Blood, grant success in every examination, interview, presentation, project, publication, proposal, contract, negotiation, and assignment according to Your will.","scripture":[{"ref":"Psalm 90:17","verses":[{"n":"17","text":"“And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.”"}]}],"o":"s-5-2-14","o2":"s-5-2-14"},{"text":"Father, by the Blood of Jesus, let my business and profession become instruments for serving others, advancing righteousness, supporting missions, helping the needy, and glorifying Christ.","scripture":[{"ref":"Colossians 3:23","verses":[{"n":"23","text":"“And whatsoever ye do, do it heartily, as to the Lord, and not unto men;”"}]}],"o":"s-5-2-15","o2":"s-5-2-15"},{"text":"Lord, by the Blood of Jesus, preserve me from burnout, discouragement, fear, anxiety, laziness, procrastination, and every hindrance to faithful service.","scripture":[{"ref":"Isaiah 40:31","verses":[{"n":"31","text":"“But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.”"}]}],"o":"s-5-2-16","o2":"s-5-2-16"},{"text":"Father, let the Blood of Jesus establish lasting fruit in my profession, business, and education. Let the work of my hands bring blessing to many people and honor to Your name.","scripture":[{"ref":"John 15:16","verses":[{"n":"16","text":"“Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.”"}]}],"o":"s-5-2-17","o2":"s-5-2-17"},{"text":"Lord Jesus, by Your Blood, keep me humble in success, faithful in little things, grateful in every season, and dependent upon You alone.","scripture":[{"ref":"Proverbs 3:5–6","verses":[{"n":"5","text":"“Trust in the LORD with all thine heart; and lean not unto thine own understanding."},{"n":"6","text":"In all thy ways acknowledge him, and he shall direct thy paths.”"}]}],"o":"s-5-2-18","o2":"s-5-2-18"},{"text":"Father, let my profession, business, and education become platforms through which the Gospel is proclaimed, disciples are encouraged, lives are transformed, and Your Kingdom is advanced.","scripture":[{"ref":"Matthew 28:19","verses":[{"n":"19","text":"“Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost:”"}]}],"o":"s-5-2-19","o2":"s-5-2-19"},{"text":"Thank You, Heavenly Father, because through the precious Blood of Jesus my profession, my business, my education, and every work of my hands are redeemed, sanctified, protected, established, fruitful, and dedicated to Your glory. May every success You grant me become a testimony of Your faithfulness and a means of advancing the Kingdom of our Lord Jesus Christ.","scripture":[{"ref":"Philippians 4:13","verses":[{"n":"13","text":"“I can do all things through Christ which strengtheneth me.”"}]}],"o":"s-5-2-20","o2":"s-5-2-20"}]},{"orig":29,"title":"Prayer for Divine Prosperity","foundation":[{"ref":"3 John 2","verses":[{"n":"2","text":"“Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth.”"}]}],"prayers":[{"text":"Father, prosper me spiritually above all else, that I may know You more deeply.","scripture":[],"o":"s-5-3-1","o2":"s-5-3-1"},{"text":"Lord Jesus, bless the work of my hands according to Your will.","scripture":[],"o":"s-5-3-2","o2":"s-5-3-2"},{"text":"Father, grant me wisdom to manage every resource faithfully.","scripture":[],"o":"s-5-3-3","o2":"s-5-3-3"},{"text":"Lord, deliver me from greed and teach me contentment.","scripture":[],"o":"s-5-3-4","o2":"s-5-3-4"},{"text":"Father, let every blessing You entrust to me become a means of serving others.","scripture":[],"o":"s-5-3-5","o2":"s-5-3-5"},{"text":"Lord Jesus, establish my finances in righteousness and integrity.","scripture":[],"o":"s-5-3-6","o2":"s-5-3-6"},{"text":"Father, provide every resource necessary for the work You have assigned to me.","scripture":[],"o":"s-5-3-7","o2":"s-5-3-7"},{"text":"Lord, make me a cheerful giver and a faithful steward.","scripture":[],"o":"s-5-3-8","o2":"s-5-3-8"},{"text":"Father, let my prosperity advance the Gospel and glorify Christ.","scripture":[],"o":"s-5-3-9","o2":"s-5-3-9"},{"text":"Thank You, Lord, because You are my Provider and Sustainer forever.","scripture":[],"o":"s-5-3-10","o2":"s-5-3-10"}]},{"orig":30,"title":"Prayer for a Glorious Career and Profession","foundation":[{"ref":"Deuteronomy 28:12","verses":[{"n":"12","text":"“The LORD shall open unto thee his good treasure, the heaven to give the rain unto thy land in his season, and to bless all the work of thine hand: and thou shalt lend unto many nations, and thou shalt not borrow.”"}]}],"prayers":[{"text":"Father, establish me in the profession You have prepared for me according to Your perfect will.","scripture":[],"o":"s-5-4-1","o2":"s-5-4-1"},{"text":"Lord Jesus, grant me excellence, wisdom, creativity, integrity, and diligence in all my work.","scripture":[],"o":"s-5-4-2","o2":"s-5-4-2"},{"text":"Father, open doors of employment, promotion, leadership, research, and service that glorify Christ.","scripture":[],"o":"s-5-4-3","o2":"s-5-4-3"},{"text":"Lord, help me to become a blessing to my colleagues, clients, students, patients, and everyone I serve.","scripture":[],"o":"s-5-4-4","o2":"s-5-4-4"},{"text":"Father, let my profession become a platform for demonstrating Christian character and advancing the Gospel.","scripture":[],"o":"s-5-4-5","o2":"s-5-4-5"},{"text":"Lord Jesus, preserve me from compromise, dishonesty, corruption, and every temptation.","scripture":[],"o":"s-5-4-6","o2":"s-5-4-6"},{"text":"Father, let the work of my hands produce lasting fruit and benefit many people.","scripture":[],"o":"s-5-4-7","o2":"s-5-4-7"},{"text":"Lord, give me favor with supervisors, employers, institutions, and decision-makers according to Your will.","scripture":[],"o":"s-5-4-8","o2":"s-5-4-8"},{"text":"Father, may my professional life reflect the excellence and humility of Christ.","scripture":[],"o":"s-5-4-9","o2":"s-5-4-9"},{"text":"Thank You, Lord, because every good opportunity comes from Your gracious hand.","scripture":[],"o":"s-5-4-10","o2":"s-5-4-10"}]},{"orig":31,"title":"Prayer to Establish My Business for God’s Glory","foundation":[{"ref":"Deuteronomy 8:18","verses":[{"n":"18","text":"“But thou shalt remember the LORD thy God: for it is he that giveth thee power to get wealth, that he may establish his covenant which he sware unto thy fathers, as it is this day.”"}]}],"prayers":[{"text":"Father, if it is Your will, establish the business You have prepared for me and let it become an instrument for Your glory.","scripture":[],"o":"s-5-5-1","o2":"s-5-5-1"},{"text":"Lord Jesus, grant me wisdom to build every enterprise upon righteousness, honesty, and biblical principles.","scripture":[],"o":"s-5-5-2","o2":"s-5-5-2"},{"text":"Father, bless the work of my hands and teach me to serve people with excellence and integrity.","scripture":[],"o":"s-5-5-3","o2":"s-5-5-3"},{"text":"Lord, surround me with wise counselors, trustworthy partners, and faithful employees.","scripture":[],"o":"s-5-5-4","o2":"s-5-5-4"},{"text":"Father, preserve me from greed, dishonest gain, pride, and every temptation that prosperity can bring.","scripture":[],"o":"s-5-5-5","o2":"s-5-5-5"},{"text":"Lord Jesus, let my business become a source of employment, generosity, compassion, and Kingdom impact.","scripture":[],"o":"s-5-5-6","o2":"s-5-5-6"},{"text":"Father, help me to honor You with my substance and with the firstfruits of all my increase.","scripture":[],"o":"s-5-5-7","o2":"s-5-5-7"},{"text":"Lord, let every success remind me that You alone are the source of every blessing.","scripture":[],"o":"s-5-5-8","o2":"s-5-5-8"},{"text":"Father, may every resource You entrust to me be used faithfully for Your Kingdom.","scripture":[],"o":"s-5-5-9","o2":"s-5-5-9"},{"text":"Thank You, Lord, because You are able to prosper the work that is according to Your will.","scripture":[],"o":"s-5-5-10","o2":"s-5-5-10"}]},{"orig":32,"title":"Prayer for Divine Distinction and Excellence","foundation":[{"ref":"Daniel 6:3","verses":[{"n":"3","text":"“Then this Daniel was preferred above the presidents and princes, because an excellent spirit was in him; and the king thought to set him over the whole realm.”"}]},{"ref":"Deuteronomy 28:13","verses":[{"n":"13","text":"“And the LORD shall make thee the head, and not the tail; and thou shalt be above only, and thou shalt not be beneath; if that thou hearken unto the commandments of the LORD thy God, which I command thee this day, to observe and to do them:”"}]},{"ref":"Matthew 5:16","verses":[{"n":"16","text":"“Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.”"}]}],"prayers":[{"text":"Father, let the Spirit of excellence rest upon my life as it rested upon Daniel, so that everything I do will bring honor to the name of Jesus Christ.","scripture":[],"o":"s-5-6-1","o2":"s-5-6-1"},{"text":"Lord Jesus, distinguish me by Your grace, not for my own glory, but so that many people may glorify my Father which is in heaven.","scripture":[],"o":"s-5-6-2","o2":"s-5-6-2"},{"text":"Father, make me the head and not the tail in every assignment You have entrusted to me, according to Your perfect will.","scripture":[],"o":"s-5-6-3","o2":"s-5-6-3"},{"text":"Lord, let excellence characterize my prayer life, my preaching, my studies, my profession, my ministry, my leadership, and my daily conduct.","scripture":[],"o":"s-5-6-4","o2":"s-5-6-4"},{"text":"Father, remove every spirit of mediocrity, laziness, carelessness, procrastination, and complacency from my life.","scripture":[],"o":"s-5-6-5","o2":"s-5-6-5"},{"text":"Lord Jesus, help me to pursue excellence because I serve Christ and not merely men.","scripture":[],"o":"s-5-6-6","o2":"s-5-6-6"},{"text":"Father, let my work consistently reflect integrity, diligence, wisdom, humility, and faithfulness.","scripture":[],"o":"s-5-6-7","o2":"s-5-6-7"},{"text":"Lord, grant me skill, understanding, creativity, and innovation that will make me effective in every assignment You have given me.","scripture":[],"o":"s-5-6-8","o2":"s-5-6-8"},{"text":"Father, let people see Christ through the quality of my character more than through the greatness of my achievements.","scripture":[],"o":"s-5-6-9","o2":"s-5-6-9"},{"text":"Lord Jesus, establish an excellent spirit within me that remains constant whether I am seen by many or by few.","scripture":[],"o":"s-5-6-10","o2":"s-5-6-10"},{"text":"Father, let excellence open doors for the Gospel through my life.","scripture":[],"o":"s-5-6-11","o2":"s-5-6-11"},{"text":"Lord, help me to prepare thoroughly, think biblically, speak wisely, and serve faithfully.","scripture":[],"o":"s-5-6-12","o2":"s-5-6-12"},{"text":"Father, make me dependable, trustworthy, and faithful in both small and great responsibilities.","scripture":[],"o":"s-5-6-13","o2":"s-5-6-13"},{"text":"Lord Jesus, let every gift You have placed within me be developed to its fullest potential for Your glory.","scripture":[],"o":"s-5-6-14","o2":"s-5-6-14"},{"text":"Father, let my life become a pattern of disciplined Christian living.","scripture":[],"o":"s-5-6-15","o2":"s-5-6-15"},{"text":"Lord, grant me wisdom to continually improve while remaining humble before You.","scripture":[],"o":"s-5-6-16","o2":"s-5-6-16"},{"text":"Father, let Your favor accompany every excellent work performed for Your Kingdom.","scripture":[],"o":"s-5-6-17","o2":"s-5-6-17"},{"text":"Lord Jesus, raise me as an example that encourages others to pursue holiness, diligence, and excellence.","scripture":[],"o":"s-5-6-18","o2":"s-5-6-18"},{"text":"Father, let every honor You allow me to receive become another opportunity to exalt Christ rather than myself.","scripture":[],"o":"s-5-6-19","o2":"s-5-6-19"},{"text":"Thank You, Heavenly Father, because every good and perfect gift comes from You, and I dedicate every ability, every success, and every accomplishment to the glory of Jesus Christ alone.","scripture":[],"o":"s-5-6-20","o2":"s-5-6-20"}]},{"orig":33,"title":"Prayer for Supernatural Provision for Kingdom Assignments","foundation":[{"ref":"Philippians 4:19","verses":[{"n":"19","text":"“But my God shall supply all your need according to his riches in glory by Christ Jesus.”"}]},{"ref":"2 Corinthians 9:8","verses":[{"n":"8","text":"“And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:”"}]}],"prayers":[{"text":"Father, supply every resource needed to fulfill every Kingdom assignment You have entrusted to me.","scripture":[],"o":"s-5-7-1","o2":"s-5-7-1"},{"text":"Lord Jesus, provide spiritual strength, wisdom, grace, and endurance for every responsibility.","scripture":[],"o":"s-5-7-2","o2":"s-5-7-2"},{"text":"Father, provide every financial resource needed for the advancement of Your Kingdom according to Your perfect will.","scripture":[],"o":"s-5-7-3","o2":"s-5-7-3"},{"text":"Lord, raise faithful partners and co-laborers who share a sincere desire to glorify Christ.","scripture":[],"o":"s-5-7-4","o2":"s-5-7-4"},{"text":"Father, let there never be lack where You have truly called and commissioned me.","scripture":[],"o":"s-5-7-5","o2":"s-5-7-5"},{"text":"Lord Jesus, teach me to depend upon You daily rather than upon earthly resources alone.","scripture":[],"o":"s-5-7-6","o2":"s-5-7-6"},{"text":"Father, bless me so that I may become a blessing to many others.","scripture":[],"o":"s-5-7-7","o2":"s-5-7-7"},{"text":"Lord, help me to be faithful with little so that I may faithfully steward greater responsibilities.","scripture":[],"o":"s-5-7-8","o2":"s-5-7-8"},{"text":"Father, let every provision You send be used wisely, honestly, and for the advancement of the Gospel.","scripture":[],"o":"s-5-7-9","o2":"s-5-7-9"},{"text":"Lord Jesus, remove every fear concerning future provision and strengthen my confidence in Your faithfulness.","scripture":[],"o":"s-5-7-10","o2":"s-5-7-10"},{"text":"Father, let my heart never trust in riches but always in the living God.","scripture":[],"o":"s-5-7-11","o2":"s-5-7-11"},{"text":"Lord, make me generous toward missions, evangelism, the poor, and the work of Your Church.","scripture":[],"o":"s-5-7-12","o2":"s-5-7-12"},{"text":"Father, let every seed sown for Your Kingdom produce lasting spiritual fruit.","scripture":[],"o":"s-5-7-13","o2":"s-5-7-13"},{"text":"Lord Jesus, help me distinguish between needs, wants, and Your perfect priorities.","scripture":[],"o":"s-5-7-14","o2":"s-5-7-14"},{"text":"Father, provide every book, mentor, opportunity, relationship, and resource needed for my growth.","scripture":[],"o":"s-5-7-15","o2":"s-5-7-15"},{"text":"Lord, let Your abundant grace enable me to abound in every good work.","scripture":[],"o":"s-5-7-16","o2":"s-5-7-16"},{"text":"Father, preserve me from waste, unnecessary debt, and unwise stewardship.","scripture":[],"o":"s-5-7-17","o2":"s-5-7-17"},{"text":"Lord Jesus, let every blessing You entrust to me become a testimony of Your goodness.","scripture":[],"o":"s-5-7-18","o2":"s-5-7-18"},{"text":"Father, may everything You provide ultimately serve the salvation of souls and the building up of Your Church.","scripture":[],"o":"s-5-7-19","o2":"s-5-7-19"},{"text":"Thank You, Heavenly Father, because You are Jehovah-Jireh, and You will faithfully supply all my needs according to Your riches in glory by Christ Jesus.","scripture":[],"o":"s-5-7-20","o2":"s-5-7-20"}]}]}]$json$::jsonb, $json$[{"u":"part-1","s":[{"u":"s-1-1","p":["s-1-1-1","s-1-1-2","s-1-1-3","s-1-1-4","s-1-1-5","s-1-1-6","s-1-1-7","s-1-1-8","s-1-1-9","s-1-1-10","s-1-1-11","s-1-1-12","s-1-1-13","s-1-1-14","s-1-1-15","s-1-1-16","s-1-1-17","s-1-1-18","s-1-1-19","s-1-1-20"]},{"u":"s-1-2","p":["s-1-2-1","s-1-2-2","s-1-2-3","s-1-2-4","s-1-2-5","s-1-2-6","s-1-2-7","s-1-2-8","s-1-2-9","s-1-2-10","s-1-2-11","s-1-2-12","s-1-2-13","s-1-2-14","s-1-2-15","s-1-2-16","s-1-2-17","s-1-2-18","s-1-2-19","s-1-2-20"]},{"u":"s-1-3","p":["s-1-3-1","s-1-3-2","s-1-3-3","s-1-3-4","s-1-3-5","s-1-3-6","s-1-3-7","s-1-3-8","s-1-3-9","s-1-3-10","s-1-3-11","s-1-3-12","s-1-3-13","s-1-3-14","s-1-3-15","s-1-3-16","s-1-3-17","s-1-3-18","s-1-3-19","s-1-3-20"]},{"u":"s-1-4","p":["s-1-4-1","s-1-4-2","s-1-4-3","s-1-4-4","s-1-4-5","s-1-4-6","s-1-4-7","s-1-4-8","s-1-4-9","s-1-4-10","s-1-4-11","s-1-4-12","s-1-4-13","s-1-4-14","s-1-4-15","s-1-4-16","s-1-4-17","s-1-4-18","s-1-4-19","s-1-4-20","s-1-4-21"]},{"u":"s-1-5","p":["s-1-5-1","s-1-5-2","s-1-5-3","s-1-5-4","s-1-5-5","s-1-5-6","s-1-5-7","s-1-5-8","s-1-5-9","s-1-5-10","s-1-5-11","s-1-5-12","s-1-5-13","s-1-5-14","s-1-5-15","s-1-5-16","s-1-5-17","s-1-5-18","s-1-5-19","s-1-5-20","s-1-5-21"]},{"u":"s-1-6","p":["s-1-6-1","s-1-6-2","s-1-6-3","s-1-6-4","s-1-6-5","s-1-6-6","s-1-6-7","s-1-6-8","s-1-6-9","s-1-6-10","s-1-6-11","s-1-6-12","s-1-6-13","s-1-6-14"