insert into public.book_editions (book_slug, version, data, layout, note) values ('jcfp', 0, $json$[{"label":"Prayer Watch ONE","title":"FIRST PRAYER WATCH","subtitle":"","sections":[{"title":"Prayers for America","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayers for America","scripture":[{"ref":"1 Timothy 2:1-3","verses":[{"n":"","text":"I exhort therefore, that, first of all, supplications, prayers, intercessions, and giving of thanks, be made for all men;For kings, and for all that are in authority; that we may lead a quiet and peaceable life in all godliness and honesty. For this is good and acceptable in the sight of God our Saviour;"}]},{"ref":"Jeremiah 29:7","verses":[{"n":"","text":"And seek the peace of the city whither I have caused you to be carried away captives, and pray unto the Lord for it: for in the peace thereof shall ye have peace."}]},{"ref":"Proverbs 14:34","verses":[{"n":"","text":"Righteousness exalteth a nation: but sin is a reproach to any people."}]}]}]},{"title":"Prayer for 10/196 nations","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for 10/196 nations","scripture":[{"ref":"Deuteronomy 11:24","verses":[{"n":"","text":"Every place whereon the soles of your feet shall tread shall be yours: from the wilderness and Lebanon, from the river, the river Euphrates, even unto the uttermost sea shall your coast be."}]},{"ref":"Joshua 1:3","verses":[{"n":"","text":"Every place that the sole of your foot shall tread upon, that have I given unto you, as I said unto Moses."}]},{"ref":"Genesis 13:17","verses":[{"n":"","text":"Arise, walk through the land in the length of it and in the breadth of it; for I will give it unto thee."}]},{"ref":"Psalm 2:7-8","verses":[{"n":"7","text":"I will declare the decree: the Lord hath said unto me, Thou art my Son; this day have I begotten thee."},{"n":"8","text":"Ask of me, and I shall give thee the heathen for thine inheritance, and the uttermost parts of the earth for thy possession."}]}]}]},{"title":"Prayer for God’s Remnant Assembly Mega Churches","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for God’s Remnant Assembly Mega Churches","scripture":[{"ref":"Psalm 2:8","verses":[{"n":"","text":"Ask of me, and I shall give thee the heathen for thine inheritance, and the uttermost parts of the earth for thy possession."}]},{"ref":"Isaiah 9:8","verses":[{"n":"","text":"The Lord sent a word into Jacob, and it hath lighted upon Israel."}]},{"ref":"Isaiah 27:6","verses":[{"n":"","text":"He shall cause them that come of Jacob to take root: Israel shall blossom and bud, and fill the face of the world with fruit."}]},{"ref":"Matthew 5:13","verses":[{"n":"","text":"Ye are the salt of the earth: but if the salt have lost his savour, wherewith shall it be salted? It is thenceforth good for nothing, but to be cast out, and to be trodden under foot of men."}]},{"ref":"Luke 8:19","verses":[{"n":"","text":"Then came to him his mother and his brethren, and could not come at him for the press."}]},{"ref":"Mark 2:4","verses":[{"n":"","text":"And when they could not come nigh unto him for the press, they uncovered the roof where he was: and when they had broken it up, they let down the bed wherein the sick of the palsy lay."}]}]}]},{"title":"Prayer for GRA Mission Squad Global","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for GRA Mission Squad Global","scripture":[{"ref":"Acts 13:47","verses":[{"n":"","text":"For so hath the Lord commanded us, saying, I have set thee to be a light of the Gentiles, that thou shouldest be for salvation unto the ends of the earth."}]},{"ref":"1 Chronicles 16:24","verses":[{"n":"","text":"Declare his glory among the heathen; his marvellous works among all nations."}]},{"ref":"Isaiah 52:7","verses":[{"n":"","text":"How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!"}]}]}]},{"title":"Prayer for God’s Remnant Assembly Ministers (GRA Servant Leaders)","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for God’s Remnant Assembly Ministers (GRA Servant Leaders)","scripture":[{"ref":"1 Thessalonians 2:18","verses":[{"n":"","text":"Therefore, brethren, stand fast, and hold the traditions which ye have been taught, whether by word, or our epistle."}]},{"ref":"1 Thessalonians 5:25","verses":[{"n":"","text":"Brethren, pray for us."}]},{"ref":"2 Thessalonians 2:18","verses":[{"n":"","text":"Finally, brethren, pray for us, that the word of the Lord may have free course, and be glorified, even as it is with you: And that we may be delivered from unreasonable and wicked men: for all men have not faith."}]}]}]},{"title":"Prayer for the Establishment of God’s Covenant of Gathering Multitude in God’s Remnant Assembly","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for the Establishment of God’s Covenant of Gathering Multitude in God’s Remnant Assembly","scripture":[{"ref":"Micah 2:12","verses":[{"n":"","text":"I will surely assemble, O Jacob, all of thee; I will surely gather the remnant of Israel; I will put them together as the sheep of Bozrah, as the flock in the midst of their fold: they shall make great noise by reason of the multitude of men."}]},{"ref":"Matthew 13:2","verses":[{"n":"","text":"And great multitudes were gathered together unto him, so that he went into a ship, and sat; and the whole multitude stood on the shore."}]},{"ref":"Revelation 7:9","verses":[{"n":"","text":"After this I beheld, and, lo, a great multitude, which no man could number, of all nations, and kindreds, and people, and tongues, stood before the throne, and before the Lamb, clothed with white robes, and palms in their hands."}]}]}]},{"title":"Judgment in the House of God","hideTitle":true,"foundation":[],"prayers":[{"text":"Judgment in the House of God","scripture":[{"ref":"Isaiah 26:9","verses":[{"n":"","text":"With my soul have I desired thee in the night; yea, with my spirit within me will I seek thee early: for when thy judgments are in the earth, the inhabitants of the world will learn righteousness."}]},{"ref":"1 Peter 4:17","verses":[{"n":"","text":"For the time is come that judgment must begin at the house of God: and if it first begin at us, what shall the end be of them that obey not the gospel of God?"}]},{"ref":"Psalm 75","verses":[{"n":"1","text":"To thee, O God, do we give thanks: to thee do we give thanks: for that thy name is near thy wondrous works declare."},{"n":"2","text":"When I shall receive the congregation I will judge uprightly."},{"n":"3","text":"The earth and all the inhabitants thereof are dissolved: I bear up the pillars of it. Selah."},{"n":"4","text":"I said unto the fools, Deal not foolishly: and to the wicked, Lift not up the horn:"},{"n":"5","text":"Lift not up your horn on high: speak not with a stiff neck."},{"n":"6","text":"For promotion cometh neither from the east, nor from the west, nor from the south."},{"n":"7","text":"But God is the judge: he putteth down one, and setteth up another."},{"n":"8","text":"For in the hand of the Lord there is a cup, and the wine is red; it is full of mixture; and he poureth out of the same: but the dregs thereof, all the wicked of the earth shall wring them out, and drink them."},{"n":"9","text":"But I will declare for ever; I will sing praises to the God of Jacob."},{"n":"10","text":"All the horns of the wicked also will I cut off; but the horns of the righteous shall be exalted."}]}]}]},{"title":"Prayer Against Enemies","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer Against Enemies","scripture":[{"ref":"Matthew 5:44-45","verses":[{"n":"44","text":"But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;"},{"n":"45","text":"That ye may be the children of your Father which is in heaven: for he maketh his sun to rise on the evil and on the good, and sendeth rain on the just and on the unjust."}]},{"ref":"Luke 23:34","verses":[{"n":"","text":"Then said Jesus, Father, forgive them; for they know not what they do. And they parted his raiment, and cast lots."}]},{"ref":"Acts 7:60","verses":[{"n":"","text":"And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep."}]},{"ref":"1 Timothy 1:13","verses":[{"n":"","text":"Who was before a blasphemer, and a persecutor, and injurious: but I obtained mercy, because I did it ignorantly in unbelief."}]},{"ref":"Acts 22:25","verses":[{"n":"","text":"And as they bound him with thongs, Paul said unto the centurion that stood by, Is it lawful for you to scourge a man that is a Roman, and uncondemned?"}]},{"ref":"Deuteronomy 25:15","verses":[{"n":"","text":"But thou shalt have a perfect and just weight, a perfect and just measure shalt thou have: that thy days may be lengthened in the land which the Lord thy God giveth thee."}]},{"ref":"Revelation 11:1","verses":[{"n":"","text":"And there was given me a reed like unto a rod: and the angel stood, saying, Rise and measure the temple of God, and the altar, and them that worship therein."}]},{"ref":"Revelation 16:11","verses":[{"n":"","text":"And blasphemed the God of heaven because of their pains and their sores, and repented not of their deeds."}]},{"ref":"Deuteronomy 5:25-26, 30","verses":[{"n":"25","text":"Now therefore why should we die? For this great fire will consume us: if we hear the voice of the Lord our God any more, then we shall die."},{"n":"26","text":"For who is there of all flesh, that hath heard the voice of the living God speaking out of the midst of the fire, as we have, and lived?"},{"n":"30","text":"Go say to them, Get you into your tents again."}]},{"ref":"Psalm 110","verses":[{"n":"1","text":"The Lord said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool."},{"n":"2","text":"The Lord shall send the rod of thy strength out of Zion: rule thou in the midst of thine enemies."},{"n":"3","text":"Thy people shall be willing in the day of thy power, in the beauties of holiness from the womb of the morning: thou hast the dew of thy youth."},{"n":"4","text":"The Lord hath sworn, and will not repent, Thou art a priest for ever after the order of Melchizedek."},{"n":"5","text":"The Lord at thy right hand shall strike through kings in the day of his wrath."},{"n":"6","text":"He shall judge among the heathen, he shall fill the places with the dead bodies; he shall wound the heads over many countries."},{"n":"7","text":"He shall drink of the brook in the way: therefore shall he lift up the head."}]}]}]}]},{"label":"Prayer Watch TWO","title":"SECOND PRAYER WATCH","subtitle":"","sections":[{"title":"Prophesy to the Four winds","hideTitle":true,"foundation":[],"prayers":[{"text":"Prophesy to the Four winds","scripture":[{"ref":"Luke 13:28-30","verses":[{"n":"28","text":"There shall be weeping and gnashing of teeth, when ye shall see Abraham, and Isaac, and Jacob, and all the prophets, in the kingdom of God, and you yourselves thrust out."},{"n":"29","text":"And they shall come from the east and from the west, and from the north and from the south, and shall sit down in the kingdom of God."},{"n":"30","text":"And, behold, there are last which shall be first, and there are first which shall be last."}]},{"ref":"Ezekiel 37:10","verses":[{"n":"","text":"So I prophesied as he commanded me, and the breath came into them, and they lived, and stood up upon their feet, an exceeding great army."}]},{"ref":"Isaiah 43:5-8","verses":[{"n":"5","text":"Fear not: for I am with thee: I will bring thy seed from the east, and gather thee from the west;"},{"n":"6","text":"I will say to the north, Give up; and to the south, Keep not back: bring my sons from far, and my daughters from the ends of the earth;"},{"n":"7","text":"Even every one that is called by my name: for I have created him for my glory, I have formed him; yea, I have made him."},{"n":"8","text":"Bring forth the blind people that have eyes, and the deaf that have ears."}]},{"ref":"Mark 13:27","verses":[{"n":"","text":"And then shall he send his angels, and shall gather together his elect from the four winds, from the uttermost part of the earth to the uttermost part of heaven."}]}]}]},{"title":"Pray for Upcoming Programs (i.e.Sunday Services, SOAK, Mega Exploits, Ministering To The Lord, Alpha & Omega Gathering,etc)","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for Upcoming Programs (i.e.Sunday Services, SOAK, Mega Exploits, Ministering To The Lord, Alpha & Omega Gathering,etc)","scripture":[{"ref":"Psalm 37:5","verses":[{"n":"","text":"Commit thy way unto the Lord; trust also in him; and he shall bring it to pass."}]},{"ref":"Proverbs 3:5-6","verses":[{"n":"5","text":"Trust in the LORD with all thine heart; and lean not unto thine own understanding."},{"n":"6","text":"In all thy ways acknowledge him, and he shall direct thy paths."}]},{"ref":"Psalm 32:8","verses":[{"n":"","text":"I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye."}]},{"ref":"Isaiah 48:17","verses":[{"n":"","text":"Thus saith the LORD, thy Redeemer, the Holy One of Israel; I am the LORD thy God which teacheth thee to profit, which leadeth thee by the way that thou shouldest go."}]},{"ref":"Psalm 127:1","verses":[{"n":"","text":"A Song of degrees for Solomon. Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain."}]}]}]},{"title":"Pray for God’s Remnant Assembly Workers / The Spirit of Servanthood","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for God’s Remnant Assembly Workers / The Spirit of Servanthood","scripture":[{"ref":"Exodus 23:25","verses":[{"n":"","text":"And ye shall serve the Lord your God, and he shall bless thy bread, and thy water; and I will take sickness away from the midst of thee."}]},{"ref":"Isaiah 42:1-4","verses":[{"n":"1","text":"Behold my servant, whom I uphold; mine elect, in whom my soul delighteth; I have put my spirit upon him: he shall bring forth judgment to the Gentiles."},{"n":"2","text":"He shall not cry, nor lift up, nor cause his voice to be heard in the street."},{"n":"3","text":"A bruised reed shall he not break, and the smoking flax shall he not quench: he shall bring forth judgment unto truth."},{"n":"4","text":"He shall not fail nor be discouraged, till he have set judgment in the earth: and the isles shall wait for his law."}]},{"ref":"John 13:15-16","verses":[{"n":"15","text":"For I have given you an example, that ye should do as I have done to you."},{"n":"16","text":"Verily, verily, I say unto you, The servant is not greater than his lord; neither he that is sent greater than he that sent him."}]}]}]},{"title":"Thank God for our Mega Buildings","hideTitle":true,"foundation":[],"prayers":[{"text":"Thank God for our Mega Buildings","scripture":[{"ref":"Luke 7:5","verses":[{"n":"","text":"For he loveth our nation, and he hath built us a synagogue."}]},{"ref":"Acts 2:41","verses":[{"n":"","text":"Then they that gladly received his word were baptized: and the same day there were added unto them about three thousand souls."}]}]}]},{"title":"Pray for the Fulfillment of Prophecies","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for the Fulfillment of Prophecies","scripture":[{"ref":"Job 22:28","verses":[{"n":"","text":"Thou shalt also decree a thing, and it shall be established unto thee: and the light shall shine upon thy ways."}]},{"ref":"1 Timothy 1:18","verses":[{"n":"","text":"This charge I commit unto thee, son Timothy, according to the prophecies which went before on thee, that thou by them mightest war a good warfare;"}]}]}]},{"title":"Pray for Evangelism/Soul Winning","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for Evangelism/Soul Winning","scripture":[{"ref":"Proverbs 11:30","verses":[{"n":"","text":"The fruit of the righteous is a tree of life; and he that winneth souls is wise."}]},{"ref":"Daniel 12:3","verses":[{"n":"","text":"And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever."}]}]}]},{"title":"Prayer for our Sons and Daughters in School and for their Perfection, Protection and Preservation","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for our Sons and Daughters in School and for their Perfection, Protection and Preservation","scripture":[{"ref":"Zecheriah 2:5","verses":[{"n":"","text":"For I, saith the Lord, will be unto her a wall of fire round about, and will be the glory in the midst of her."}]},{"ref":"Psalm 115:14","verses":[{"n":"","text":"The Lord shall increase you more and more, you and your children."}]},{"ref":"Isaiah 54:13","verses":[{"n":"","text":"And all thy children shall be taught of the Lord; and great shall be the peace of thy children. -"}]}]}]},{"title":"Pray for Israel","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for Israel","scripture":[{"ref":"Psalm 122:6-7","verses":[{"n":"6","text":"Pray for the peace of Jerusalem: they shall prosper that love thee."},{"n":"7","text":"Peace be within thy walls, and prosperity within thy palaces in thee."}]},{"ref":"Psalm 137:5","verses":[{"n":"","text":"If I forget thee, O Jerusalem, let my right hand forget her cunning."}]}]}]},{"title":"Pray for the Sweet Influence and Fresh Anointing of the Holy Spirit upon our Parents in the Lord and their Family. Pray for great and effectual open doors. Pray that Jesus Christ the adversary of the adversaries mounted at these open doors will eliminate all the adversaries because He is a man of war","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for the Sweet Influence and Fresh Anointing of the Holy Spirit upon our Parents in the Lord and their Family. Pray for great and effectual open doors. Pray that Jesus Christ the adversary of the adversaries mounted at these open doors will eliminate all the adversaries because He is a man of war","scripture":[{"ref":"Luke 1:16","verses":[{"n":"","text":"Pray for the Sweet Influence and Fresh Anointing of the Holy Spirit upon our Parents in the Lord and their Family. Pray for great and effectual open doors. Pray that Jesus Christ the adversary of the adversaries mounted at these open doors will eliminate all the adversaries because He is a man of war. And many of the children of Israel shall he turn to the Lord their God."}]},{"ref":"Luke 1:41","verses":[{"n":"","text":"And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost."}]},{"ref":"Luke 1:67","verses":[{"n":"","text":"And his father Zacharias was filled with the Holy Ghost, and prophesied, saying,"}]},{"ref":"Luke 11:13","verses":[{"n":"","text":"If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?"}]},{"ref":"Luke 24:49","verses":[{"n":"","text":"And, behold, I send the promise of my Father upon you: but tarry ye in the city of Jerusalem, until ye be endued with power from on high."}]},{"ref":"John 1:12","verses":[{"n":"","text":"But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name."}]},{"ref":"John 20:22","verses":[{"n":"","text":"And when he had said this, he breathed on them, and saith unto them, Receive ye the Holy Ghost."}]},{"ref":"Acts 1:8","verses":[{"n":"","text":"But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth."}]},{"ref":"Acts 2:4","verses":[{"n":"","text":"And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance."}]},{"ref":"Acts 4:8","verses":[{"n":"","text":"Then Peter, filled with the Holy Ghost, said unto them, Ye rulers of the people, and elders of Israel. -"}]},{"ref":"Acts 4:31","verses":[{"n":"","text":"And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness."}]},{"ref":"Acts 9:17","verses":[{"n":"","text":"And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost."}]},{"ref":"Acts 9:17","verses":[{"n":"","text":"And the disciples were filled with joy, and with the Holy Ghost."}]},{"ref":"Acts 2:38","verses":[{"n":"","text":"Then Peter said unto them, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost."}]},{"ref":"Acts 8:15-17","verses":[{"n":"15","text":"Who, when they were come down, prayed for them, that they might receive the Holy Ghost:"},{"n":"16","text":"For as yet he was fallen upon none of them: only they were baptized in the name of the Lord Jesus"},{"n":"17","text":"Then laid they their hands on them, and they received the Holy Ghost."}]},{"ref":"Acts 10:47","verses":[{"n":"","text":"Can any man forbid water, that these should not be baptized, which have received the Holy Ghost as well as we?"}]},{"ref":"Acts 19:1-6","verses":[{"n":"1","text":"And it came to pass, that, while Apollos was at Corinth, Paul having passed through the upper coasts came to Ephesus: and finding certain disciples,"},{"n":"2","text":"He said unto them, Have ye received the Holy Ghost since ye believed? And they said unto him, We have not so much as heard whether there be any Holy Ghost."},{"n":"3","text":"And he said unto them, Unto what then were ye baptized? And they said, Unto John's baptism."},{"n":"4","text":"Then said Paul, John verily baptized with the baptism of repentance, saying unto the people, that they should believe on him which should come after him, that is, on Christ Jesus."},{"n":"5","text":"When they heard this, they were baptized in the name of the Lord Jesus."},{"n":"6","text":"And when Paul had laid his hands upon them, the Holy Ghost came on them; and they spake with tongues, and prophesied."}]},{"ref":"1 Corinthians 16:9","verses":[{"n":"","text":"For a great door and effectual is opened unto me, and there are many adversaries."}]},{"ref":"Exodus 23:22,27","verses":[{"n":"","text":"But if thou shalt indeed obey his voice, and do all that I speak; then I will be an enemy unto thine enemies, and an adversary unto thine adversaries. I will send my fear before thee, and will destroy all the people to whom thou shalt come, and I will make all thine enemies turn their backs unto thee."}]},{"ref":"Numbers 10:35","verses":[{"n":"","text":"And it came to pass, when the ark set forward, that Moses said, Rise up, Lord, and let thine enemies be scattered; and let them that hate thee flee before thee."}]},{"ref":"Deuteronomy 6:19","verses":[{"n":"","text":"To cast out all thine enemies from before thee, as the Lord hath spoken."}]},{"ref":"Judges 5:31","verses":[{"n":"","text":"So let all thine enemies perish, O Lord: but let them that love him be as the sun when he goeth forth in his might. And the land had rest forty years."}]}]}]},{"title":"Pray to be Continually Filled with the Fresh Power of the Holy Spirit","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray to be Continually Filled with the Fresh Power of the Holy Spirit","scripture":[{"ref":"Luke 11:13","verses":[{"n":"","text":"If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?"}]},{"ref":"Ephesians 5:18","verses":[{"n":"","text":"And be not drunk with wine, wherein is excess; but be filled with the Spirit."}]},{"ref":"Ephesians 1:16-23","verses":[{"n":"16","text":"Cease not to give thanks for you, making mention of you in my prayers;"},{"n":"17","text":"That the God of our Lord Jesus Christ, the Father of glory, may give unto you the spirit of wisdom and revelation in the knowledge of him:"},{"n":"18","text":"The eyes of your understanding being enlightened; that ye may know what is the hope of his calling, and what the riches of the glory of his inheritance in the saints,"},{"n":"19","text":"And what is the exceeding greatness of his power to us-ward who believe, according to the working of his mighty power,"},{"n":"20","text":"Which he wrought in Christ, when he raised him from the dead, and set him at his own right hand in the heavenly places,"},{"n":"21","text":"Far above all principality, and power, and might, and dominion, and every name that is named, not only in this world, but also in that which is to come:"},{"n":"22","text":"And hath put all things under his feet, and gave him to be the head over all things to the church,"},{"n":"23","text":"Which is his body, the fulness of him that filleth all in all"}]}]}]},{"title":"Pray for the 7 Point Weekly Kingdom Prayers","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for the 7 Point Weekly Kingdom Prayers","scripture":[],"link":"weekly"}]},{"title":"Pray Specifically for Sunday Services","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray Specifically for Sunday Services","scripture":[{"ref":"Luke 5:17","verses":[{"n":"","text":"And it came to pass on a certain day, as he was teaching, that there were Pharisees and doctors of the law sitting by, which were come out of every town of Galilee, and Judaea, and Jerusalem: and the power of the Lord was present to heal them."}]},{"ref":"John 6:44","verses":[{"n":"","text":"No man can come to me, except the Father which hath sent me draw him: and I will raise him up at the last day."}]},{"ref":"John 12:32","verses":[{"n":"","text":"And I, if I be lifted up from the earth, will draw all men unto me."}]},{"ref":"Acts 20:7","verses":[{"n":"","text":"And upon the first day of the week, when the disciples came together to break bread, Paul preached unto them, ready to depart on the morrow; and continued his speech until midnight."}]},{"ref":"1 Corinthians 16:2","verses":[{"n":"","text":"Upon the first day of the week let every one of you lay by him in store, as God hath prospered him, that there be no gatherings when I come."}]}]}]},{"title":"Pray for the Establishment of New Converts and Members and all God’s Remnant Assembly Family. No Evil Beasts will Harass Them. Let all Evil Beasts Positioned to Harass them be Killed in the Name of Jesus","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for the Establishment of New Converts and Members and all God’s Remnant Assembly Family. No Evil Beasts will Harass Them. Let all Evil Beasts Positioned to Harass them be Killed in the Name of Jesus","scripture":[{"ref":"2 Chronicles 20:20","verses":[{"n":"","text":"And they rose early in the morning, and went forth into the wilderness of Tekoa: and as they went forth, Jehoshaphat stood and said, Hear me, O Judah, and ye inhabitants of Jerusalem; Believe in the Lord your God, so shall ye be established; believe his prophets, so shall ye prosper."}]},{"ref":"John 10:16","verses":[{"n":"","text":"And other sheep I have, which are not of this fold: them also I must bring, and they shall hear my voice; and there shall be one fold, and one shepherd."}]},{"ref":"John 6:10","verses":[{"n":"","text":"And Jesus said, Make the men sit down. Now there was much grass in the place. So the men sat down, in number about five thousand."}]},{"ref":"Psalm 23:1-2","verses":[{"n":"","text":"The Lord is my shepherd; I shall not want. He maketh me to lie down in green pastures: he leadeth me beside the still waters."}]},{"ref":"Ezekiel 34:25","verses":[{"n":"","text":"And I will make with them a covenant of peace, and will cause the evil beasts to cease out of the land: and they shall dwell safely in the wilderness, and sleep in the wood"}]},{"ref":"2 Peter 2:12","verses":[{"n":"","text":"But these, as natural brute beasts, made to be taken and destroyed, speak evil of the things that they understand not; and shall utterly perish in their own corruption."}]}]}]},{"title":"Pray that God will Send and Make All of Us in God’s Remnant Assembly Faithful Men and Women","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray that God will Send and Make All of Us in God’s Remnant Assembly Faithful Men and Women","scripture":[]},{"text":"Men of Valour","scripture":[{"ref":"Joshua 1:14","verses":[{"n":"","text":"Your wives, your little ones, and your cattle, shall remain in the land which Moses gave you on this side Jordan; but ye shall pass before your brethren armed, all the mighty men of valour, and help them."}]},{"ref":"Joshua 10:7","verses":[{"n":"","text":"So Joshua ascended from Gilgal, he, and all the people of war with him, and all the mighty men of valour."}]},{"ref":"Judges 6:12","verses":[{"n":"","text":"And the angel of the Lord appeared unto him, and said unto him, The Lord is with thee, thou mighty man of valour."}]},{"ref":"Judges 11:1","verses":[{"n":"","text":"Now Jephthah the Gileadite was a mighty man of valour, and he was the son of an harlot: and Gilead begat Jephthah."}]},{"ref":"Judges 18:2","verses":[{"n":"","text":"And the children of Dan sent of their family five men from their coasts, men of valour, from Zorah, and from Eshtaol, to spy out the land, and to search it; and they said unto them, Go, search the land: who when they came to mount Ephraim, to the house of Micah, they lodged there."}]}]},{"text":"Men of Substance","scripture":[{"ref":"Psalm 105:21","verses":[{"n":"","text":"He made him lord of his house, and ruler of all his substance:"}]}]},{"text":"Mighty Men, Helpers of the War","scripture":[{"ref":"1 Chronicles 12:1,21","verses":[{"n":"1","text":"Now these are they that came to David to Ziklag, while he yet kept himself close because of Saul the son of Kish: and they were among the mighty men, helpers of the war."},{"n":"21","text":"And they helped David against the band of the rovers: for they were all mighty men of valour, and were captains in the host."}]}]},{"text":"Women of Honor","scripture":[{"ref":"Psalm 45:9","verses":[{"n":"","text":"Kings' daughters were among thy honourable women: upon thy right hand did stand the queen in gold of Ophir."}]},{"ref":"Luke 8:1-2","verses":[{"n":"","text":"And it came to pass afterward, that he went throughout every city and village, preaching and shewing the glad tidings of the kingdom of God: and the twelve were with him, And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils"}]}]},{"text":"Virtuous Women","scripture":[{"ref":"Proverbs 31","verses":[]}]}]},{"title":"Prayer for Tithes and Offering","hideTitle":true,"foundation":[],"prayers":[{"text":"Prayer for Tithes and Offering","scripture":[{"ref":"Malachi 3:10","verses":[{"n":"","text":"Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the Lord of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it."}]},{"ref":"Proverbs 3:9","verses":[{"n":"","text":"Honour the Lord with thy substance, and with the firstfruits of all thine increase:"}]},{"ref":"Zechariah 5:3","verses":[{"n":"","text":"Then said he unto me, This is the curse that goeth forth over the face of the whole earth: for every one that stealeth shall be cut off as on this side according to it; and every one that sweareth shall be cut off as on that side according to it."}]},{"ref":"James 4:12","verses":[{"n":"","text":"There is one lawgiver, who is able to save and to destroy: who art thou that judgest another?"}]},{"ref":"Matthew 5:17","verses":[{"n":"","text":"Think not that I am come to destroy the law, or the prophets: I am not come to destroy, but to fulfil."}]}]}]},{"title":"Pray for GRA Mission Squad Mobilizers and NEXUS","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for GRA Mission Squad Mobilizers and NEXUS","scripture":[{"ref":"Ezekiel 22:30","verses":[{"n":"","text":"And I sought for a man among them, that should make up the hedge, and stand in the gap before me for the land, that I should not destroy it: but I found none."}]},{"ref":"Isaiah 6:8","verses":[{"n":"","text":"Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me."}]},{"ref":"Isaiah 59:16","verses":[{"n":"","text":"\"And he saw that there was no man, and wondered that there was no intercessor: therefore his arm brought salvation unto him; and his righteousness, it sustained him."}]},{"ref":"Matthew 4:19","verses":[{"n":"","text":"And he saith unto them, Follow me, and I will make you fishers of men."}]},{"ref":"Acts 1:8","verses":[{"n":"","text":"But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth."}]},{"ref":"Acts 18:9-11","verses":[{"n":"9","text":"Then spake the Lord to Paul in the night by a vision, Be not afraid, but speak, and hold not thy peace:"},{"n":"10","text":"For I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city."},{"n":"11","text":"And he continued there a year and six months, teaching the word of God among them."}]},{"ref":"John 4:28-29","verses":[{"n":"28","text":"The woman then left her waterpot, and went her way into the city, and saith to the men,"},{"n":"29","text":"Come, see a man, which told me all things that ever I did: is not this the Christ?"}]},{"ref":"John 4:39-42","verses":[{"n":"39","text":"And many of the Samaritans of that city believed on him for the saying of the woman, which testified, He told me all that ever I did."},{"n":"40","text":"So when the Samaritans were come unto him, they besought him that he would tarry with them: and he abode there two days."},{"n":"41","text":"And many more believed because of his own word;"},{"n":"42","text":"And said unto the woman, Now we believe, not because of thy saying: for we have heard him ourselves, and know that this is indeed the Christ, the Saviour of the world."}]},{"ref":"Acts 16:5","verses":[{"n":"","text":"And so were the churches established in the faith, and increased in number daily."}]},{"ref":"Acts 16:14, 17","verses":[{"n":"14","text":"And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."},{"n":"17","text":"The same followed Paul and us, and cried, saying, These men are the servants of the most high God, which shew unto us the way of salvation."}]}]}]},{"title":"Pray for GRA Families","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for GRA Families","scripture":[{"ref":"Jeremiah 31:1","verses":[{"n":"","text":"At the same time, saith the Lord, will I be the God of all the families of Israel, and they shall be my people."}]},{"ref":"Ephesians 3:14-15","verses":[{"n":"14","text":"\"For this cause I bow my knees unto the Father of our Lord Jesus Christ,"},{"n":"15","text":"Of whom the whole family in heaven and earth is named."}]}]}]},{"title":"Receiving The Blessing of Fatherhood","hideTitle":true,"foundation":[],"prayers":[{"text":"Receiving The Blessing of Fatherhood","scripture":[{"ref":"Genesis 49:26","verses":[{"n":"","text":"The blessings of thy father have prevailed above the blessings of my progenitors unto the utmost bound of the everlasting hills: they shall be on the head of Joseph, and on the crown of the head of him that was separate from his brethren."}]},{"ref":"1 Corinthians 4:15","verses":[{"n":"","text":"For though ye have ten thousand instructors in Christ, yet have ye not many fathers: for in Christ Jesus I have begotten you through the gospel."}]},{"ref":"1 Kings 3:6","verses":[{"n":"","text":"And Solomon said, Thou hast shewed unto thy servant David my father great mercy, according as he walked before thee in truth, and in righteousness, and in uprightness of heart with thee; and thou hast kept for him this great kindness, that thou hast given him a son to sit on his throne, as it is this day."}]}]}]}]},{"label":"Prayer Watch THREE","title":"THIRD PRAYER WATCH","subtitle":"","sections":[{"title":"Thank God for GRA Media, Satellite & Mass Communication","hideTitle":true,"foundation":[],"prayers":[{"text":"Thank God for GRA Media, Satellite & Mass Communication","scripture":[{"ref":"Micah 1:8","verses":[{"n":"","text":"Therefore I will wail and howl, I will go stripped and naked: I will make a lamentation like the dragons, and mourning as the owls."}]},{"ref":"Micah 3:8","verses":[{"n":"","text":"But truly I am full of power by the spirit of the Lord, and of judgment, and of might, to declare unto Jacob his transgression, and to Israel his sin."}]}]}]},{"title":"Thank God for the Supernatural Gathering of the Remnants","hideTitle":true,"foundation":[],"prayers":[{"text":"Thank God for the Supernatural Gathering of the Remnants","scripture":[{"ref":"Micah 2:12-13","verses":[{"n":"12","text":"I will surely assemble, O Jacob, all of thee; I will surely gather the remnant of Israel; I will put them together as the sheep of Bozrah, as the flock in the midst of their fold: they shall make great noise by reason of the multitude of men.\""},{"n":"13","text":"The breaker is come up before them: they have broken up, and have passed through the gate, and are gone out by it: and their king shall pass before them, and the Lord on the head of them."}]},{"ref":"Micah 4:6-8","verses":[{"n":"6","text":"In that day, saith the Lord, will I assemble her that halteth, and I will gather her that is driven out, and her that I have afflicted"},{"n":"7","text":"And I will make her that halted a remnant, and her that was cast far off a strong nation: and the Lord shall reign over them in mount Zion from henceforth, even for ever."},{"n":"8","text":"And thou, O tower of the flock, the strong hold of the daughter of Zion, unto thee shall it come, even the first dominion; the kingdom shall come to the daughter of Jerusalem."}]}]}]},{"title":"Thanking God for GRA Mega Finances","hideTitle":true,"foundation":[],"prayers":[{"text":"Thanking God for GRA Mega Finances","scripture":[{"ref":"Micah 4:13","verses":[{"n":"","text":"Arise and thresh, O daughter of Zion: for I will make thine horn iron, and I will make thy hoofs brass: and thou shalt beat in pieces many people: and I will consecrate their gain unto the Lord, and their substance unto the Lord of the whole earth"}]},{"ref":"Isaiah 45:1-3, 14","verses":[{"n":"1","text":"Thus saith the Lord to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him; and I will loose the loins of kings, to open before him the two leaved gates; and the gates shall not be shut;\""},{"n":"2","text":"I will go before thee, and make the crooked places straight: I will break in pieces the gates of brass, and cut in sunder the bars of iron:\""},{"n":"3","text":"And I will give thee the treasures of darkness, and hidden riches of secret places, that thou mayest know that I, the Lord, which call thee by thy name, am the God of Israel.\""},{"n":"14","text":"Thus saith the Lord, The labour of Egypt, and merchandise of Ethiopia and of the Sabeans, men of stature, shall come over unto thee, and they shall be thine: they shall come after thee; in chains they shall come over, and they shall fall down unto thee, they shall make supplication unto thee, saying, Surely God is in thee; and there is none else, there is no God.\""}]},{"ref":"Zechariah 1:17","verses":[{"n":"","text":"Cry yet, saying, Thus saith the Lord of hosts; My cities through prosperity shall yet be spread abroad; and the Lord shall yet comfort Zion, and shall yet choose Jerusalem."}]}]}]},{"title":"Thanking God for GRA Perfect Walk with God/ Spiritual Life","hideTitle":true,"foundation":[],"prayers":[{"text":"Thanking God for GRA Perfect Walk with God/ Spiritual Life","scripture":[{"ref":"Micah 6:8","verses":[{"n":"","text":"He hath shewed thee, O man, what is good; and what doth the Lord require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?"}]},{"ref":"Zephaniah 3:5","verses":[{"n":"","text":"\"The just Lord is in the midst thereof; he will not do iniquity: every morning doth he bring his judgment to light, he faileth not; but the unjust know no shame."}]}]}]},{"title":"Thanking God for Continuous Grace to Reach the Unreached Nations","hideTitle":true,"foundation":[],"prayers":[{"text":"Thanking God for Continuous Grace to Reach the Unreached Nations","scripture":[{"ref":"Micah 5:7-12","verses":[{"n":"7","text":"And the remnant of Jacob shall be in the midst of many people as a dew from the Lord, as the showers upon the grass, that tarrieth not for man, nor waiteth for the sons of men."},{"n":"8","text":"And the remnant of Jacob shall be among the Gentiles in the midst of many people as a lion among the beasts of the forest, as a young lion among the flocks of sheep: who, if he go through, both treadeth down and teareth in pieces, and none can deliver."},{"n":"9","text":"Thine hand shall be lifted up upon thine adversaries, and all thine enemies shall be cut off.\""},{"n":"10","text":"And it shall come to pass in that day, saith the Lord, that I will cut off thy horses out of the midst of thee, and I will destroy thy chariots"},{"n":"11","text":"And I will cut off the cities of thy land, and throw down all thy strong holds"},{"n":"12","text":"And I will cut off witchcrafts out of thine hand; and thou shalt have no more soothsayers"}]}]}]},{"title":"Thanking God for God’s Sure Mercies of David upon God’s Remnant Assembly","hideTitle":true,"foundation":[],"prayers":[{"text":"Thanking God for God’s Sure Mercies of David upon God’s Remnant Assembly","scripture":[{"ref":"2 Chronicles 6:42","verses":[{"n":"","text":"O Lord God, turn not away the face of thine anointed: remember the mercies of David thy servant."}]},{"ref":"Isaiah 55:3","verses":[{"n":"","text":"Incline your ear, and come unto me: hear, and your soul shall live; and I will make an everlasting covenant with you, even the sure mercies of David."}]},{"ref":"Psalm 89:23","verses":[{"n":"","text":"My mercy will I keep for him for evermore, and my covenant shall stand fast with him."}]},{"ref":"Micah 7:18-20","verses":[{"n":"17","text":"Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in mercy."},{"n":"18","text":"He will turn again, he will have compassion upon us; he will subdue our iniquities; and thou wilt cast all their sins into the depths of the sea."},{"n":"20","text":"Thou wilt perform the truth to Jacob, and the mercy to Abraham, which thou hast sworn unto our fathers from the days of old."}]},{"ref":"Acts 13:34","verses":[{"n":"","text":"And as concerning that he raised him up from the dead, now no more to return to corruption, he said on this wise, I will give you the sure mercies of David."}]}]}]},{"title":"Thank God for Making GRA to Rule in the Midst of Our Enemies","hideTitle":true,"foundation":[],"prayers":[{"text":"Thank God for Making GRA to Rule in the Midst of Our Enemies","scripture":[{"ref":"Psalm 110:1-2","verses":[{"n":"","text":"The LORD said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool. The LORD shall send the rod of thy strength out of Zion: Rule thou in the midst of thine enemies."}]},{"ref":"Micah 4:10","verses":[{"n":"","text":"Be in pain, and labour to bring forth, O daughter of Zion, like a woman in travail: for now shalt thou go forth out of the city, and thou shalt dwell in the field, and thou shalt go even to Babylon; there shalt thou be delivered; there the Lord shall redeem thee from the hand of thine enemies."}]}]}]},{"title":"Pray for the 7 Point Weekly Kingdom Prayers","hideTitle":true,"foundation":[],"prayers":[{"text":"Pray for the 7 Point Weekly Kingdom Prayers","scripture":[],"link":"weekly"}]}]},{"label":"Prayer Lists","title":"PRAYER LISTS","subtitle":"States, nations and ministries to pray over by name","sections":[{"title":"U.S. States & Capitals","foundation":[],"prayers":[],"kind":"list","list":[{"name":"Alabama","sub":"Montgomery","group":""},{"name":"Alaska","sub":"Juneau","group":""},{"name":"Arizona","sub":"Phoenix","group":""},{"name":"Arkansas","sub":"Little Rock","group":""},{"name":"California","sub":"Sacramento","group":""},{"name":"Colorado","sub":"Denver","group":""},{"name":"Connecticut","sub":"Hartford","group":""},{"name":"Delaware","sub":"Dover","group":""},{"name":"District of Columbia","sub":"","group":""},{"name":"Florida","sub":"Tallahassee","group":""},{"name":"Georgia","sub":"Atlanta","group":""},{"name":"Hawaii","sub":"Honolulu","group":""},{"name":"Idaho","sub":"Boise","group":""},{"name":"Illinois","sub":"Springfield","group":""},{"name":"Indiana","sub":"Indianapolis","group":""},{"name":"Iowa","sub":"Des Moines","group":""},{"name":"Kansas","sub":"Topeka","group":""},{"name":"Kentucky","sub":"Frankfort","group":""},{"name":"Louisiana","sub":"Baton Rouge","group":""},{"name":"Maine","sub":"Augusta","group":""},{"name":"Maryland","sub":"Annapolis","group":""},{"name":"Massachusetts","sub":"Boston","group":""},{"name":"Michigan","sub":"Lansing","group":""},{"name":"Minnesota","sub":"St. Paul","group":""},{"name":"Mississippi","sub":"Jackson","group":""},{"name":"Missouri","sub":"Jef